window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-cirurgia-cir-2"]={"block":"medcurso:medcurso-cirurgia-cir-2","label":"Medcurso · CIR 2","count":391,"questions":[{"id":"medcurso-cirurgia-cir-2-343822","number":"343822","sourceNumber":"343822","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Qual dos seguintes é o fator mais importante na taxa de contração das feridas?","options":{"A":"Concentração de colágeno.","B":"Concentração de fibrina.","C":"Concentração de substância fundamental.","D":"Quantidade de miofibroblastos."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-343823","number":"343823","sourceNumber":"343823","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Na execução de um curativo, sobre uma ferida, segundo as regras clássicas:","options":{"A":"Deve-se colocar pomada anti-inflamatória.","B":"Deve-se colocar pomada antibiótica.","C":"Deve-se manter a ferida limpa.","D":"A e B estão corretas."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-343833","number":"343833","sourceNumber":"343833","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O rastreamento do câncer de próstata é recomendado, segundo a Sociedade Brasileira\nde Urologia, a todos os homens a partir dos 50\nanos. No entanto, os homens que apresentam fator\nde risco para câncer de próstata, devem iniciar o rastreamento a partir de qual idade?","options":{"A":"35 anos.","B":"42 anos.","C":"45 anos.","D":"47 anos."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-291769","number":"291769","sourceNumber":"291769","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo masculino, 30 anos de idade, é trazido por populares à Unidade de\nPronto Atendimento,UPA, após queimadura por combustão\npor álcool há 30 minutos. Ao exame, A:\nVia aérea pérvia, colocado colar cervical, SatO2: 96% em ar ambiente; B: murmúrios vesiculares\nbem distribuídos e sem ruídos adventícios, FR: 20ipm; C: Bulhas rítmicas e normofonéticas, FC:\n92bpm, PA: 116x78mmHg, abdome indolor à palpação, pelve estável e toque retal sem alterações;\nD: escala de coma de Glasgow = 15, pupilas isocóricas e fotorreagentes; E: feridas de queimadura\nde segundo grau em região anterior do tronco e anterior dos membro superiores. Indique,\nrepectivamente, a estimativa da porcentagem da superfície corpórea queimada e a velocidade de\ninfusão da solução cristaloide nas primeiras horas, de acordo com o protocolo do ATLS 10ª edição,\nconsiderando que o peso do paciente é 60kg.","options":{"A":"18% e 135mL/h","B":"27% e 405mL/h","C":"18% e 270mL/h","D":"27% e 202mL/h"},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-291770","number":"291770","sourceNumber":"291770","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo masculino, 30 anos de idade, é trazido por populares à Unidade de\nPronto Atendimento,UPA, após queimadura por combustão\npor álcool há 30 minutos. Ao exame, A:\nVia aérea pérvia, colocado colar cervical, SatO2: 96% em ar ambiente; B: murmúrios vesiculares\nbem distribuídos e sem ruídos adventícios, FR: 20ipm; C: Bulhas rítmicas e normofonéticas, FC:\n92bpm, PA: 116x78mmHg, abdome indolor à palpação, pelve estável e toque retal sem alterações;\nD: escala de coma de Glasgow = 15, pupilas isocóricas e fotorreagentes; E: feridas de queimadura\nde segundo grau em região anterior do tronco e anterior dos membro superiores. Indique o\ntratamento imediato mais adequado para as feridas das queimaduras.","options":{"A":"Realizar curativo com sulfadiazina de prata.","B":"Realizar curativo com neomicina tópica.","C":"Realizar desbridamento com lavagem das feridas e curativo com sulfadiazina de prata.","D":"Realizar desbridamento com lavagem das feridas e curativo com gazes."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-291806","number":"291806","sourceNumber":"291806","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Homem, 62 anos de idade, comparece à Unidade Básica de Saúde, UBS, pois deseja\nfazer avaliação para neoplasia de próstata, após\ncolega de trabalho ter tido a doença. Relata que\nacorda, eventualmente, uma vez à noite para urinar, mas nega outros sintomas. Mantém calibre do\njato urinário normal e nega gotejamento terminal. O paciente é casado, tem vida sexual ativa, sem\nproblemas. Tem antecedentes de uretrite na juventude, tratada com antibióticos. Nega história\nfamiliar de CA de Próstata, embora relate que sua mãe teve câncer de mama. Ex tabagista, tendo\nabandonado o hábito há 20 anos. Carga tabágica prévia: 16 anos/maço. Nega etilismo. Nunca fez\nexames para Cancer de próstata. Indique o principal fator de risco, para neoplasia de próstata, que\nfoi identificado nesse paciente:","options":{"A":"História familiar de neoplasia de mama.","B":"História pregressa de tabagismo.","C":"Antecedentes de uretrite infecciosa.","D":"Vida sexual ativa."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-283326","number":"283326","sourceNumber":"283326","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação à terapia medicamentosa expulsiva para cálculos ureterais, NÃO é\nCORRETO afirmar:","options":{"A":"Tem se mostrado eficaz no tratamento de pacientes com cálculo ureteral que são favoráveis ao\ntratamento conservador.","B":"Deve ser descontinuada se surgirem complicações como: infecção, dor refratária e piora da\nfunção renal.","C":"Uso de ?-bloqueadores (tansulosina) aumenta o índice de expulsão dos cálculos distais menores\nque 5 mm.","D":"Há pouca evidência que a associação de inibidores da PDE5 ou de corticosteroides tenha uma\nação expulsiva adjuvante na combinação com\n?-bloqueadores."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-281158","number":"281158","sourceNumber":"281158","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Principal estímulo para o desencadeamento da resposta endócrina após trauma ou\ncirurgia:","options":{"A":"Estímulos nervosos provenientes da área lesada.","B":"Acidose tecidual.","C":"Bloqueio espinhal.","D":"Hipovolemia pela perda de sangue.","E":"Alteração da temperatura."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-281172","number":"281172","sourceNumber":"281172","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente de 70kg com queimadura de terceiro grau envolvendo 60% da superfície\ncorporal chega ao pronto-socorro três horas após a queimadura. De acordo com a fórmula de\nParkland, que volume de solução cristaloide deve ser infundida nas próximas cinco horas?","options":{"A":"600 ml.","B":"1.000 ml.","C":"2.100 ml.","D":"8.400 ml.","E":"16.800 ml."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-283356","number":"283356","sourceNumber":"283356","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sebastião de 71 anos de idade vai à Unidade Básica de Saúde mais próximo a sua\ncasa no mês de novembro (mês de alusão a\nsaúde do homem), por insistência da sua esposa,\nsolicitando exame de próstata. Relata que apresenta dificuldade para urinar a algum tempo, mas\nque nunca procurou ajuda, perguntando sobre o jato urinário menciona que está cada vez mais\nfraco. Refere ainda dor em região pélvica e coluna lombar. No exame de toque retal apresenta uma\npróstata endurecida. Em relação ao câncer de próstata, qual das alternativas abaixo não está\ncorreta?","options":{"A":"Mais de 95% dos cânceres de próstata são adenocarcinomas. Esse é o segundo tipo de câncer\ncom mais mortes entre os homens.","B":"Fatores de risco incluem: idade, raça negra, e história familiar. História de DST, dieta rica em\ngorduras e baixos níveis de testosterona parecem também estar associados.","C":"As complicações mais comuns desse tumor são: metástases ósseas, linfonodos, pulmão e\nhepáticas, sintomas obstrutivos, hematúria, insuficiência renal, paraplegia e manifestações\nneurológicas.","D":"Os tumores são classificados de acordo com os achados anatomopatológicos da biópsia (escore\nde Gleason). A graduação vai de 2 a 12 e,\nquanto maior for o grau, menos diferenciado e, portanto,\npotencialmente menos agressivo é o tumor."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-251943","number":"251943","sourceNumber":"251943","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Na abordagem e tratamento da nefrolitíase, em suas diversas causas, podem ser\nindicadas as seguintes recomendações, EXCETO:","options":{"A":"Suplementação com álcalis.","B":"Uso de diuréticos tiazídicos.","C":"Evitar desidratação e manter ingesta hídrica abundante.","D":"Restrição da ingesta de cálcio na dieta."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-217680","number":"217680","sourceNumber":"217680","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente sexo masculino, 72 anos com tumefação redutível em região inguinal direita\ncom evolução de 3 meses. Ao exame físico\nevidenciou-se hérnia inguinal direita. Qual comorbidade\ncontribui efetivamente para o desenvolvimento de hérnias nessa localização?","options":{"A":"Diabetes mellitus.","B":"Síndrome nefrítica.","C":"Hiperplasia prostática.","D":"Hipertensão arterial."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-217690","number":"217690","sourceNumber":"217690","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Comparados a homens que não apresentam câncer na próstata, a fração livre do PSA\nem homens com câncer na próstata é:","options":{"A":"Igual.","B":"Menor.","C":"Maior.","D":"Indetectável pelos meios diagnósticos atuais."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-183141","number":"183141","sourceNumber":"183141","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação ao suporte nutricional no paciente grave, é INCORRETO afirmar:","options":{"A":"A calorimetria indireta é o método de referência para o cálculo do gasto energético.","B":"O gasto energético diário, usualmente, está em torno de 20 a 30 Kcal/kg (do peso habitual).","C":"A elevação das catecolaminas, no paciente crítico, favorece a gliconeogênese e a glicogenólise.","D":"Observa-se diminuição da captação hepática de glicose (resistência central à insulina) e\nperiférica (resistência periférica à insulina).","E":"A promoção da hiperalimentação no paciente com sepse melhora o prognóstico, haja vista o seu\nestado hipermetabólico."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-183142","number":"183142","sourceNumber":"183142","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"As artérias renais, comumente, se originam da aorta abdominal na:","options":{"A":"12ª vértebra.","B":"1ª vértebra.","C":"2ª vértebra lombar.","D":"3ª vértebra lombar.","E":"4ª vértebra lombar."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-183150","number":"183150","sourceNumber":"183150","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"As artérias testiculares se originam, mais comumente, da (as):","options":{"A":"Artérias renais.","B":"Artérias supra-renais.","C":"Aorta abdominal acima da artéria mesentérica superior.","D":"Aorta abdominal abaixo das artérias renais.","E":"Artérias ilíacas comuns"},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-183162","number":"183162","sourceNumber":"183162","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O sítio linfonodal primário de drenagem do testículo direito são:","options":{"A":"Os linfonodos lombares intercavoaórticos.","B":"Os linfonodos inguinais superficiais direitos.","C":"Os linfonodos inguinais profundos direitos.","D":"Os linfonodos ilíacos comum direitos.","E":"Os linfonodos no hilo renal direito."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-183174","number":"183174","sourceNumber":"183174","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Para preservar a irrigação vascular do ureter, as incisões no peritônio devem ser\nfeitas:","options":{"A":"Medialmente no abdome e lateralmente na pelve.","B":"Lateralmente no abdome e medialmente na pelve.","C":"Sempre medial ao ureter.","D":"Sempre lateral ao ureter.","E":"Diretamente sobre o ureter."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-183204","number":"183204","sourceNumber":"183204","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação à queimadura em crianças, assinale a alternativa INCORRETA.","options":{"A":"Na queimadura extensa ocorre aumento da permeabilidade vascular sistêmica proporcional à\nmagnitude da queimadura que evolui com maior intensidade 24 horas após o evento e persiste por\n48 horas.","B":"Para classificar a extensão da superfície corporal queimada (SCQ), em menores de 15 anos, o\nmelhor método é o diagrama de Lund e Browder.","C":"A reposição volêmica, nas primeiras 24 horas, é fundamental e é imperativa a sondagem vesical\npara controle rigoroso da diurese em criança com queimadura em 20% ou mais de SCQ.","D":"A reposição volêmica após 24 horas segue o Esquema de Carvajal, ou seja, o volume\nadministrado deve ser reduzido em 25% em relação ao volume das primeiras 24 horas.","E":"Albumina Humana 1 a 2 G/Kg/dia deve ser indicada em todos os pacientes com SCQ maior que\n20% após as primeiras 24 horas, porque, a\npartir de então, a permeabilidade capilar já está melhor\ne permite que a albumina volte a exercer pressão coloidosmótica."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-182636","number":"182636","sourceNumber":"182636","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente de 65 anos com Adenocarcinoma de próstata, escore de Gleason 6 (3+3),\nPSA = 7 ng/ml e que ao toque retal\napresenta-se com tumor confinado à mesma (T1C) poderá ser\nsubmetido a qual conduta?","options":{"A":"Radioterapia da próstata.","B":"Orquiectomia bilateral.","C":"Prostatectomia radical.","D":"As alternativas a e c estão corretas."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-182641","number":"182641","sourceNumber":"182641","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente jovem possui cálculo radiopaco de 1,7 cm em cálice superior de rim esquerdo.\nRelata dor lombar esporádica do mesmo lado,\nsem hidronefrose. Para o caso em questão, e dentro\ndas alternativas abaixo, qual tratamento oferece a maior porcentagem de pacientes livres de\ncálculos?","options":{"A":"Nefrolitotripsia percutânea.","B":"Colocação de cateter duplo J.","C":"Ureterorrenolitotripsia.","D":"Litotripsia extra-corpórea por ondas de choque (LECO)."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-182646","number":"182646","sourceNumber":"182646","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação aos tumores de bexiga, assinale a afirmativa CORRETA:","options":{"A":"Acometem mais mulheres do que os homens.","B":"A recidiva está relacionada ao número e grau das lesões.","C":"Na sua maioria já são avançados no momento do diagnóstico.","D":"A citologia oncótica tem alta sensibilidade para tumores superficiais."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-159091","number":"159091","sourceNumber":"159091","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente de 74 anos possui cálculo radiopaco observado na radiografia de abdome, de\n1,9 cm em cálice superior de rim esquerdo. Relata dor lombar esporádica do mesmo lado, sem\nhidronefrose, sem febre ou outros sintomas. Das alternativas possíveis qual o melhor tratamento\npara esse caso?","options":{"A":"Nefrolitotripsia percutânea.","B":"Colocação de cateter duplo J.","C":"Ureterorrenolitotripsia.","D":"Litotripsia extra-corpórea por ondas de choque (LECO)."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-159096","number":"159096","sourceNumber":"159096","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação à hiperplasia prostática benigna, marque a alternativa INCORRETA:","options":{"A":"A maior forma de andrôgenio encontrada na próstata é a dihidrotestosterona.","B":"Estudos em material de autópsia demonstram que a partir dos 35-40 anos inicia-se o\ncrescimento microscópico da próstata.","C":"Sintomas de LUTS ou STUB são específicos de hiperplasia prostática.","D":"Castração de homens idosos inibe o aumento do volume prostático."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-159117","number":"159117","sourceNumber":"159117","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação às queimaduras de 3° grau, marque a assertiva verdadeira:","options":{"A":"São muito dolorosas e de aspecto marmóreo.","B":"A gravidade é mais relacionada com a profundidade que com a extensão.","C":"São indolores mas sangram facilmente à manipulação.","D":"Quando circulares em membros podem levar à Síndrome compartimental."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-108665","number":"108665","sourceNumber":"108665","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Marque a alternativa correta sobre hérnia inguinal na infância:","options":{"A":"No exame físico habitualmente utilizamos a manobra semiológica que consiste em introduzir o\ndedo indicador no canal inguinal do paciente;","B":"Nas crianças pequenas o risco de complicação é maior;","C":"O lado esquerdo é mais acometido;","D":"40% dos casos é bilateral."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-108674","number":"108674","sourceNumber":"108674","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Qual das seguintes associações tem indicação cirúrgica mais urgente pelo risco e\ngravidade das complicações?","options":{"A":"Criptorquidia em criança de 7 anos;","B":"Hérnia inguinal esquerda em lactente de 3 meses;","C":"Hidrocele em criança de 5 anos;","D":"Fimose em lactente de 9 meses."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-108757","number":"108757","sourceNumber":"108757","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente foi submetido à hernioplastia inguinal à Linchtenstein, foi utilizado\ncefazolina 1g IV imediatamente antes do\nbloqueio anestésico. No retorno ambulatorial apresenta\numa equimose extensa em bolsa escrotal. Qual a conduta?","options":{"A":"Reabordagem cirúrgica;","B":"Drenagem com dreno de Penrose;","C":"Solicitar doppler de bolsa escrotal;","D":"Conduta expectante."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-84521","number":"84521","sourceNumber":"84521","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente que recebe terapia com cumarínicos em virtude de cirurgia anterior de\ntroca valvar necessita submeter-se a uma\ngastrectomia em virtude de um adenocarcinoma. Todas\nas medidas abaixo estão corretas, EXCETO:","options":{"A":"O anticoagulante deve ser suspenso 4 a 6 dias antes do procedimento.","B":"Deve-se aguardar que o RNI seja inferior a 1,5.","C":"O uso de vitamina K via oral ou parenteral retorna a protrombina a valores adequados em 24 a\n48 horas.","D":"Para restauração da protrombina a níveis ideais, em caráter de urgência devemos infundir uma\ndose de plasma correspondente a 40 ml/kg de\npeso.","E":"Fatores II, VII, IX, e X, fatores dependentes da vitamina K e diminuídos pela terapia cumarínica,\nestão praticamente estáveis em plasma armazenado nos\nbancos de sangue."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-84527","number":"84527","sourceNumber":"84527","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O reparo de McVay é uma técnica clássica para o tratamento das hérnias inguinais\ndiretas, indiretas, recidivadas e principalmente\nas hérnias femorais. Seu princípio técnico se baseia\nem:","options":{"A":"Suturar a fáscia ao ligamento inguinal e incisar o ligamento de Cooper.","B":"Suturar o tendão conjunto ao ligamento inguinal e aproximá-lo do ligamento de Cooper.","C":"Suturar a margem da aponeurose do transverso do abdome ao ligamento de Cooper.","D":"Estreitar o anel inguinal interno e suturar a aponeurose do oblíquo externo ao ligamento de\nCooper.","E":"Colocar uma tela de marlex no assoalho do canal inguinal e fixá-la no ligamento de Cooper."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-66978","number":"66978","sourceNumber":"66978","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre hérnia inguinal em crianças, marque a ALTERNATIVA FALSA:","options":{"A":"São sempre indiretas, causadas pela persistência do conduto peritoniovaginal;","B":"O exame físico é diferente do adulto, não sendo indicada a introdução do dedo indicador no anel\ninguinal externo para sua avaliação;","C":"Na maioria das vezes é necessária a realização de reforço de parede posterior através do uso\nde tela sintética;","D":"A cirurgia deve ser indicada precocemente pelo risco de complicações."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-50065","number":"50065","sourceNumber":"50065","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"No preparo pré-operatório, devemos suspender por pelo menos 7 (sete) dias antes da\ncirurgia o uso de:","options":{"A":"Ginco (Ginkgo biloba);","B":"Alho (Allium sativum);","C":"Éfedra (Ephedra sínica);","D":"Kawa-Kawa (Piper methysticum);"},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-50068","number":"50068","sourceNumber":"50068","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação à anestesia raquidiana, podemos afirmar que aumenta a incidência de\ncefaleia pós-punção de dura-máter:","options":{"A":"Deambulação precoce;","B":"Gravidez;","C":"Uso de agulhas de fino calibre;","D":"Quando o paciente é idoso;"},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-37071","number":"37071","sourceNumber":"37071","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Qual é o parâmetro mais importante na avaliação pré-operatória da reserva funcional\nhepática?","options":{"A":"Tempo de protrombina.","B":"Tempo parcial de tromboplastina.","C":"Albuminemia.","D":"Bilirrubinemia.","E":"Transaminases."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-29353","number":"29353","sourceNumber":"29353","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Na maioria dos serviços de cirurgia, a partir da década de noventa, incrementou-se o\nuso de telas de polipropileno no reparo de\nhérnias inguinais. O fator principal foi:","options":{"A":"O aumento no uso desse material ocorreu apenas nos casos de recidiva herniária","B":"O desenvolvimento de técnica de sutura sem tensão, o que diminuiu a taxa de recidiva herniária","C":"Apesar do custo elevado, a baixa taxa de permanência hospitalar compensa","D":"O fato de não haver relatos de rejeição biológicas ao produto","E":"O aumento da oferta do material nos diversos centros médicos"},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-369539","number":"369539","sourceNumber":"369539","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Diante do caso clínico, indique o estágio desta ferida, de acordo com a NPUAP\n(National Pressure Ulcer Advisory Panel):","options":{"A":"Estágio 1.","B":"Estágio 2.","C":"Estágio 3.","D":"Estágio 4."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-369540","number":"369540","sourceNumber":"369540","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo feminino, 75 anos de idade, acamada por sequela de acidente vascular\ncerebral há dois anos, é trazida por\nfamiliares à Unidade de Saúde por apresentar ferida em região\nsacral há seis meses. A filha relata que a paciente não deambula e permanece em decúbito dorsal\na maior parte do tempo. A paciente recebe visitas semanais da Equipe de Saúde da Família, da\nárea, que orienta os cuidados e a troca do curativo da ferida sacral. Ao exame físico, regular\nestado\ngeral, descorada +1/+4, afebril, FC: 62bpm, PA: 108x68mmHg; ausculta cardíaca e respiratória sem\nalterações; ferida em região sacral medindo cerca de 10cm, com exposição de musculatura glútea,\npresença de tecido necrótico sem secreção purulenta ou odor fétido. Indique a orientação mais\nimportante que a família deve receber da Equipe de Saúde Família para evitar a progressão da\nferida sacral:","options":{"A":"Aumentar a ingesta proteica e calórica nas refeições.","B":"Realizar mudança de decúbito de 2 em 2 horas, evitando o decúbito dorsal.","C":"Repor vitaminas com suplementos por via oral.","D":"Realizar a troca das fraldas imediatamente após diurese e dejeções."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-341051","number":"341051","sourceNumber":"341051","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo masculino, 22 anos de idade, trazido por populares à UPA após ser\nvítima de agressão fisica, relata que\nsofreu agressão com um soco na face há cerca de 45 minutos.\nRefere ferimento em pálpebra superior direita com dor e sangramento. Nega outros sintomas. Ao\nexame físico, bom estado geral, lúcido e orientado, presença de ferimento corto-contuso na\npálpebra superior direita, medindo 2,0cm, com exposição da camada interna, sangramento ativo em\npequena quantidade e sem lesão do globo ocular direito. Caso o paciente apresente perda de\nsubstância que impossibilite a síntese primária, identifique a técnica menos adequada para a\nreconstrução da pálpebra:","options":{"A":"Enxerto de pele da pálpebra contralateral.","B":"Retalho cutâneo de sobrancelha.","C":"Retalho cutâneo da pálpebra inferior.","D":"Enxerto de mucosa."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-341052","number":"341052","sourceNumber":"341052","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo masculino, 22 anos de idade, trazido por populares à UPA após ser\nvítima de agressão fisica, relata que\nsofreu agressão com um soco na face há cerca de 45 minutos.\nRefere ferimento em pálpebra superior direita com dor e sangramento. Nega outros sintomas. Ao\nexame físico, bom estado geral, lúcido e orientado, presença de ferimento corto-contuso na\npálpebra superior direita, medindo 2,0cm, com exposição da camada interna, sangramento ativo em\npequena quantidade e sem lesão do globo ocular direito. Caso o paciente apresente perda de\nsubstância de forma relevante e seja realizada a síntese primária, indique a complicação mais\ncomumente observada:","options":{"A":"Lagoftalmo.","B":"Entrópio.","C":"Ptose palpebral.","D":"Diplopia."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-341056","number":"341056","sourceNumber":"341056","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, 20 anos de idade, sexo feminino, sofreu ferimento cortante em mão direita\ncom uma faca, há uma hora. Nega outros\ntraumas. Ao exame físico, bom estado geral, corada, FC:\n78bpm, PA: 118x72mmHg, FR: 16imp; apresenta ferimento cortante em palma da mão direita,\nmedindo cerca de 2cm, linear e sem sangramento ativo. Diante desse caso clínico, em relação à\nfase inflamatória da cicatrização, é correto afirmar:","options":{"A":"A vasodilatação ocorre imediatamente para que os neutrófilos possam migrar para a ferida.","B":"O endotélio não participa dos mecanismos de migração celular.","C":"As plaquetas são ativadas pelo contato com o colágeno do tipo IV.","D":"O fator do complemento C5a não participa da quimiotaxia de neutrófilos."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-341058","number":"341058","sourceNumber":"341058","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, 20 anos de idade, sexo feminino, sofreu ferimento cortante em mão direita\ncom uma faca, há uma hora. Nega outros\ntraumas. Ao exame físico, bom estado geral, corada, FC:\n78bpm, PA: 118x72mmHg, FR: 16imp; apresenta ferimento cortante em palma da mão direita,\nmedindo cerca de 2cm, linear e sem sangramento ativo. Sobre a fase proliferativa da cicatrização,\npode-se afirmar que","options":{"A":"o surgimento dos macrófagos é simultâneo ao dos neutrófilos na ferida.","B":"os linfócitos liberam metaloproteinases que são fundamentais para a remoção do tecido\ndesvitalizado.","C":"a interleucina 4 tem um efeito pró-inflamatório no estímulo à formação do tecido de granulação.","D":"o TGF beta é um potente estimulante da fibroplasia."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-307039","number":"307039","sourceNumber":"307039","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente foi submetido à cirurgia de colectomia total, ampliada para ressecção de tumor\nde cólon direito. A cirurgia teve duração de\ntrês horas e extravasamento de conteúdo fecal para\ncavidade abdominal. No pós-operatório em UTI desenvolveu edema em membros inferiores\nbilateral e bolsa escrotal. Com relação ao estresse cirúrgico, diversos hormônios atuam e regulam a\nresposta do organismo. Indique, dentre estes, o hormônio responsável por promover a retenção\nhídrica que gera o edema:","options":{"A":"Glucagon.","B":"Aldosterona.","C":"Cortisol.","D":"Catecolaminas."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-307040","number":"307040","sourceNumber":"307040","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente foi submetido à cirurgia de colectomia total, ampliada para ressecção de tumor\nde cólon direito. A cirurgia teve duração de\ntrês horas e extravasamento de conteúdo fecal para\ncavidade abdominal. No pós-operatório em UTI desenvolveu edema em membros inferiores\nbilateral e bolsa escrotal. Diante do relato, indique a medida que reduz o efeito da resposta\nmetabólica ao trauma cirúrgico.","options":{"A":"Utilizar afastadores.","B":"Administrar antibióticos via oral.","C":"Utilizar sonda nasogástrica.","D":"Administrar líquidos com carboidratos no pré-operatório."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-307042","number":"307042","sourceNumber":"307042","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo masculino, 67 anos de idade, está acamado devido a quadro de\nAlzheimer progressivo. É diabético, hipertenso e\nex-tabagista. Vinha sendo cuidado em casa pela\nfamília e cuidadores, mas foi internado devido a quadro de covid, há 20 dias. A enfermagem\nsinaliza o aparecimento de lesão ulcerada em nádega direita, com fundo róseo e áreas amareladas;\nsecreção serosa e hiperemia em bordas associada à zona escurecida. Com base no processo de\ncicatrização de feridas, é correto afirmar:","options":{"A":"Na fase inflamatória há uma preponderância de macrófagos e ocorre uma diminuição da\npermeabilidade vascular.","B":"A ferida é considerada crônica quando não cicatriza totalmente, após percorrido um período de 3\nmeses.","C":"A imunossupressão, a hipertensão, o tabagismo, o diabetes e o uso crônico de corticóides\ninterferem no processo de cicatrização.","D":"Ao final do processo de cicatrização, a força tênsil máxima atingida pela área da cicatriz é de\n60% do normal."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-307043","number":"307043","sourceNumber":"307043","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo masculino, 67 anos de idade, está acamado devido a quadro de\nAlzheimer progressivo. É diabético, hipertenso e\nex-tabagista. Vinha sendo cuidado em casa pela\nfamília e cuidadores, mas foi internado devido a quadro de covid, há 20 dias. A enfermagem\nsinaliza o aparecimento de lesão ulcerada em nádega direita, com fundo róseo e áreas amareladas;\nsecreção serosa e hiperemia em bordas associada à zona escurecida. Com relação ao tipo de\nferida encontrada, trata-se de:","options":{"A":"Úlcera por pressão.","B":"Úlcera venosa.","C":"Úlcera de Marjolin.","D":"Úlcera isquêmica."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-307044","number":"307044","sourceNumber":"307044","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo masculino, 67 anos de idade, está acamado devido a quadro de\nAlzheimer progressivo. É diabético, hipertenso e\nex-tabagista. Vinha sendo cuidado em casa pela\nfamília e cuidadores, mas foi internado devido a quadro de covid, há 20 dias. A enfermagem\nsinaliza o aparecimento de lesão ulcerada em nádega direita, com fundo róseo e áreas amareladas;\nsecreção serosa e hiperemia em bordas associada à zona escurecida. Um dos pilares para o\nadequado tratamento desta lesão é fazer","options":{"A":"antibiótico tópico.","B":"ressecção completa com margens de segurança.","C":"debridamento.","D":"antiagregante plaquetário."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-313451","number":"313451","sourceNumber":"313451","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A pieloplastia desmembrada, consagrada por Anderson-Hynes, tem como finalidade a\ncorreção cirúrgica de:","options":{"A":"Estenose da junção ureteropiélica.","B":"Ampliação vesical.","C":"Nefrolitotomia percutânea.","D":"Refluxo vesicoureteral."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-315204","number":"315204","sourceNumber":"315204","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação aos cálculos renais, em sua grande maioria são formados por?","options":{"A":"Cálcio.","B":"Estruvita.","C":"Cistina.","D":"Ácido úrico.","E":"Colesterol."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-283724","number":"283724","sourceNumber":"283724","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo masculino, 30 anos de idade, é trazido por populares à Unidade de\nPronto Atendimento, UPA, após queimadura por\ncombustão por álcool há 30 minutos. Ao exame, A:\nVia aérea pérvia, colocado colar cervical, SatO?: 96% em ar ambiente; B: murmúrios vesiculares\nbem distribuídos e sem ruídos adventícios, FR: 20ipm; C: Bulhas rítmicas e normofonéticas, FC:\n92bpm, PA: 116x78mmHg, abdome indolor à palpitação, pelve estável e toque retal sem\nalterações; D: escala de coma de Glasgow = 15, pupilas isocóricas e fotorreagentes; E: feridas de\nqueimadura de segundo grau em região anterior do tronco e anterior dos membro superiores.\n\nIndique, respectivamente, a estimativa da porcentagem da superfície corpórea queimada e a\nvelocidade de infusão da solução cristaloide nas primeiras horas, de acordo com o protocolo do\nATLS 10ª edição, considerando que o peso do paciente é 60kg.","options":{"A":"18% e 135mL/h","B":"27% e 405mL/h","C":"18% e 270mL/h","D":"27% e 202mL/h"},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-278619","number":"278619","sourceNumber":"278619","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"De acordo com a ASPEN as necessidades calóricas na terapia de nutrição parenteral\nde crianças de 1 a 7 anos, são de:","options":{"A":"90 a 120 Kcal/Kg/dia.","B":"30 a 50 Kcal/Kg/dia.","C":"75 a 90 Kcal/Kg/dia.","D":"85 a 105 Kcal/Kg/dia."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-283725","number":"283725","sourceNumber":"283725","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo masculino, 30 anos de idade, é trazido por populares à Unidade de\nPronto Atendimento, UPA, após queimadura por\ncombustão por álcool há 30 minutos. Ao exame, A:\nVia aérea pérvia, colocado colar cervical, SatO?: 96% em ar ambiente; B: murmúrios vesiculares\nbem distribuídos e sem ruídos adventícios, FR: 20ipm; C: Bulhas rítmicas e normofonéticas, FC:\n92bpm, PA: 116x78mmHg, abdome indolor à palpitação, pelve estável e toque retal sem\nalterações; D: escala de coma de Glasgow = 15, pupilas isocóricas e fotorreagentes; E: feridas de\nqueimadura de segundo grau em região anterior do tronco e anterior dos membro superiores.\n\nIndique o tratamento imediato mais adequado para as feridas das queimaduras.","options":{"A":"Realizar curativo com sulfadiazina de prata.","B":"Realizar curativo com neomicina tópica.","C":"Realizar desbridamento com lavagem das feridas e curativo com sulfadiazina de prata.","D":"Realizar desbridamento com lavagem das feridas e curativo com gazes."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-283726","number":"283726","sourceNumber":"283726","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo masculino, 30 anos de idade, é trazido por populares à Unidade de\nPronto Atendimento, UPA, após queimadura por\ncombustão por álcool há 30 minutos. Ao exame, A:\nVia aérea pérvia, colocado colar cervical, SatO?: 96% em ar ambiente; B: murmúrios vesiculares\nbem distribuídos e sem ruídos adventícios, FR: 20ipm; C: Bulhas rítmicas e normofonéticas, FC:\n92bpm, PA: 116x78mmHg, abdome indolor à palpitação, pelve estável e toque retal sem\nalterações; D: escala de coma de Glasgow = 15, pupilas isocóricas e fotorreagentes; E: feridas de\nqueimadura de segundo grau em região anterior do tronco e anterior dos membro superiores.\n\nDetermine o tratamento cirúrgico, mais adequado, caso as feridas não evoluam com reepitelização\ncom a realização de curativos.","options":{"A":"Realizar enxertos de pele total.","B":"Realizar retalhos cutâneos.","C":"Realizar enxertos de pele parcial em lâmina.","D":"Realizar enxertos de pele parcial em malha."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-280414","number":"280414","sourceNumber":"280414","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O tratamento farmacológico da urolitíase é dirigido aos pacientes com diagnóstico\nmetabólico estabelecido. Esse tratamento deve ser\nsempre aliado ao não farmacológico. As\nprincipais alterações metabólicas encontradas no paciente pediátrico são todas as abaixo, exceto:","options":{"A":"Hipercalciúria idiopática.","B":"Baixa ingestão de sódio.","C":"Baixo volume urinário.","D":"Hipocitratúria idiopática."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-280421","number":"280421","sourceNumber":"280421","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Assinale a alternativa correta em relação à Nutrição Parenteral.","options":{"A":"Só deve ser realizada se o trato gastrointestinal não for funcionante.","B":"A nutrição parenteral é uma terapia nutricional utilizada em casos restritos, pois não é possível\npromover crescimento adequado em crianças.","C":"O controle glicêmico diário faz-se necessário para o ajuste diário da oferta energética e para\ncontrole da hiper e/ou hipoglicemias.","D":"A nutrição parenteral periférica é contra indicada em pacientes pediátricos."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-278106","number":"278106","sourceNumber":"278106","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente masculino de 34 anos comparece em consulta na atenção básica\nqueixando-se de dor abdominal em cólicas há 5\nou 6 anos (não sabe precisar). Há alguns meses\n\napresentou piora das dores, classificando-a como em cólicas, de forte intensidade, com duração de\naproximadamente 10 minutos, associada a náuseas e vômitos no momento da dor. Nega febre.\n\nQueixa-se de irradiação para região testicular direita. No momento não tem queixas urinárias, mas\ndurante o último ano apresentou 3 infecções urinárias não complicadas. Nega comorbidades. Ao\nexame físico: bom estado geral, corado, hidratado. Sem alterações cardiopulmonares. Abdome com\nruídos, flácido, indolor, sem sinais de visceromegalias ou peritonite. Punho percussão de loja renal\ndireita duvidosa. Traz uma radiografia de abdome simples. A principal hipótese diagnóstica é:","options":{"A":"Estenose de junção ureteropiélica (JUP).","B":"Pielonefrite aguda.","C":"Cálculo coraliforme.","D":"Ureterolitíase distal."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-2/278106.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-278637","number":"278637","sourceNumber":"278637","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"São fatores que não inibem a cicatrização de feridas:","options":{"A":"Infecção.","B":"Radiação ionizante.","C":"Glicocorticoesteróides.","D":"Vasodilatação."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-278640","number":"278640","sourceNumber":"278640","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"De acordo com o INCA (Instituto Nacional do Câncer), assinale a alternativa CORRETA\nsobre o câncer de próstata:","options":{"A":"No Brasil, o câncer de próstata é o segundo mais comum entre os homens (atrás apenas do\ncâncer de pele melanoma).","B":"A idade é um fator de risco importante, uma vez que tanto a incidência quanto a mortalidade\naumentam significativamente após os 50 anos.","C":"Excesso de gordura corporal não tem relação com o aumento do risco de câncer de próstata\navançado.","D":"Para doença localizada e restrita à próstata, a cirurgia é mandatória, visando redução da\npossibilidade de metástase óssea."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-278118","number":"278118","sourceNumber":"278118","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Os cálculos coraliformes são cálculos renais ramificados que se amoldam aos\ncontornos do sistema coletor e ocupam mais de\numa porção dos mesmos. Podem se associar a\ninfecções urinárias de repetição. A melhor opção terapêutica para este tipo de cálculo é:","options":{"A":"Litotripsia extracorpórea.","B":"Ureterolitotripsia endoscópica.","C":"Nefrolitotripsia percutânea.","D":"Nefrectomia parcial."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-252900","number":"252900","sourceNumber":"252900","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente do sexo masculino, 70 anos de idade, é levado por familiares ao Pronto\nSocorro com queixa de dor em hipogástrio há\nduas horas, que vem piorando. O paciente relata\ntambém esforço excessivo para iniciar a micção, gotejamento pós-miccional e diminuição do jato\nurinário há alguns meses. Nega comorbidades ou uso de medicamentos. Ao exame físico, bom\nestado geral; ausculta cardíaca e respiratória sem alterações; abdome distendido em hipogástrio\ncom dor à palpação, sem sinais de irritação peritoneal; toque retal com próstata medindo cerca de 5\npolpas digitais e sem lesões tocáveis ou sangue em dedo de luva. De acordo com o caso clínico,\nindique a principal suspeita etiológica para a causa que levou o paciente ao Pronto Socorro.","options":{"A":"Infecção urinária.","B":"Litíase urinária.","C":"Hiperplasia prostática benigna.","D":"Bexiga de esforço."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-252901","number":"252901","sourceNumber":"252901","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente do sexo masculino, 70 anos de idade, é levado por familiares ao Pronto\nSocorro com queixa de dor em hipogástrio há\nduas horas, que vem piorando. O paciente relata\ntambém esforço excessivo para iniciar a micção, gotejamento pós-miccional e diminuição do jato\nurinário há alguns meses. Nega comorbidades ou uso de medicamentos. Ao exame físico, bom\nestado geral; ausculta cardíaca e respiratória sem alterações; abdome distendido em hipogástrio\ncom dor à palpação, sem sinais de irritação peritoneal; toque retal com próstata medindo cerca de 5\npolpas digitais e sem lesões tocáveis ou sangue em dedo de luva. Após a avaliação inicial,\ndetermine a conduta mais adequada.","options":{"A":"Solicitar uma ultrassonografia de rins e vias urinárias.","B":"Solicitar exame de urina.","C":"Fazer terapia antibiótica e analgesia.","D":"Realizar sondagem vesical de alívio."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-252902","number":"252902","sourceNumber":"252902","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente do sexo masculino, 70 anos de idade, é levado por familiares ao\n\npronto-socorro com queixa de dor em hipogástrio há duas horas, que vem piorando. O paciente\nrelata também esforço excessivo para iniciar a\nmicção, gotejamento pós-miccional e diminuição do\njato urinário há alguns meses. Nega comorbidades ou uso de medicamentos. Ao exame físico, bom\nestado geral; ausculta cardíaca e respiratória sem alterações; abdome distendido em hipogástrio\ncom dor à palpação, sem sinais de irritação peritoneal; toque retal com próstata medindo cerca de 5\npolpas digitais e sem lesões tocáveis ou sangue em dedo de luva. Supondo que o paciente evolua\ncom quadros de repetição semelhantes ao descrito no caso, indique a conduta mais adequada:","options":{"A":"Profilaxia antibiótica contínua.","B":"Terapia para prevenção de formação de cálculos urinários.","C":"Ressecção transuretral da próstata.","D":"Cirurgia para suspensão da bexiga."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-249411","number":"249411","sourceNumber":"249411","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre cicatrização de feridas, assinale a correta:","options":{"A":"A primeira fase (proliferativa) apresenta-se por intensa transformação de colágeno tipo III em\ncolágeno tipo I, essencial para contratura da ferida.","B":"A função primária do fibroblasto é produção de colágeno tipo I, processo este marcante da\nterceira fase (proliferativa).","C":"A primeira fase (inflamatória) caracteriza-se pelo processo inflamatório local, em que a presença\nde polimorfonucleares junto com macrófagos organizam os\nprocessos de hemostasia, limitam o\ndano tecidual e tentam remover os tecidos necróticos.","D":"Miofibroblastos são as células principais do processo inflamatório da cicatrização. É através\ndeles em que há sinalização para interleucinas\nda fase inflamatória."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-219898","number":"219898","sourceNumber":"219898","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação aos grandes queimados, assinale a alternativa CORRETA:","options":{"A":"As alterações imunológicas são responsáveis pela diminuição da sobrevivência dos homo e\nxenoenxertos.","B":"Níveis circulantes aumentados de catecolaminas estimulam a gliconeogênese e a perda\nproteica.","C":"O paciente deve ser colocado em ambiente com temperaturas mais baixas para diminuir a razão\nmetabólica.","D":"Ocorre aumento da atividade quimiotáxica dos polimorfonucleares."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-215269","number":"215269","sourceNumber":"215269","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O Nutrition Risk in Critically Ill (NUTRIC) é o primeiro escore validado para identificar\npacientes críticos que tendem a se beneficiar\nde uma terapia nutricional agressiva. Suas variáveis\nde controle são todas as abaixo, EXCETO:","options":{"A":"APACHE II.","B":"SOFA.","C":"Índice de Massa corpórea.","D":"Números de comorbidades."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-215475","number":"215475","sourceNumber":"215475","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação às cistostomias.","options":{"A":"Consiste na colocação de um cateter que alcança a bexiga pela região pré-vesical.","B":"Trata-se de derivação urinária externa entubada.","C":"As cistostomias temporárias colocadas através de incisões suprapúbicas são empregadas para\nprevenir fístulas e obstruções do trato urinário após operações que envolvem a bexiga, como\nprostatectomias, ampliações vesicais, correções de incontinência urinária e de traumas.","D":"As cistostomias definitivas são procedimentos rotineiros em serviços de emergência para o\ntratamento de retenção urinária decorrente de obstruções prostáticas ou uretrais, nas quais não se\nconsegue cateterismo uretral."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-215519","number":"215519","sourceNumber":"215519","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre a nutrição em pacientes com insuficiência hepática, é INCORRETO que:","options":{"A":"Pacientes que possuem varizes esofágicas não devem ser submetidos à sondagem\nnasogástrica sem visualização direta.","B":"Pacientes com insuficiência hepática fulminante apresentam com frequência carência de\nvitaminas hidrossolúveis.","C":"A terapia nutricional está indicada em pacientes desnutridos moderados quando a ingesta oral\nfor inferior a 60%.","D":"A desnutrição é um fator de risco independente para mortalidade em pacientes com cirrose\nhepática."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-216254","number":"216254","sourceNumber":"216254","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Durante a avaliação do doente queimado, os indicadores de lesão por inalação incluem\nos seguintes itens, EXCETO","options":{"A":"rouquidão.","B":"níveis sanguíneos de carboxi-hemoglobina maiores que 1,5% em indivíduos previamente sadios\nou acima de 5% em fumantes.","C":"queimaduras faciais e/ou cervicais.","D":"chamuscamento dos cílios e das vibrissas nasais."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-215223","number":"215223","sourceNumber":"215223","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação à duplicidade pieloureteral, assinale a alternativa INCORRETA.","options":{"A":"A duplicidade pieloureteral é uma das anomalias mais raras do trato urinário, e os segmentos\nrenais associados e as vias excretoras são\ndisfuncionais na maioria dos pacientes.","B":"A duplicidade ureteral pode ser uni ou bilateral, completa ou incompleta.","C":"As anomalias associadas à duplicidade ureteral completa incluem ureterocele e ectopia ureteral,\no que dependerá dos eventos embriológicos.","D":"A duplicidade ureteral está associada a sinais clínicos de uropatia obstrutiva (duplicidade,\nureterocele), infecção urinária (refluxo\nvesicoureteral) e incontinência urinária (ectopia ureteral)."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-212222","number":"212222","sourceNumber":"212222","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Assinale a alternativa correta em relação a queimaduras em crianças.","options":{"A":"A prioridade inicial é a retirada imediata da fonte de calor e aplicação do suporte básico de\nvida.\n\nPorém, não se deve resfriar as lesões com água corrente pela maior susceptibilidade a choque\ntérmico.","B":"Devido à superfície corpórea relativamente maior que o peso e maior concentração de água\nextracelular, o risco para desidratação, choque hipovolêmico e insuficiência renal aguda é maior\nque no adulto.","C":"As soluções hipertônicas em infusão rápida podem causar acidose hiponatrêmica e hemorragia\ncerebral em crianças abaixo de 3 anos de idade.","D":"A reparação volêmica para crianças com superfície corpórea queimada abaixo de 15% deve ser\niniciada imediatamente com hidratação venosa.","E":"As infecções são a principal causa de morte, por isso a profilaxia com antibióticos está indicada\nde rotina."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-187744","number":"187744","sourceNumber":"187744","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação aos grandes queimados, assinale alternativa ERRADA:","options":{"A":"A depressão da função imunológica geralmente prolonga a sobrevida dos aloenxertos cutâneos","B":"Deve-se evitar injeções intramusculares ou subcutâneas de narcóticos","C":"Na suspeita de lesões broncopulmonares (inalação) é importante a realização de radiografia de\ntórax para diagnóstico precoce","D":"Reanimação volêmica precoce diminui o risco de insuficiência renal aguda"},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-181351","number":"181351","sourceNumber":"181351","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Dadas as afirmativas em relação às queimaduras, I. A pele pode suportar temperaturas\nde até 44 graus Celsius por várias horas sem\nque haja morte celular. II. Nas queimaduras de\nprimeiro grau há destruição da epiderme sem que haja qualquer alteração na derme. III. Na\nqueimadura de segundo grau é obrigatória a presença de bolhas e seu processo de cura é a\nregeneração. verifica-se que está(ão) correta(s) apenas","options":{"A":"I.","B":"II.","C":"I e II.","D":"I e III.","E":"II e III."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-181369","number":"181369","sourceNumber":"181369","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Dados os itens sobre fatores de risco para o câncer de próstata: I. Negros e idade\navançada. II. Prostatite de repetição e vitamina A. III. Idade avançada e uso de finasterida.\n\nVerifica-se que está(ão) CORRETO(S):","options":{"A":"I, apenas.","B":"III, apenas.","C":"I e II, apenas.","D":"II e III, apenas.","E":"I, II e III."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-180148","number":"180148","sourceNumber":"180148","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Na síndrome compartimental aguda, o achado clínico inicial de maior sensibilidade para\no diagnóstico é a:","options":{"A":"Ausência de pulso distal à lesão","B":"Parestesia","C":"Dor ao estiramento passivo do músculo isquêmico","D":"Palidez da extremidade","E":"Cianose"},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-183609","number":"183609","sourceNumber":"183609","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Segundo a décima edição do ATLS, é INCORRETO afirmar:","options":{"A":"Não há indicação de antibióticos profiláticos no grande queimado.","B":"Crianças recebem hidratação mais vigorosa que os adultos.","C":"De acordo com a regra dos Nove, uma criança que apresenta queimaduras em toda cabeça, e\ntronco anterior e posterior e\n\nmembro superior direito completo tem aproximadamente 58% de superfície corporal queimada.","D":"Uma criança de 12 anos, 35 quilos tem 20% da superfície corporal queimada deve receber 1.400\nml no total, sendo metade nas\n\nprimeiras oito horas e a outra metade em 16 horas."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-183104","number":"183104","sourceNumber":"183104","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com base na fórmula de Parkland, a hidratação nas primeiras 8 horas para um homem\njovem de 70 kg de peso corporal e que\n\napresenta queimaduras em 40% da superfície corporal é","options":{"A":"500mL/h.","B":"600mL/h.","C":"700mL/h.\n\n.","D":"800mL/h."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-158797","number":"158797","sourceNumber":"158797","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre a cicatrização de feridas, é CORRETO afirmar:","options":{"A":"Os neutrófilos e as células endoteliais são as principais células da fase proliferativa.","B":"A característica mais importante da fase de remodelamento é a confecção de tecido de\ngranulação a ser reorganizado.","C":"Isquemia, infecção, corpo estranho, edema, pressão tecidual elevada e tabagismo são fatores\nque influem negativamente\n\nna cicatrização.","D":"Na fase inflamatória, os macrófagos são as primeiras células de defesa a chegar à ferida, com\nmaior concentração 24 horas após a lesão.","E":"O processo de cicatrização em serosas é lento em relação ao da pele. As principais células\nenvolvidas nesse processo são os neutrófilos e fibroblastos."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-161410","number":"161410","sourceNumber":"161410","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"São condições clínicas que exigem uso cauteloso de Nutrição Parenteral, com\nEXCEÇÃO de uma. Aponte-a.","options":{"A":"Ureia > 100 mg/dL.","B":"Osmolalidade do soro > 350 mOsm/kg.","C":"Sódio sérico > 150 mEq/L.","D":"Glicemia < 70 mg/dL."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-161158","number":"161158","sourceNumber":"161158","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A cicatrização de feridas é o esforço dos tecidos lesados para restaurar função e\nestrutura normais após o trauma. Assinale a alternativa INCORRETA em relação a este tema.","options":{"A":"As três fases da ferida são: inflamação, proliferação e maturação.","B":"A fase inflamatória se caracteriza por maior permeabilidade vascular, migração de células para a\nferida por quimiotaxia, secreção de citocinas e fatores de crescimento na ferida.","C":"Os macrófagos induzem apoptose de polimorfonucleares.","D":"TNF liberada por polimorfonucleares e macrófagos encontram-se diminuídos nas feridas\ncrônicas."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-152652","number":"152652","sourceNumber":"152652","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Trauma vascular de artéria poplítea com lesão total com evolução para edema de\nperna, pé equino e perda da sensibilidade, qual o seu diagnóstico provável?","options":{"A":"Síndrome de compartimento.","B":"Fratura.","C":"Edema traumático.","D":"Rotura muscular.","E":"Trombose venosa."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-134303","number":"134303","sourceNumber":"134303","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Quando da necessidade de entubação orotraqueal, existe a necessidade de utilização\ndo laringoscópio, este apresenta diversos tipos de\nlâminas, sendo que ocorrem diferenças de\ntécnicas entre as lâminas retas e curvas relacionadas a","options":{"A":"Posicionamento na epiglote.","B":"Posicionamento da língua.","C":"Posicionamento na lateral da boca.","D":"Técnicas iguais."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-134075","number":"134075","sourceNumber":"134075","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Várias classificações têm sido propostas para quantificar o risco operatório. A respeito\ndisso é CORRETO afirmar que,","options":{"A":"a mais utilizada é a da Sociedade Americana de Anestesiologia (ASA).","B":"ASA I: processo patológico não sistêmico, ausência de alterações fisiológicas, bioquímicas e\npsiquiátricas.","C":"ASA IV: graves doenças sistêmicas, com insuficiências funcionais instaladas, constituindo\nameaça à vida.","D":"Três acima estão certas"},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-134896","number":"134896","sourceNumber":"134896","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Qual das alternativas abaixo apresenta uma contraindicação para a realização de\ncirurgia por videolaparoscopia?","options":{"A":"Problemas cardiovasculares graves.","B":"DPOC.","C":"Cirurgia abdominal anterior.","D":"Obesidade mórbida."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-134301","number":"134301","sourceNumber":"134301","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Dos hormônios abaixo relacionados, aponte aquele que se encontra com sua secreção\ndiminuída na fase catabólica do trauma:","options":{"A":"Cortisol.","B":"Insulina.","C":"Glucagon.","D":"Aldosterona."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-134044","number":"134044","sourceNumber":"134044","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente de 58 anos foi submetido à gastrectomia total com linfadenectomia D II\npara tratamento de adenocarcinoma de corpo\ngástrico. O exame anatomopatológico revelou\nmargens microscópicas positiva no duodeno. De acordo com a terminologia adotada para avaliar o\ngrau de doença residual, esta operação foi:","options":{"A":"R0.","B":"R1.","C":"R2.","D":"R4."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-134894","number":"134894","sourceNumber":"134894","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre hérnias inguinais por deslizamento, marque (V) para as afirmações Verdadeiras\nou (F) para as Falsas e, em seguida, assinale\na alternativa contendo a sequência CORRETA. ( )\nFaz-se o reparo do ligamento de Cooper após a redução do saco. ( ) A bexiga e o cólon são os\nprincipais órgãos envolvidos. ( ) Na maioria dos casos são hérnias indiretas.","options":{"A":"V / F / V","B":"F / V / F","C":"F / F / V","D":"V / V / F"},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-134062","number":"134062","sourceNumber":"134062","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Assinale a alternativa que apresente o patógeno mais comum às Infecções em Áreas\nCirúrgicas.","options":{"A":"Enterococcus.","B":"Escherichia coli.","C":"Staphylococcus aureus.","D":"Staphylococcus coagulase negativa."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-134835","number":"134835","sourceNumber":"134835","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Aponte os três fatores fundamentais na ?decisão operatória?:","options":{"A":"A indicação correta, os riscos avaliados e informados, e o momento oportuno.","B":"Os honorários, os riscos avaliados e informados,e o momento oportuno.","C":"A indicação correta, o anestesista e o momento oportuno.","D":"A indicação correta, os riscos avaliados e informados, e a tecnologia disponível."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-134077","number":"134077","sourceNumber":"134077","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"No intraoperatório de um paciente que recebeu grande volume de infusão sanguínea, o\ncirurgião percebe que, por diversos pontos, começam a ?brotar? sangue. Essa hemorragia tem,\nnesse caso, como causas principais:","options":{"A":"Trombocitopenia de diluição, falta de fatores de coagulação, coagulação intravascular\ndisseminada e uremia.","B":"Trombocitopenia de diluição, falta de fatores de coagulação, coagulação intravascular\ndisseminada e reação hemolítica.","C":"Uremia, falta de fatores de coagulação, coagulação intravascular disseminada e reação\nhemolítica.","D":"Existem duas alternativas certas acima."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-134331","number":"134331","sourceNumber":"134331","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Os métodos que podem ser utilizados para reduzir o risco de tromboembolismo em\npacientes que apresentam história clínica de trombose ou embolia prévia são:","options":{"A":"Filtro na cava e elevação dos membros inferiores.","B":"Meias de compressão pneumática e deambulação precoce.","C":"Heparina em baixas doses e posição de Trendelenburg.","D":"Enfaixamento com crepe dos membros inferiores e aspirina oral."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-109969","number":"109969","sourceNumber":"109969","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente do sexo masculino, 53 anos, internado por Infarto Agudo do Miocárdio. Após\ncineangiocoronariografia, foi optado pela cirurgia de revascularização do miocárdio. Paciente em\nuso de Clopidogrel. Com relação ao uso dessa medicação, assinale a alternativa CORRETA.","options":{"A":"Deve ser suspensa sete dias antes do procedimento cirúrgico.","B":"Deve ser suspensa dois dias antes do procedimento cirúrgico.","C":"Deve ser suspensa a dose no dia do procedimento cirúrgico.","D":"Não há necessidade de suspensão para o procedimento cirúrgico."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-110039","number":"110039","sourceNumber":"110039","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Qual das alternativas abaixo apresenta uma contraindicação para a realização de\ncirurgia por videolaparoscopia?","options":{"A":"Problemas cardiovasculares graves.","B":"DPOC.","C":"Cirurgia abdominal anterior.","D":"Obesidade mórbida."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-110000","number":"110000","sourceNumber":"110000","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"São fatores de risco para infecção da ferida operatória, EXCETO:","options":{"A":"Tabagismo.","B":"Diabetes Mellitus.","C":"Uso de curativos oclusivos por mais de 48 horas.","D":"Uso de corticoides."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-110066","number":"110066","sourceNumber":"110066","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Faça a associação entre o procedimento cirúrgico e o antibiótico mais indicado para a\nprofilaxia, e assinale a alternativa CORRETA. 1. Cirurgias Colorretais; 2. Apendicectomia; 3.\n\nTireoidectomia / ( ) cefazolina + metronidazol ;( ) sem antibiótico profilático ; ( ) neomicina +\neritromicina;","options":{"A":"2 / 3 / 1.","B":"2 / 1 / 3.","C":"1 / 2 / 3.","D":"1 / 3 / 2."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-110018","number":"110018","sourceNumber":"110018","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Assinale a alternativa que apresenta uma das principais vantagens da técnica de\nherniorrafia de Lichtenstein:","options":{"A":"Menor índice de orquite isquêmica.","B":"Menor índice de infecção.","C":"Menor índice de recidiva.","D":"Menor índice de lesão do nervo ilioinguinal."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-110022","number":"110022","sourceNumber":"110022","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre hérnias ventrais NÃO é correto afirmar que","options":{"A":"a hérnia mais comum em mulheres é a femural e, nos homens, a inguinal.","B":"o sinal de Howship-Romberg, na hérnia obturadora, indica dor referida acompanhando o nervo\nobturador.","C":"as hérnias lombares ocorrem nos flancos, com mais frequência no triângulo lombar superior\n(Grynfelt) ou inferior (Petit).","D":"todas a afirmativas estão incorretas."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-110025","number":"110025","sourceNumber":"110025","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Assinale a alternativa CORRETA sobre hérnias da parede abdominal.","options":{"A":"O canal inguinal possui um comprimento superior a 10 cm.","B":"Deve-se postergar a correção cirúrgica da hérnia inguinal indireta por até 4 anos.","C":"Grande parte das hérnias umbilicais congênitas fecha em até 2 anos.","D":"Todas as hérnias devem ser tratadas cirurgicamente."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-109738","number":"109738","sourceNumber":"109738","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A Infecção em Área Cirúrgica (IAC) é a infecção hospitalar MAIS comum em nossa\npopulação, e ela pode ocorrer em qualquer momento entre:","options":{"A":"0 a 7 dias após a cirurgia.","B":"0 a 15 dias após a cirurgia.","C":"0 a 21 dias após a cirurgia.","D":"0 a 30 dias após a cirurgia."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-109746","number":"109746","sourceNumber":"109746","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Assinale a alternativa ERRADA.","options":{"A":"Assepsia é o conjunto de procedimentos realizados com o objetivo de manter o paciente e o\nambiente cirúrgico livres de germes.","B":"Antissepsia é a prevenção de infecção pela destruição dos germes.","C":"Degermação é a remoção total ou parcial de microrganismo da pele ou mucosa por meio de\nmétodos físicos ou químicos.","D":"Todas as alternativas acima estão erradas."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-109749","number":"109749","sourceNumber":"109749","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A Hérnia de Littré é a presença do:","options":{"A":"divertículo de Meckel dentro de uma hérnia da região inguinal ou femoral.","B":"apêndice cecal dentro de uma hérnia da região inguinal ou femoral.","C":"omento dentro de uma hérnia da região inguinal ou femoral.","D":"sigmoide dentro de uma hérnia da região inguinal ou femoral."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-86821","number":"86821","sourceNumber":"86821","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"De acordo com a Sociedade Americana de Anestesiologia, o risco iminente de morte\npós-operatória pode ser estimado pela classificação ASA. Escolha a alternativa incorreta.","options":{"A":"ASA I - paciente sem outra doença, além da cirurgia;","B":"ASA II - comorbidade leve;","C":"ASA III - comorbidade grave incapacitante;","D":"ASA V - paciente moribundo;","E":"ASA VI - morte cerebral."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-86828","number":"86828","sourceNumber":"86828","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Os cuidados com o paciente com diabetes melito incluem:","options":{"A":"Glicemia deve ser mantida acima de 200 mg/dl;","B":"Recomenda-se que a operação eletiva deva ser realizada o mais cedo possível pela manhã;","C":"Nunca devemos usar solução glicosada nestes pacientes;","D":"Os hipoglicemiantes orais devem ser administrados no dia da operação;","E":"A administração de insulina subcutânea é sempre recomendada no peroperatório."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-86791","number":"86791","sourceNumber":"86791","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O uso da heparina de baixo peso molecular deve seguir algumas recomendações,\nexceto:","options":{"A":"Iniciar duas horas após a cirurgia;","B":"Suspender 12 horas antes do procedimento;","C":"Reiniciar somente 12 a 24 horas após o procedimento;","D":"Suspender o uso quando o INR > 1,9;","E":"Pode ser usada realizada em pacientes submetidos à raquianestesia ou anestesia peridural."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-86801","number":"86801","sourceNumber":"86801","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Nas cirurgias limpas e potencialmente contaminadas recomenda-se o uso de\nantibioticoprofilaxia nas seguintes situações, exceto:","options":{"A":"Pacientes acima de 70 anos;","B":"Desnutridos;","C":"Hernioplastia incisional;","D":"Implantes de órteses ou telas;","E":"Hernioplastia umbilical."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-86653","number":"86653","sourceNumber":"86653","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Qual o parâmetro clínico mais precoce na indicação de reoperação de um paciente\nsubmetido à cirurgia bariátrica?","options":{"A":"Irritação peritoneal.","B":"Dor abdominal.","C":"Hematúria.","D":"Taquidispneia.","E":"Parada de eliminação de flatos e fezes."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-158419","number":"158419","sourceNumber":"158419","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação a resposta endócrino metabólica ao trauma, assinale a resposta\nINCORRETA:","options":{"A":"O ato operatório promove inevitável lesão de tecidos, mas este pode ser reduzida a menor\nexpressão possível.","B":"A técnica operatória possui destaque e preponderância neste objetivo.","C":"Os princípios de técnica cirúrgica devem estar sempre presentes e o cirurgião deve se submeter\na constante disciplina e devoção em cada detalhe\nnas intervenções que realizar e desenvolver\nesforços contínuos na obtenção de conhecimento.","D":"Pequenos detalhes repetidos com consciência se somarão ao final da operação e se traduzirão\nem sucesso e vantagem para o paciente.","E":"O bisturi elétrico é importante recurso tecnológico e assim seu emprego não precisa ser\ncriterioso uma vez que a forma de seu uso não interfere na resposta ao ato cirúrgico."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-158412","number":"158412","sourceNumber":"158412","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação à litíase urinaria, marque a alternativa CORRETA:","options":{"A":"Nefrolitotripsia percutânea representa a primeira escolha para tratamento de cálculos ureterais\ndistais.","B":"Ureterorrenolitotripsia rigida a laser representa a melhor opção para tratamento de cálculos\ncoraliformes complexos.","C":"A litotripsia extra corpórea (LECO) representa a primeira opção para tratamento de cálculos com\ndensidades maiores que 1000 UH, distância pele-pedra maior que 10 cm, bem como em pacientes\ngravidas.","D":"As complicações como perfuração ureteral e estenose ureteral estão abaixo de 2% dos casos. A\navulsão ureteral ocorre em menos de 1%.","E":"O RX de abdome é o padrão ouro para o diagnóstico de litíase urinaria, com uma acurácia de\n90%."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-108563","number":"108563","sourceNumber":"108563","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação ao paciente que se encontra no pós-operatório, é correto afirmar que:","options":{"A":"A alimentação deve ser precoce, quando possível, com preferência pela via enteral.","B":"A alimentação deve ser precoce com preferência pela via parenteral.","C":"O paciente não deve ser alimentado.","D":"A alimentação só deve ser iniciada sete dias após o ato cirúrgico.","E":"A dieta deve sempre iniciar por via parenteral e depois modificar para via enteral."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-108569","number":"108569","sourceNumber":"108569","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Os dois índices mais confiáveis para avaliação do risco pré-operatório são:","options":{"A":"ASA e APACHE II.","B":"Goldman e APACHE II.","C":"APACHE II e APACHE III.","D":"ASA e Goldman.","E":"APACHE e Glasgow."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-108570","number":"108570","sourceNumber":"108570","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A laparoscopia tem sido difundida intensamente em todo o mundo, e pode ser utilizada\ntambém como uma alternativa segura em urgências de origem abdominal traumáticas e não\ntraumáticas. São contraindicações para a sua utilização, EXCETO:","options":{"A":"Úlcera perfurada com peritonite purulenta.","B":"Pacientes com TCE associado ao trauma abdominal.","C":"Paciente com instabilidade hemodinâmica.","D":"Paciente com lesão penetrante em dorso e suspeita de lesão retroperitoneal.","E":"Pacientes com distúrbio da coagulação."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-362515","number":"362515","sourceNumber":"362515","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Você é plantonista de uma unidade secundária de pronto atendimento e recebe\npaciente do sexo masculino, 18 anos de\nidade, vítima de queimadura de segundo grau em tórax\nanterior, abdome anterior, região genital e braço esquerdo, por água quente, ocorrido há 15\nminutos. Queixa muita dor local. Peso: 60kg. Ao exame físico observamos a presença de bolhas já\nrôtas. Sobre os cuidados iniciais que devem ser tomadas na conduta deste paciente, assinale a\nalternativa INCORRETA:","options":{"A":"O volume de Ringer Lactato para ressuscitação hídrica deste paciente é de aproximadamente\n1.400ml nas primeiras 8 horas e 1.400ml nas 16\nhoras restantes.","B":"Há indicação de internação hospitalar para cuidados e estes devem incluir analgesia potente,\nantibioticoprofilaxia e averiguação do status vacinal contra o tétano.","C":"Uma vez calculado o volume de Ringer Lactato a ser infundido para ressuscitação, estes valores\ndevem servir apenas de base para hidratação, com o volume de infusão ajustado hora a hora\nbaseado no débito urinário.","D":"Há indicação de curativo sob anestesia para este paciente e tal procedimento deve incluir\ndesbridamento do tecido morto, lavagem da ferida com solução salina estéril e aplicação de\ncurativos com agentes antibacterianos ou substitutos sintéticos de pele."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-298221","number":"298221","sourceNumber":"298221","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente do sexo masculino, 57 anos, procedente de comunidade ribeirinha de Juruá,\nvem a atendimento médico ambulatorial para\navaliação de queixas urinárias. Refere que há cerca\nde 5 anos vem apresentando dificuldade progressiva para urinar, muitas vezes exigindo esforço\npara iniciar a micção e saída de jato urinário fraco, continuada sensação de esvaziamento\nincompleto da bexiga, aumento da frequência de micções durante o dia e vários episódios de\nnoctúria, impactando sua qualidade de vida e suas atividades diárias. Nega hematúria, disúria e dor\npélvica. Nega qualquer tipo de tratamento médico para suas queixas. O exame físico do pênis e do\nescroto não tinham alterações. Não foi palpado bexigoma. O toque retal evidenciou próstata de\nvolume aumentado, consistência fibro-elástica, sem nodulações. Sobre o caso descrito, assinale a\nalternativa CORRETA:","options":{"A":"A provável evolução para hidronefrose indica urografia excretora para o caso.","B":"Já que não foram palpadas nodulações prostáticas, não há indicação da realização da USG\ntransretal e a dosagem do PSA sérico.","C":"O paciente apresenta sintomas graves de obstrução infravesical, estando indicada a\nprostatectomia para alívio dos sintomas.","D":"A abordagem terapêutica inicial para o caso provavelmente consistirá no uso de alfa-\nbloqueadores como a doxazosina e diminuição da ingesta hídrica à noite."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-286728","number":"286728","sourceNumber":"286728","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente do sexo feminino, 28 anos, cerca de 70kg, é trazida ao pronto atendimento\ncom queimaduras de 2º. grau em face, tórax\nanterior, abdome anterior e todo o membro superior\nesquerdo e perna e pé esquerdos, por incêndio em seu domicílio. Há relatos que foi resgatada\npelos bombeiros, mas inalou muita fumaça pois permaneceu muito tempo dentro da casa. Durante\nsua admissão, a paciente estava com nível de consciência rebaixado e foi observada queimaduras\nde víbices nasais e presença de fuligem na cavidade oral, associado a edema e hiperemia mucosa.\nSua saturação de O? à oximetria de pulso era 93%. Assinale a alternativa INCORRETA:","options":{"A":"Há indicação de intubação orotraqueal precoce para este paciente.","B":"Esta paciente pode apresentar acidose mista, isto é, com parâmetros de base metabólica e\nrespiratória, à gasometria de entrada.","C":"O volume estimado para hidratação volêmica nas primeiras 24 horas é de 10.200ml de\ncristaloides, preferencialmente o Ringer Lactato.","D":"Caso a medição de carboxihemoglobina for superior a 10%, a conduta mais adequada é a\noxigenioterapia a 100% por até 12 horas após o incidente."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-286736","number":"286736","sourceNumber":"286736","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente do sexo masculino, 40 anos, dá entrada no pronto atendimento com quadro\nde dor tipo cólica, de início súbito,\nbastante intensa, que iniciou em região lombar alta à direita e\nirradiou para FD e hemibolsa escrotal direita, com evolução de 4h. Refere vômitos. Nega febre e\ndiarreia. Ao exame físico, o paciente se apresenta ansioso, inquieto na maca, com fácies de dor,\ntaquicárdico, sudoreico e normotenso. Seu abdome é bastante doloroso à palpação profunda em\nFlanco Direito e Fossa Ilíaca Direita, sem sinais de irritação peritoneal. Leucograma: 9.000. EAS:\nincontáveis hemácias e piócitos/campo. Sobre a investigação diagnóstica e tratamento deste\npaciente, assinale a alternativa INCORRETA:","options":{"A":"A identificação de complicações infecciosas, insuficiência renal ou complicações obstrutivas\nurinárias indicam internação hospitalar e\npossível tratamento cirúrgico/endoscópico.","B":"O uso de anti-inflamatórios não esteroidais como o Diclofenaco® e a morfina são drogas\nfrequentemente usadas no tratamento inicial nestes casos.","C":"Na ausência de complicações, o uso da Tansulosina e da Nifedipina podem evitar a necessidade\ndo tratamento cirúrgico para o caso acima.","D":"Já que a urografia excretora com contraste venoso apresenta a maior sensibilidade e\nespecificidade no diagnóstico etiológico e de complicações para estes casos, esta é\npreferencialmente o exame de imagem indicado para avaliação inicial e decisão terapêutica."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-252232","number":"252232","sourceNumber":"252232","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Incêndio domiciliar: casa de dois andares, completamente tomada de fogo e fumaça\npreta, saindo por janelas e pelo teto. O\npaciente RSF, 25 anos, voltou para resgatar o cão e foi\nretirado pelos bombeiros, totalmente inconsciente. Num primeiro exame, apresentava-se\ninconsciente, respirando espontaneamente, mas com dificuldades. O cabelo apresentava-se\nchamuscado além de queimaduras de 2º grau, na face e pescoço, como um todo, na região anterior\ndo tórax e abdômen, nos 2 braços / ante-braços e nas duas mãos. Queimadura circunferencial em\nMMSS, pulso palpável, porém apresentando membro bastante edemaciado. FC de 128 bpm, FR de\n26irpm, PA de 148/94 mmHg, SaO2 de 92% Peso 75 kg O paciente foi transferido para o Pronto\nSocorro 28 de Agosto, pelos bombeiros. Chegando lá foi atendido no box de politrauma por uma\nequipe multidisciplinar, composta por um cirurgião, dois residentes, um enfermeiro e dois técnicos\nem enfermagem. O tempo decorrido do acidente e referido à equipe de trauma foi de 3 horas.\n\nAgora são 13h de quinta-feira. A ressuscitação volêmica desse paciente deve ser realizada através\nde:","options":{"A":"Punção venosa periférica com cateteres curtos.","B":"Via enteral (sonda naso-enteral).","C":"Punção venosa central com cateteres longos.","D":"Via Oral (200 ml a cada hora)."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-208352","number":"208352","sourceNumber":"208352","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A melhor conduta para minimizar os efeitos da translocação bacteriana do Grande\nQueimado:","options":{"A":"Instituir precocemente Nutrição Parenteral","B":"Administrar Antibiótico de amplo espectro","C":"Administrar Albumina","D":"Instituir precocemente Nutrição Enteral"},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-176032","number":"176032","sourceNumber":"176032","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente vítima de ferimento abdominal por arma de fogo foi submetido à laparotomia\nexploradora que evidenciou lesão\ntransfixante de estômago, explosão esplênica com hemorragia\nprofusa e lesão do diafragma esquerdo, sendo realizada a gastrorrafia, esplenectomia, frenorrafia e\ndrenagem fechada de tórax à esquerda. A paciente fez uso profilático de cefalosporina de primeira\ngeração, ressuscitação volêmica com Ringer lactato e analgesia. No primeiro dia pós-operatório\napresentava-se pálido, discretamente dispneico, taquicárdico e normotenso, com urina concentrada\ne volume reduzido. Sobre possíveis condutas adicionais e eventos relacionados ao pós-operatório,\nmarque a alternativa INCORRETA:","options":{"A":"Podemos afirmar que o paciente se encontra hemodinamicamente instável devido à reposição\ninadequada de potássio na hidratação venosa no pós-operatório imediato.","B":"O paciente apresenta oligúria devido a ação da aldosterona nos túbulos renais distais e do\nhormônio antidiurético, em resposta à provável hipovolemia não plenamente tratada.","C":"Podemos inferir que o débito cardíaco deste paciente está sendo mantido às custas de aumento\nda resistência vascular periférica e aumento da\nfrequência cardíaca mediada pelas catecolaminas.","D":"A vasoconstrição periférica mediada pela noradrenalina piora a perfusão tecidual, ocasionando\nsofrimento tissular com hipóxia, hipercarbia e acúmulo de catabólitos ácidos."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-176099","number":"176099","sourceNumber":"176099","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Quais as células predominantes encontradas na fase de maturação de uma ferida em\ncicatrização?","options":{"A":"Macrófagos.","B":"Neutrófilos.","C":"Fibroblastos.","D":"Linfócitos."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-151943","number":"151943","sourceNumber":"151943","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre as complicações metabólicas da terapia nutricional parenteral, qual a\nCORRETA?","options":{"A":"Hiponatremia.","B":"Hipercoagulabilidade.","C":"Depósito de hemosiderina.","D":"Aumento da produção de CO2."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-139125","number":"139125","sourceNumber":"139125","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação as hérnias inguinais, o elemento importante que fornece um ponto de\nreferencia últil para diferenciar as \" diretas das indiretas\" por fazer parte da borda lateral do\ntriângulo de Hasselbach?","options":{"A":"Sínfise pública.","B":"Ligamento umbilical medial.","C":"Artéria epigástrica inferior.","D":"Fáscia de Gallaudet ou fáscia inominada."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-103785","number":"103785","sourceNumber":"103785","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Na correção de hérnia inguinal minimamente invasiva, pela técnica TAPP, deve-se\nevitar grampeamento no triângulo do desastre ou de\ndestruição para evitar lesão de qual estrutura?","options":{"A":"Vasos espermáticos.","B":"Vasos epigástricos.","C":"Nervo genitocrural.","D":"Vasos ilíacos."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-103787","number":"103787","sourceNumber":"103787","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Hérnia localizada no triângulo lombar superior.","options":{"A":"Petit;","B":"Grynfelt;","C":"Spiegel;","D":"Petterson."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-103797","number":"103797","sourceNumber":"103797","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Infecção que se dissemina através da fáscia de Buck, ao longo dos planos fasciais,\ndartos, escroto, estendendo-se para a fáscia de\nColles do períneo, podendo atingir a fáscia de\nScarpa:","options":{"A":"Síndrome de Fournier.","B":"Gangrena de Meleney.","C":"Abscesso isquiorretal.","D":"Miosite clostrídica."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-107777","number":"107777","sourceNumber":"107777","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"As hérnias da parede anterior do abdome são patologias das mais frequentes no\npaciente cirúrgico e o conhecimento da sua\nanatomia e de suas possíveis complicações são\nessenciais no seu tratamento adequado. Sobre as hérnias da parede abdominal, analise as\nassertivas abaixo e assinale a alternativa CORRETA: I. Hérnia inguinal cujo conteúdo do saco\nherniário contém o apêndice cecal é conhecida como hérnia de Littré; II. A técnica de Lichtenstein é\nde fácil reprodução e apresenta baixos índices de recidiva quando comparada à técnica de Bassini;\n\nIII. Tanto hérnias inguinais diretas quanto hérnias inguinais indiretas podem ser tratadas por via\nlaparoscópica; IV. Uma hérnia inguinoscrotal, não redutível, bastante dolorosa à palpação, com\nsinais flogísticos exuberantes configura provável estrangulamento do seu conteúdo; V. Hérnias\nNyhus I são adquiridas.","options":{"A":"Há 3 assertivas incorretas acima.","B":"As assertivas I e III são corretas.","C":"Apenas a assertiva IV é falsa.","D":"As assertivas II e III são corretas."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-87445","number":"87445","sourceNumber":"87445","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O uso indiscriminado de antimicrobianos em pacientes cirúrgicos resulta em aumento\nna incidência de cepas bacterianas\nmultirresistentes e maiores custos hospitalares. Sobre a\nracionalização da antibioticoprofilaxia do paciente cirúrgico, assinale a alternativa FALSA:","options":{"A":"O antimicrobiano deve ter espectro de ação direcionado à microbiota prevalente na região da\ncirurgia.","B":"Deve ser administrada preferencialmente na indução anestésica e seu uso não deve ultrapassar\n48h.","C":"Devemos dar preferência aos antimicrobianos de primeira geração.","D":"Deve ser direcionado pelo antibiograma da área.","E":"A presença de drenos e/ou cateteres não justifica o prolongamento da antibioticoprofilaxia."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-87460","number":"87460","sourceNumber":"87460","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre as hérnias da parede anterior do abdome, assinale a alternativa INCORRETA:","options":{"A":"Podemos afirmar que as hérnias Nyhus I são congênitas.","B":"Hérnias localizadas dentro do triângulo de Hesselbach são adquiridas.","C":"Hérnias não redutíveis, com sinais flogísticos na pele ou evolução acima de 6 horas têm\nindicação de tratamento cirúrgico urgente.","D":"A técnica de Liechtestein está caindo em desuso devido à sua complexidade técnica.","E":"A herniorrafia inguinal videolaparoscópica, quando realizado por cirurgião experiente, é\nprocedimento factível, com baixas taxas de recidiva e complicações."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-82011","number":"82011","sourceNumber":"82011","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente transferido do interior do estado, vítima de lesão da arteria femural por FAB.\nFeito clampeamento arterial e estabilidade hemodinâmica na cidade de origem. Realizado\nprocedimento cirúrgico após 4h da agressão (reparo arterial). Evolução com hipercalemia já no\nPós-operatório imediato. A provável causa será:","options":{"A":"IRA devido choque hipovolêmico","B":"Rabdomiólise devido reperfusão","C":"CIVD","D":"Infratores da glândula adrenal","E":"Uso de drogas anestésicas que elevaram o eletrólito."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-81024","number":"81024","sourceNumber":"81024","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Qual dos fenômenos abaixo não está relacionado à resposta endócrina à hipovolemia?","options":{"A":"Liberação de noradrenalina pela suprarrenal.","B":"Reabsorção de água e sódio nos túbulos renais distais.","C":"Tentativa de compensação do débito cardíaco.","D":"Hipofluxo na arteríola aferente do glomérulo.","E":"Distensão dos baroceptores carotídeos."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-61497","number":"61497","sourceNumber":"61497","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente de 70 anos de idade apresenta adenocarcinoma do reto alto, devendo ser\nsubmetido à ressecção anterior do reto. Qual é o melhor tipo de intervenção para a profilaxia do\ntromboembolismo venoso?","options":{"A":"Deambulação precoce.","B":"Instalação de filtro de veia cava.","C":"Uso de heparina não fracionada e de meia elástica.","D":"Uso de heparina de baixo peso molecular e deambulação precoce.","E":"Compressão pneumática dos membros inferiores, uso de meia elástica e de heparina de baixo\npeso molecular e deambulação precoce."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-60882","number":"60882","sourceNumber":"60882","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente após queimadura térmica envolvendo mais de 50% da superfície corporal, foi\ninternado em estado grave em unidade de terapia intensiva. Após todos os cuidados referentes à\nqueimadura e hidratação, paciente evolui com hemorragia digestiva alta. Qual a principal hipótese\ndiagnóstica?","options":{"A":"Úlcera de Curling","B":"Distúrbio de coagulação","C":"Lesão gástrica de Dieulafoy","D":"Laceração de Mallory-Weiss","E":"Doença de Ménétrier, devido à gastrite hipertrófica"},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-26492","number":"26492","sourceNumber":"26492","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Assinale a alternativa incorreta:","options":{"A":"As hérnias inguinais indiretas correspondem à persistência de conduto peritoneo-vaginal patente\npelo canal inguinal","B":"Hérnias inguinais indiretas em pacientes idosos são congênitas","C":"Hérnias femorais são mais comuns em mulheres e podem ocasionar obstrução intestinal","D":"Hérnias inguinais diretas ocorrem por fragilidade da parede posterior do canal inguinal","E":"A hérnia de Richter contém apêndice cecal no seu interior"},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-26650","number":"26650","sourceNumber":"26650","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente com fístula gastrointestinal, que mostra alta taxa de bicarbonato. A partir\ndeste\nachado, pode-se afirmar que a fístula é proveniente de:","options":{"A":"Estômago.","B":"1° porção duodenal.","C":"Pâncreas.","D":"Biliar.","E":"Íleo."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-354398","number":"354398","sourceNumber":"354398","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Homem, 65 anos de idade, procura a Unidade de Saúde para uma consulta de rotina.\nNão apresenta sintomas, mas está preocupado com\na saúde de sua próstata, já que seu pai foi\ndiagnosticado com câncer de próstata aos 70 anos de idade. O fator adicional que pode aumentar a\npreocupação com o câncer de próstata para esse paciente é ser de origem","options":{"A":"afrodescendente.","B":"asiática.","C":"judaica.","D":"mediterrânea."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-284583","number":"284583","sourceNumber":"284583","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo masculino, 65 anos de idade, procura a Unidade de Pronto Atendimento\n(UPA) com queixa de dor intensa em abdômen\ninferior há duas horas e dificuldade para urinar. O\npaciente refere que apresenta dificuldade para iniciar a micção há cerca de seis meses, associada\na despertares noturnos para urinar (duas vezes/noite) e intermitência da micção. Relata que a\nultima micção foi há cinco horas. Nega outros sintomas e comorbidades. Ao exame físico, bom\nestado geral, corado, FC: 92bpm, PA: 132x76mmHg, FR: 18 ipm: palpada massa volumosa\narredondada em hipogástrio, associada à dor intensa e sem sinais de irritação peritoneal. Indique a\nprincipal suspeita etiológica que motivou o paciente a procurar o Pronto Atendimento.","options":{"A":"Infecção do trato urinário.","B":"Prostatite aguda.","C":"Litíase urinária.","D":"Hiperplasia prostática benigna."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-284584","number":"284584","sourceNumber":"284584","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo masculino, 65 anos de idade, procura a Unidade de Pronto Atendimento\n(UPA) com queixa de dor intensa em abdômen\ninferior há duas horas e dificuldade para urinar. O\npaciente refere que apresenta dificuldade para iniciar a micção há cerca de seis meses, associada\na despertares noturnos para urinar (duas vezes/noite) e intermitência da micção. Relata que a\nultima micção foi há cinco horas. Nega outros sintomas e comorbidades. Ao exame físico, bom\nestado geral, corado, FC: 92bpm, PA: 132x76mmHg, FR: 18 ipm: palpada massa volumosa\narredondada em hipogástrio, associada à dor intensa e sem sinais de irritação peritoneal.\n\nDetermine o primeiro exame, ou procedimento, que pode auxiliar no diagnóstico etiológico do caso.","options":{"A":"Ultrassonografia dos rins e vias urinárias.","B":"Tomografia de abdome e pelve.","C":"Toque retal.","D":"Cistoscopia."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-284585","number":"284585","sourceNumber":"284585","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo masculino, 65 anos de idade, procura a Unidade de Pronto Atendimento\n(UPA) com queixa de dor intensa em abdômen\ninferior há duas horas e dificuldade para urinar. O\npaciente refere que apresenta dificuldade para iniciar a micção há cerca de seis meses, associada\na despertares noturnos para urinar (duas vezes/noite) e intermitência da micção. Relata que a\nultima micção foi há cinco horas. Nega outros sintomas e comorbidades. Ao exame físico, bom\nestado geral, corado, FC: 92bpm, PA: 132x76mmHg, FR: 18 ipm: palpada massa volumosa\narredondada em hipogástrio, associada à dor intensa e sem sinais de irritação peritoneal. Indique o\ntratamento imediato que deve ser instituído.","options":{"A":"Sondagem vesical.","B":"Prescrição de antibiótico por via oral.","C":"Cistoscopia para remoção de cálculo urinário.","D":"Videolaparoscopia."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-284586","number":"284586","sourceNumber":"284586","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo feminino, 30 anos de idade, vítima de queimadura após explosão de\nbotijão de gás dentro da cozinha há uma hora, é trazida ao Hospital Geral pelo SAMU. No exame\ninicial, A: via aérea pérvia, presença de hiperemia em orofaringe, mantido colar cervical, SatO?:\n91% com cateter de Q? 15 L/min; B: murmúrios vesiculares diminuídos em base à direita, com\nroncos bilateralmente, FR: 20 irpm; C: bulhas rítmicas e normofonéticas, FC: 88 bpm, PA: 112 x 72\nmmHg, abdome indolor à palpação, pelve estável e toque retal sem alterações; D: escala de coma\nde Glasgow = 15, pupilas isocóricas e fotorreagentes; E: presença de queimadura de 2° grau\nprofundo em região anterior da cabeça e pescoço, região anterior do tronco e região anterior do\nmembro superior esquerdo; queimadura de 3° grau em região anterior e posterior do membro\nsuperior direito. Diante desse caso clínico, determine a primeira conduta terapêutica que deve ser\ninstituída.","options":{"A":"Toracostomia com drenagem em selo d'agua à direita.","B":"Intubação orotraqueal.","C":"Lavagem das feridas e curativo com sulfadiazina de prata.","D":"Reposição volêmica com Ringer lactato."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-284587","number":"284587","sourceNumber":"284587","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo feminino, 30 anos de idade, vítima de queimadura após explosão de\nbotijão de gás dentro da cozinha há uma\nhora, é trazida ao Hospital Geral pelo SAMU. No exame\ninicial, A: via aérea pérvia, presença de hiperemia em orofaringe, mantido colar cervical, SatO?:\n91% com cateter de Q? 15 L/min; B: murmúrios vesiculares diminuídos em base à direita, com\nroncos bilateralmente, FR: 20 irpm; C: bulhas rítmicas e normofonéticas, FC: 88 bpm, PA: 112 x 72\nmmHg, abdome indolor à palpação, pelve estável e toque retal sem alterações; D: escala de coma\nde Glasgow = 15, pupilas isocóricas e fotorreagentes; E: presença de queimadura de 2° grau\nprofundo em região anterior da cabeça e pescoço, região anterior do tronco e região anterior do\nmembro superior esquerdo; queimadura de 3° grau em região anterior e posterior do membro\nsuperior direito. Indique, com base no ATLS® 10ª edição, a velocidade mais aproximada de infusão\n(ml/h) da solução cristaloide nas primeiras horas de reanimação, considerando que a paciente pesa\n60 kg.","options":{"A":"270 ml/h.","B":"540 ml/h.","C":"308 ml/h.","D":"617 ml/h."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-284588","number":"284588","sourceNumber":"284588","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo feminino, 30 anos de idade, vítima de queimadura após explosão de\nbotijão de gás dentro da cozinha há uma hora, é trazida ao Hospital Geral pelo SAMU. No exame\ninicial, A: via aérea pérvia, presença de hiperemia em orofaringe, mantido colar cervical, SatO?:\n91% com cateter de Q? 15 L/min; B: murmúrios vesiculares diminuídos em base à direita, com\nroncos bilateralmente, FR: 20 irpm; C: bulhas rítmicas e normofonéticas, FC: 88 bpm, PA: 112 x 72\nmmHg, abdome indolor à palpação, pelve estável e toque retal sem alterações; D: escala de coma\nde Glasgow = 15, pupilas isocóricas e fotorreagentes; E: presença de queimadura de 2° grau\nprofundo em região anterior da cabeça e pescoço, região anterior do tronco e região anterior do\nmembro superior esquerdo; queimadura de 3° grau em região anterior e posterior do membro\nsuperior direito. Indique a conduta terapêutica imediata que deve ser instituída, caso a paciente\nevolua com edema e dor em antebraço direito.","options":{"A":"Abrir os curativos.","B":"Fasciotomia.","C":"Desbridamento.","D":"Escarotomia."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-35015","number":"35015","sourceNumber":"35015","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo masculino, 38 anos de idade, submetido à hemorroidectomia pela\ntécnica de Milligan Morgan, cursa com\nsangramento copioso anal 6 horas após a cirurgia. Sobre a\nanatomia cirúrgica da região inguinal, é correto afirmar:","options":{"A":"A tela subcutânea é composta principalmente pelas fáscias de Scarpa (mais superficial e\nlamelar) e Camper (mais profunda e areolar).","B":"A estrutura músculo-aponeurótica mais superficial é o músculo transverso.","C":"0 ligamento de Poupart é constituído por espessamento látero-inferior do músculo oblíquo\ninterno.","D":"O anel inguinal superficial é recoberto pela fáscia de Gallaudet.","E":"A fáscia cremastérica é originada do músculo oblíquo externo."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-35016","number":"35016","sourceNumber":"35016","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente classificado como ASA I, no 8º DPO de hernioplastia inguinal à Lichtenstein,\nrefere desconforto e tumoração na região inguinal\noperada. Ao exame, nota-se volumoso\nabaulamento macio na região inguinal, sem sinais de flogose local. A coloração da pele é normal.\nNessa situação, a principal suspeita diagnóstica é:","options":{"A":"hematoma.","B":"seroma.","C":"infecção de sítio cirúrgico superficial.","D":"infecção de sítio cirúrgico profunda.","E":"recidiva da hérnia."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-34989","number":"34989","sourceNumber":"34989","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente classificado como ASA I, no 8º DPO de hernioplastia inguinal à Lichtenstein,\nrefere desconforto e tumoração na região inguinal\noperada. Ao exame, nota-se volumoso\nabaulamento macio na região inguinal, sem sinais de flogose local. A coloração da pele é normal. O\ntratamento de escolha é realizar:","options":{"A":"evacuação do hematoma com anestesia local.","B":"punção e esvaziamento.","C":"abertura dos pontos e drenagem, apenas.","D":"abertura dos pontos, drenagem e antibioticoterapia oral.","E":"reoperação com nova herniorrafia."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-27455","number":"27455","sourceNumber":"27455","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, sexo feminino, 38 anos de idade, submetida à videolaparocolecistectomia por\ncolecistolitíase, cursa, logo após a extubação no centro cirúrgico, com rigidez do masseter e\ncianose. Dados vitais, pulso: 140 bpm, frequência respiratória: 36 ipm, temperatura axilar: 41°C. Ao\nmonitor cardíaco, o ritmo era taquicardia supreventricular. Gasimetria arterial mostrava acidose\nmista. Lactato arterial: 5,0. O diagnóstico mais provável da síndrome apresentada por essa\npaciente é:","options":{"A":"desidratação.","B":"infarto agudo do miocárdio.","C":"hipertermia maligna.","D":"acidente vascular encefálico.","E":"hipercarbia por alta absorção do CO2 do pneumoperitônio."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-215596","number":"215596","sourceNumber":"215596","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre as citocinas na resposta inflamatória, é INCORRETO que:","options":{"A":"A citocina TNF-alfa é produzida por monócitos, macrófagos, neutrófilos e células endoteliais.","B":"As citocinas anti-inflamatórias são uma série de moléculas imunoregulatórias, dentre elas IL-4,\nIL-6.","C":"A IL-6 apresenta propriedades pró e anti-inflamatória.","D":"A IL-18 está diminuída na sepse."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-181175","number":"181175","sourceNumber":"181175","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"De acordo com a classificação de Nyhus para hérnias inguinais, a do tipo II\ncorresponde a:","options":{"A":"Hérnia Inguinal Direita.","B":"Hérnia Inguinal indireta com anel interno dilatado com destruição da fáscia transversal do\ntriangulo de Hesselbach.","C":"Hérnia Inguinal Indireta com anel interno dilatado e parede inguinal posterior intacta.","D":"Hérnia Femoral."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-157649","number":"157649","sourceNumber":"157649","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação aos fios de sutura, assinale a alternativa em que a afirmação esteja\nCORRETA.","options":{"A":"O categute simples é considerado um fio absorvível, tem a resistência diminuída ao final da\nsegunda semana, e totalmente absorvida em até 60\ndias por hidrólise.","B":"O fio de polipropileno é inabsorvível, monofilamentar e não sofre biodegradação pelo organismo\ne, por isso, tem muita reação tissular e pouca\nresistência à tração.","C":"O fio de poliéster é inabsorvível, monofilamentado, que não sofre biodegradação pelo\norganismo, pode apresentar escorregamento na\nfixação dos nós e requer, no mínimo, quatro nós.","D":"O fio de algodão é inabsorvível, mulfilamentar, de origem vegetal, e podem ser misturados a\nfibras de poliéster, ganhando assim maior maleabilidade, maior resistência à tração e menor\ndegradação pelo organismo."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-157644","number":"157644","sourceNumber":"157644","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Marque a opção em que a afirmativa esteja INCORRETA.","options":{"A":"O Fentanil é um opioide que apresenta potência 80 a 100 vezes superior à morfina. É\namplamente usada em associação com o Cloridrato de Bupivacaína por via peridural, seja por\ninfusão contínua ou por analgesia controlada pelo paciente.","B":"O Sulfato de Morfina tem amplo emprego no período pós-operatório de toracotomias. Quando\nutilizado por via venosa é mais bem administrado pelo método de analgesia controlada pelo\npaciente.","C":"O Cloridrato de Cetamina é um anestésico geral conhecido há mais de 30 anos que pode ser\nutilizado como adjuvante no controle da dor pós-operatória, quando utilizado conjuntamente com\nanestésicos locais ou opioides.","D":"A Meperidina é um opioide amplamente prescrito para o controle de dor pós-operatória, pela\ncapacidade de controle de dor, sem risco de depressão respiratória."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-157579","number":"157579","sourceNumber":"157579","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação à monitorização invasiva no paciente cirúrgico de alto risco, indique a\nalternativa em que a afirmação esteja INCORRETA.","options":{"A":"A avaliação da volemia com o uso de pressão arterial invasiva pode ser feita através da variação\nda pressão de pulso durante o ciclo\nrespiratório, se o delta PP for menor que 13% está associado à\nhipovolemia com possibilidade de ser corrigida.","B":"A saturação venosa mista de oxigênio (SVO2) é um indicador global da oxigenação tecidual. A\nimportância da SVO2 obtida pelo cateter venoso central foi evidenciada por Rivers et al., que\ndemostraram redução estatisticamente significativa quando SVO2 >70% nos pacientes sépticos.","C":"A monitorização do gradiente arteriovenoso de CO2 (delta CO2) baseia-se no fato de que no\nponto de vista fisiológico, existe uma\nrelação inversa entre fluxo sanguíneo e gradiente venoarterial\nde CO2.","D":"Os benefícios da monitorização com cateter de Swan-Ganz ainda são controversos. É consenso\nque não deve ser utilizado rotineiramente.\nO risco relacionado à inserção do cateter é semelhante a\nde uma punção venosa."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-157687","number":"157687","sourceNumber":"157687","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre a Mediastinite Necrotizante Descendente Aguda, aponte a opção que esteja\nINCORRETA.","options":{"A":"Geralmente é uma infecção polimicrobiana, e os agentes mais comuns são: Pseudomonas\naeroginosa, Stafilococcus aureus e\n\nBacteriodes fragilis.","B":"A mortalidade pode chegar a 50% e é mais frequente na população de pior condição\nsocioeconômica.","C":"O tratamento com medidas de suporte intensivo e antibioticoterapia de amplo espectro é a\nterapia padrão.","D":"O exame mais preciso e que melhor orienta o diagnóstico é a tomografia computadorizada de\npescoço e tórax."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-162509","number":"162509","sourceNumber":"162509","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação ao manejo de feridas, é CORRETO afirmar que:","options":{"A":"O fechamento secundário é indicado em casos nos quais o tratamento aberto das feridas não\nevoluiu bem.","B":"O fechamento primário é indicado para feridas limpas, com pequeno risco de infecção e\ncontraindicado nos casos de ferida por mordedura.","C":"O tratamento aberto de feridas nos casos de feridas infectadas é a melhor opção, obtendo-se,\ngeralmente, bom resultado estético.","D":"O fechamento primário de feridas também é uma opção, quando o intervalo entre o traumatismo\ne o início do tratamento é maior que 6\nhoras.","E":"O fechamento primário também é indicado nas feridas em tecidos com suprimento sanguíneo\ninadequado, tendo em vista que a sutura provocaria danos nessa região."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-157624","number":"157624","sourceNumber":"157624","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Crianças internadas em UTI Pediátrica necessitam, muitas vezes, de suporte\nventilatório com intubação endotraqueal por\ntempo indeterminado, levando a complicações\nassociadas aos cuidados e à presença do tubo traqueal. Dentre as complicações a seguir, aponte\naquela que apresenta uma morbidade significativa.","options":{"A":"Aumento de secreções na via respiratória.","B":"Incidência aumentada de infecções.","C":"Pneumomediastino.","D":"Estenose subglótica."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-157632","number":"157632","sourceNumber":"157632","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A traqueostomia, realizada por equipe treinada, torna-se um procedimento cirúrgico\nseguro e eficaz. Quando há uma indicação correta para o seu uso, porém, pode apresentar\ncomplicações imediatas importantes, que devem ser diagnosticadas e tratadas corretamente.\n\nAssinale a alternativa que NÃO representa uma dessas complicações.","options":{"A":"Decanulação acidental.","B":"Acúmulo de secreção ao redor da cânula.","C":"Enfisema subcutâneo, mediastinal e pneumotórax.","D":"Parada cardíaca secundária à hipóxia, acidose ou distúrbios hidroeletrolíticos."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-157623","number":"157623","sourceNumber":"157623","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação à Máscara Laríngea (ML), assinale a alternativa CORRETA.","options":{"A":"Necessita de lâmina de laringoscópio reta para melhor visualização das estruturas, a fim de\npermitir um perfeito deslizamento da ML contra o palato.","B":"Não deve ser usada em crianças, pois não há como posicioná-la adequadamente, já que a\nlaringe da criança é afunilada em relação à do adulto.","C":"Pode ser usada em situação de emergência quando ?não intubo e não ventilo?.","D":"Nunca deve ser usada como recurso para intubação traqueal."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-157681","number":"157681","sourceNumber":"157681","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Quanto à terapia nutricional mista ou combinada, é INCORRETO afirmar que:","options":{"A":"Pode ser útil na otimização do aporte de macro e micronutrientes na criança gravemente doente.","B":"A terapia nutricional parenteral administrada por veia perférica pode ser suficiente para\ncomplementar o aporte enteral.","C":"Para que o procedimento seja adequado, há necessidade de instalação de cateter venoso\ncentral.","D":"O cateter tipo PICC é relacionado a menores taxas de infecção quando comparado ao cateter\nvenoso central de tripla via."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-157698","number":"157698","sourceNumber":"157698","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A melhora da sobrevida em pacientes com choque séptico está relacionada, entre\noutros fatores,","options":{"A":"à infusão rápida de solução fisiológica, 20 ml/kg a 60 ml/kg, nos primeiros 15 minutos.","B":"ao uso de insulina nos pacientes com hiperglicemia associada.","C":"à obtenção de acesso venoso central nas primeiras 6 horas do atendimento.","D":"à transfusão de hemoderivados na admissão, na UTI Pediátrica."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-139761","number":"139761","sourceNumber":"139761","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação à prevenção da infecção da incisão cirúrgica, assinale a alternativa\nCORRETA.","options":{"A":"A tricotomia do sítio cirúrgico deve ser realizada poucos minutos antes da incisão cirúrgica.","B":"O antibiótico profilático deve ser mantido por 3 dias.","C":"O antibiótico profilático deve ser administrado assim que termina a cirurgia.","D":"A degermação esteriliza a pele, evitando a infecção."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-134742","number":"134742","sourceNumber":"134742","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Frequentemente, solicitamos tomografia para avaliação clínica dos mais diversos\ncasos, sendo atualmente inegável sua\nimportância dentro do contexto do diagnóstico por imagem.\nQuando necessário o uso de contraste, apresenta como consideração vários aspectos, EXCETO\npor:","options":{"A":"Necessitar suspender metiformina por risco.","B":"Relacionar-se à alergia de iodo.","C":"Poder aumentar a área de injúria secundária no sangramento do sistema nervoso central.","D":"Hidratação prévia não mudar a toxicidade."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-134714","number":"134714","sourceNumber":"134714","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Faça a associação entre o procedimento cirúrgico e o antibiótico mais indicado para\nprofilaxia, e assinale a alternativa CORRETA. 1. Cirurgias Colorretais. 2. Apendicectomia. 3.\n\nTireoidectomia. ( ) Cefazolina + metronidazol. ( ) Sem antibiótico profilático. ( ) Neomicina +\neritromicina.","options":{"A":"2 / 3 / 1.","B":"2 / 1 / 3.","C":"1 / 2 / 3.","D":"1 / 3 / 2."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-111833","number":"111833","sourceNumber":"111833","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A ossificação da ferida operatória:","options":{"A":"é uma complicação tardia e rara.","B":"ocorre principalmente nas cicatrizes de toracotomias.","C":"ocorre principalmente nas cicatrizes de laparotomias.","D":"uma das alternativas anteriores está errada."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-111923","number":"111923","sourceNumber":"111923","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"São complicações da Cirurgia Abdominal e que indicam nutrição parenteral:","options":{"A":"disfunção da boca anastomótica ou fístula gastrointestinal.","B":"peritonite difusa grave e abscesso intraperitoneal grave ou íleo paralítico prolongado.","C":"diarreias graves.","D":"todas as alternativas anteriores."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-111841","number":"111841","sourceNumber":"111841","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Aponte os três fatores fundamentais na ?decisão operatória?.","options":{"A":"A indicação correta, os riscos avaliados e informados, e o momento oportuno.","B":"Os honorários, os riscos avaliados e informados,e o momento oportuno.","C":"A indicação correta, o anestesista e o momento oportuno.","D":"A indicação correta, os riscos avaliados e informados, e a tecnologia disponível."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-111846","number":"111846","sourceNumber":"111846","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação às complicações urinárias pós-operatórias, é CORRETO afirmar que:","options":{"A":"é uma complicação rara.","B":"é mais comum em pacientes do sexo masculino, idosos e prostáticos.","C":"o uso de sedativos não influencia.","D":"todas acima estão corretas."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-350856","number":"350856","sourceNumber":"350856","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Mulher 72 anos, portadora de Mal de Alzheimer, apresenta desnutrição\n\nprotéico-calórica por dificuldade progressiva de ingesta de alimentação oral. História patológica\npregressa: 02 internamentos por broncopneumonia\nno último ano. A família a alimenta com dieta\ncom espessante, porém a paciente vem apresentando perda de peso devido ao pequeno volume\ntolerado e ao baixo aporte de proteína e calorias. Qual via de acesso alimentar é a mais adequada\npara essa paciente?","options":{"A":"Jejunostomia.","B":"Gastrostomia.","C":"Esofagostomia.","D":"Sonda nasoenteral."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-259690","number":"259690","sourceNumber":"259690","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, 40 anos, obeso mórbido, IMC 40, tem diagnóstico de retocolite ulcerativa há\n10 anos e achado de displasia de alto grau\nem biópsias colonoscópicas aleatórias. A proposta seria\numa colectomia total. Qual deverá ser a melhor estratégia em relação ao suporte nutricional para\nesse paciente?","options":{"A":"Indicar cirurgia bariátrica antes da realização da colectomia para uma adequação do peso.","B":"Orientar perda de 10% de peso corporal no pré-operatório para melhoria da função pulmonar e\nmetabólica.","C":"Prescrever glutamina parenteral perioperatória para diminuir o catabolismo proteico e estimular a\nlipólise.","D":"Iniciar NPT no pós-operatório imediato objetivando reduzir o risco de fístula secundária à\n\n?obesidade sarcopênica?."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-234020","number":"234020","sourceNumber":"234020","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente do sexo masculino, de 45 anos, foi referido a partir de uma unidade ba?sica\nde sau?de com relato de aumento indolor do\nvolume escrotal a? esquerda. Conforme o relato do\nme?dico que o encaminhou, o exame fi?sico revelava aumento volume?trico e moderado do\nescroto a? esquerda, indolor a? palpac?a?o, de consiste?ncia tensa e totalmente passi?vel de\ntransiluminac?a?o. Foram realizadas tambe?m as dosagens se?ricas de alfafetoprotei?na e\ngonadotrofina corio?nica humana. Na avaliac?a?o cli?nica do especialista, os achados cli?nicos da\ntransiluminac?a?o foram confirmados e na?o havia sugesta?o de aumento de volume testicular.\n\nQual deve ser o resultado esperado das dosagens hormonais realizadas?","options":{"A":"Aumento do ni?vel se?rico de alfafetoprotei?na.","B":"Ni?veis se?ricos de ambos dentro da normalidade.","C":"Aumento do ni?vel se?rico de ambos os hormo?nios.","D":"Aumento do ni?vel se?rico de gonadotrofina corio?nica humana."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-234023","number":"234023","sourceNumber":"234023","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente com 56 anos, tabagista, com história de icterícia, perda de peso e\nemagrecimento, foi admitido para tratamento cirúrgico. Na avaliação clínica pré-operatória, não\nforam evidenciadas comorbidades maiores e o paciente foi classificado como ASA II, conforme a\nescala da American Society of Anestesiology. O estadiamento pré-operatório mostrou lesão\ncompatível com adenocarcinoma da cabeça do pâncreas localizado. Foi realizada\nduodenopancreatectomia cefálica e o paciente se encontra no primeiro dia de pós-operatório em\nunidade de terapia intensiva, clinicamente bem, conforme o boletim médico. Com base na chamada\nresposta sistêmica à cirurgia, qual das seguintes condições é esperada para esse paciente?","options":{"A":"Aumento dos ni?veis de cortisol em resposta a? liberac?a?o renal de renina.","B":"Reduc?a?o dos ni?veis de aldosterona em resposta a? ativac?a?o da via simpato-renal.","C":"Ativac?a?o do sistema nervoso simpa?tico, reduzindo a secrec?a?o de insulina no pa?ncreas.","D":"Hipoglicemia secunda?ria a aumento dos ni?veis do hormo?nio do crescimento (GH)."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-199662","number":"199662","sourceNumber":"199662","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um trabalhador de empresa de energia elétrica, 23 anos, sofreu acidente de trabalho\npor queimadura de alta voltagem sendo a extensão da\nlesão estimada em 40% da área corporal\ncom queimaduras de terceiro grau. Foi levado pelo SAMU para uma unidade de tratamento de\nqueimados onde foi admitido e recebeu tratamento imediato. Após 48 horas do trauma, mantém\nestabilidade hemodinâmica, desenvolve escurecimento da urina (cor vermelho acastanhado),\nelevação importante da creatina quinase sérica (20 vezes acima do normal), hipercalemia e\nhipocalcemia. Qual deve ser a conduta imediata?","options":{"A":"Hemodiálise.","B":"Hidratação vigorosa.","C":"Manitol endovenoso.","D":"Alcalinização da urina."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-199752","number":"199752","sourceNumber":"199752","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um senhor de 65 anos, após uma consulta de rotina com toque retal normal, retorna ao\nmédico do PSF com um resultado de PSA total de 8 ng/ml (normal até 4,00 ng/ml). Ele está muito\napreensivo, pois há cerca de um ano fez o mesmo exame e o resultado fora normal. Qual deve ser\na conduta?","options":{"A":"Tranquilizar o paciente e repetir o exame no próximo ano.","B":"Encaminhar para biópsia prostática em serviço especializado.","C":"Solicitar novo exame para confirmar elevação persistente do PSA.","D":"Administrar antibiótico (quinolona) e repetir o exame após o tratamento."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-199825","number":"199825","sourceNumber":"199825","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Mulher de 34 anos, com história prévia de 3 cálculos renais, apresentou há 4 meses as\nmensurações em urina de 24h demonstradas na tabela a seguir. Recebeu orientações alimentares\ne prescrição de indapamida e citrato de potássio. Retornou em uso das medicações com novas\ndosagens em urina de 24h demonstradas na tabela a seguir. Ácido úrico, fósforo, potássio e pH\nséricos encontram-se em níveis adequados. Valores de referência encontram-se na tabela. Quais\ndos alimentos, se restritos, têm a maior chance de melhorar o perfil urinário atual da paciente?","options":{"A":"Fast-food e processados.","B":"Gorduras saturadas e trans.","C":"Limão e frutas cítricas.","D":"Leite e seus derivados."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-2/199825.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-172964","number":"172964","sourceNumber":"172964","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Homem vítima de queimadura circunferencial de segundo e terceiro graus em perna\ndireita, desde o joelho até o tornozelo, apresenta dor, formigamento, dormência e edema no pé\ndireto após cinco dias de tratamento em unidade de referência. Diante do quadro, qual a conduta\nmais adequada?","options":{"A":"Curativo com antibiótico nas áreas de terceiro grau.","B":"Pedido de parecer do cirurgião vascular e neurologista.","C":"Escarotomia longitudinal nas faces medial e lateral da perna.","D":"Desbridamento cirúrgico se pressão intramuscular maior que 20 mmHg."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-172996","number":"172996","sourceNumber":"172996","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Uma mulher de 72 anos apresenta um fístula duodenal de alto débito, cerca de 1.100\nml ao dia, após rafia de uma úlcera\nperfurada. A Equipe Multidisciplinar de Terapia Nutricional,\ninicialmente, indicou NPT. A paciente foi submetida a NPT por 15 dias de forma exclusiva. Há 2\ndias, passou a apresentar débito de 300 ml por dia pela fístula, encontra-se sem sinais de infecção\ne hemodinamicamente estável, o abdome é flácido, tem ruídos hidroaéreos normais. Considerando\na resposta à terapia nutricional ministrada a essa paciente, pergunta-se: qual a melhor estratégia\npara recuperação da condição nutricional e imunológica dessa paciente?","options":{"A":"Iniciar dieta enteral balanceada por sonda gastrojejunal.","B":"Realizar jejunostomia para programação de alta.","C":"Iniciar dieta oral com alto teor de proteína.","D":"Manter nutrição parenteral exclusiva."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-150792","number":"150792","sourceNumber":"150792","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Homem de 56 anos, agricultor, tabagista desde os 12 anos de idade, apresentou há 8\nmeses neoplasia de laringe com clara\ndificuldade progressiva de alimentar-se. Atualmente, apenas\ndeglute água com dificuldade. Paciente pesava 76 Kg há 6 meses, apresentando peso atual de 54\nKg, com IMC de 16,66 Kg/m2. O oncologista indicou tratamento de radioterapia e traqueostomia e,\napós esse tratamento, nova avaliação para possível esofagolarigectomia radical com retalho jejunal\nmicrocirúrgico. Qual a melhor via de alimentação para esse paciente, nesse momento?","options":{"A":"Sonda nasogástrica ou nasoenteral.","B":"Gastrostomia endoscópica.","C":"Gastrostomia a Stamm.","D":"Jejunostomia a Witzel."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-126940","number":"126940","sourceNumber":"126940","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em qual das seguintes situações, o uso de antibioticoprofilaxia está melhor indicada?","options":{"A":"Mulher de 43 anos a ser submetida a retirada de nódulo mamário.","B":"Homem de 47 anos a ser submetido a comissurotomia valvar percutânea.","C":"Mulher de 50 anos a ser submetida a laparotomia por diverticulite perfurada.","D":"Homem de 25 anos a ser submetido a drenagem de hematoma intracraniano."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-126970","number":"126970","sourceNumber":"126970","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente masculino, 33 anos, maratonista profissional, foi submetido há 6 meses a uma\nhernioplastia inguinal direita pela técnica de Shouldice. Paciente evoluiu satisfatoriamente,\nretomando o seu treinamento após 3 meses do tratamento cirúrgico. Há 2 meses, sentiu dor em\n\n?fisgada? na região inguinal direita, que evoluiu com aumento de intensidade e duração, impedindo\no mesmo de continuar suas atividades\ndesportistas. Procurou atendimento médico, apresentando,\nao exame físico, presença de massa palpável redutível e indolor na fossa ilíaca direita. Em relação\na esse paciente, qual das seguintes cirurgias seria mais adequada?","options":{"A":"Reparo à McVay.","B":"Reparo de Stoppa.","C":"Reparo de Bassini.","D":"Reparo laparoscópico transabdominal."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-102092","number":"102092","sourceNumber":"102092","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente de 68 anos, sexo feminino, internada na noite anterior como pré-operatório de\numa artroplastia total do joelho direito, a qual\ndeverá ser realizada no dia seguinte. No que diz\nrespeito aos sistemas de segurança exigidos, qual das opções abaixo NÃO faz parte da lista de\nverificação pré-operatória a ser checada no centro cirúrgico, imediatamente antes da indução\nanestésica, por toda a equipe cirúrgica?","options":{"A":"Revisão da história clínica.","B":"Identidade correta do paciente.","C":"Posição do paciente, sítio e lado corretos.","D":"Disponibilidade de implantes e equipamentos necessários."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-81236","number":"81236","sourceNumber":"81236","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Homem de 62 anos compareceu ao ambulatório de cirurgia queixando-se de\nabaulamento na região inguinal direita há\nseis meses. No exame físico da região inguinal,\nobservam-se alargamento de 4 cm de diâmetro dos anéis inguinais e defeito da parede posterior do\ncanal inguinal, à direita. O paciente refere uma ?tumoração? que desce às vezes para o saco\nescrotal, à direita, sendo reduzido por ele manualmente. Diante do quadro clínico, o provável\ndiagnóstico, tratamento, e complicação pós-operatória mais frequentes são, respectivamente:","options":{"A":"Hérnia inguino-escrotal indireta, hernioplastia por videolaparoscopia e neuralgia (dor).","B":"Hérnia inguino-escrotal direta, hernioplastia com tela e neuralgia (dor).","C":"Hérnia inguino-escrotal, hernioplastia com tela e retenção urinária.","D":"Hérnia inguino-escrotal direta, hernioplastia com tela e seroma."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-81259","number":"81259","sourceNumber":"81259","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente masculino, 60 anos, pós-operatório tardio de fratura do colo do fêmur\nesquerdo, comparece à emergência com quadro de\ndor intensa na perna contralateral. Ao exame,\napresenta hipersensibilidade difusa no membro comprometido e edema depressível em toda a\nperna, mais intenso na região da panturrilha, que está com diâmetro 5 cm maior em relação à perna\nesquerda. Não há eritema. Qual o exame mais indicado para comprovação da hipótese diagnóstica\nmais provável nesse caso?","options":{"A":"Venografia.","B":"Dosagem de d-dímero.","C":"Angiotomografia venosa.","D":"Ultrassonografia com Doppler."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-65760","number":"65760","sourceNumber":"65760","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente foi admitido no centro cirúrgico para submeter-se a uma colecistectomia\nvideolaparoscópica. O momento inicial da indução foi interrompido pela entrada abrupta da\nenfermeira comunicando que o paciente estava, na verdade, agendado para cirurgia cardíaca.\n\nUtilizando como base as sugestões da OMS para concepção de uma cultura organizacional de\nsegurança do paciente, qual deve ser a atitude do chefe do centro cirúrgico em relação ao caso?","options":{"A":"Atribuir responsabilidade exclusiva à equipe cirúrgica responsável pela cirurgia e puni-la.","B":"Atribuir responsabilidade exclusiva à equipe de enfermagem do centro cirúrgico e puni-la.","C":"Atribuir responsabilidade exclusiva à equipe de enfermagem da enfermaria de cirurgia e puni-la.","D":"Mobilizar recursos para rever o processo de comunicação na admissão de pacientes no centro\ncirúrgico.","E":"Reconhecer o fato como erro natural e factível no ambiente do centro cirúrgico, sem notificar,\nevitando alardes."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-65779","number":"65779","sourceNumber":"65779","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente feminina, 57 anos, 60 kg, com sepse urinária, evolui com hipotensão, mesmo\napós infusão de 2.500 ml de solução\nfisiológica 0,9% nos últimos 30 minutos. Após passagem do\ncateter de artéria pulmonar, os dados da monitorização hemodinâmica e respiratória revelaram:\npressão venosa central normal; pressão de oclusão da artéria pulmonar baixa; índice cardíaco\nbaixo; resistência vascular periférica normal; saturação venosa central baixa e taxa de extração de\noxigênio alta. O hemograma revela hemoglobina de 10 g/dl, leucócitos de 24.000/mm³ com desvio à\nesquerda e plaquetas normais. Neste momento, em termos de abordagem hemodinâmica, a melhor\nconduta seria:","options":{"A":"cristaloide.","B":"dobutamina.","C":"vasopressina.","D":"noradrenalina.","E":"hemotransfusão."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-51205","number":"51205","sourceNumber":"51205","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Quanto à classificação de sítio cirúrgico, qual das alternativas abaixo é classificada\ncomo do tipo incisional profunda?","options":{"A":"Celulite.","B":"Abscesso hepático.","C":"Abscesso subfrênico.","D":"Fasceíte necrotizante."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-141607","number":"141607","sourceNumber":"141607","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O rastreamento sobre o câncer de próstata ainda gera muito debate na comunidade\ncientífica internacional. Sobre este tema, assinale a alternativa CORRETA:","options":{"A":"Seu principal fator de risco é o tabagismo.","B":"O U.S. Preventive Services Task Force e o Canadian Task Force on Preventive Health Care\nindicam o rastreio com PSA para homens assintomáticos acima de 75 anos de idade.","C":"Uma das funções do PSA é a distinção dos graus de agressividade dos tumores de próstata.","D":"O nível de evidência ainda é insuficiente para tecer recomendações a favor ou contra a adoção\ndo rastreamento para o câncer de próstata em\nhomens assintomáticos com idade inferior a 75\nanos."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-45402","number":"45402","sourceNumber":"45402","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação ao estudo das hérnias, é verdadeiro afirmar:","options":{"A":"A maioria das hérnias estranguladas é direta.","B":"As hérnias femorais apresentam baixas taxas de estrangulamento e recomenda-se que todas as\nhérnias femorais sejam reparadas no momento de seu diagnóstico.","C":"O ligamento de Cooper é formado pelo periósteo e pela fáscia ao longo do ramo superior do\npúbis.","D":"Na classificação de Nyhus, a hérnia tipo IIIa é uma hérnia inguinal indireta e com destruição da\nparede posterior.","E":"Lesão do nervo genitofemoral é causa importante de orquite isquêmica."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-36980","number":"36980","sourceNumber":"36980","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Qual dos pacientes abaixo possui maior risco de morbimortalidade cardíaca no período\nintraoperatório e pós-operatório?","options":{"A":"Homem de 38 anos, submetido à toracotomia de emergência.","B":"Homem de 72 anos que apresenta terceira bulha (B3) à ausculta cardíaca.","C":"Mulher de 42 anos que apresenta mais de cinco extrasístoles no eletrocardiograma.","D":"Mulher de 55 anos que apresenta creatinina sérica de 3,5 mg/dL."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-32549","number":"32549","sourceNumber":"32549","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre os distúrbios acidobásicos, podemos afirmar corretamente que:","options":{"A":"As células renais captam o lactato e um próton e os convertem de volta em glicose, em um\nprocesso enzimático denominado gliconeogênese.","B":"Fístula duodenal ou diarreia podem fazer perder bicarbonato o suficiente para induzir acidemia.","C":"O nível de gás sanguíneo arterial de um paciente em cetoacidose diabética mostra alto pH e\nconcentração de bicarbonato deprimida.","D":"A cetoacidose diabética geralmente cursa com hipercalemia associada.","E":"Nos pacientes alcoólicos que desenvolvem uma síndrome de cetoacidose o\nmecanismo fisiopatológico é a deficiência de insulina."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-30915","number":"30915","sourceNumber":"30915","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, 42 anos, 48 kg, perdeu 25 kg em 4 meses, albumina pré-operatória 2,8 g/dl,\napresentava obstrução esofágica total por neoplasia de esôfago, realizou esofagectomia total e\njejunostomia. Encontra-se na UTI pós-operatória, está no sexto dia de pós-operatório, em dieta\nzero, extubado, hemodinamicamente estável. Ao exame o abdome mostra-se flácido, ruídos\nhidroaéreos presentes. Qual a conduta mais adequada em relação ao suporte nutricional deste\npaciente?","options":{"A":"Iniciar alimentação hipercalórica, hiperproteica e imunomoduladora via jejunostomia.","B":"Iniciar alimentação hipercalórica, hiperproteica via oral.","C":"Iniciar alimentação hipercalórica, hiperproteica via parenteral.","D":"Iniciar alimentação hipercalórica, hiperproteica e imunomoduladora via parenteral.","E":"Ainda não é o momento para iniciar o suporte nutricional."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-22949","number":"22949","sourceNumber":"22949","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Marcadores tumorais são moléculas secretadas pelas células tumorais que podem ser\ndetectados no sangue, fluido e tecidos. Podem também ser úteis como rastreadores, no diagnóstico\nou como fator prognóstico de certas neoplasias. São características de um marcador tumoral ideal,\nEXCETO:","options":{"A":"um marcador deve detectar a doença antes de seu aparecimento disseminado","B":"o teste para o marcador tumoral deve ser sensível, ou seja, sem resultado falso negativo","C":"o teste para o marcador tumoral deve ser específico, ou seja, sem resultado falso positivo","D":"o nível do marcador detectado na amostra biológica não precisa se correlacionar com o tamanho\ndo tumor","E":"o teste para o marcador tumoral deve ser barato o bastante para permitir seu uso para a triagem\nem um grande número de pacientes"},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-27718","number":"27718","sourceNumber":"27718","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação às hérnias, assinale a opção correta.","options":{"A":"A hérnia umbilical infantil é de tratamento cirúrgico na grande maioria das vezes.","B":"A hérnia inguinal indireta com anel inguinal interno dilatado e com aparelho posterior preservado\né classificada como tipo III de Nyhus.","C":"Nas hérnias por deslizamento as vísceras mais comumente envolvidas são o cólon e o intestino\ndelgado.","D":"A hérnia de Spigel ocorre devido fraqueza na fáscia do canal obturador.","E":"A complicação cirúrgica mais comum das hérnias é a infecção da ferida cirúrgica."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-27743","number":"27743","sourceNumber":"27743","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre as medidas preventivas para infecção em área cirúrgica, assinale o item correto.","options":{"A":"A estadia pré-operatória curta, o banho antisséptico e a retirada apropriada de pelos não são\nmedidas efetivas na prevenção de infecção.","B":"A antibioticoprofilaxia deve ser realizada em todo paciente submetido à cirurgia sob anestesia\ngeral, pois nesses casos a chance de infecção\né maior.","C":"Tempo cirúrgico prolongado, gravidade do paciente e uso de prótese são critérios de risco que\njustificam o uso de antibióticos profiláticos.","D":"Não há diferença de eficácia na administração pré e transoperatória do antibiótico na profilaxia\nde infecções","E":"O uso estendido de antibioticoprofilaxia por mais de 24 horas diminui de forma significativa a\nchance de infecção de ferida operatória."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-27774","number":"27774","sourceNumber":"27774","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"De acordo com a classificação do risco cirúrgico da Sociedade Americana de\nAnestesiologistas (ASA), paciente com doença sistêmica grave que limita atividades, mas não o\ndeixa incapacitado é classificado como ASA:","options":{"A":"I","B":"II","C":"III","D":"IV","E":"V"},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-365615","number":"365615","sourceNumber":"365615","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente de 35 anos de idade foi admitido no pronto-socorro após um acidente\nautomobilístico grave. Ele apresenta\nmúltiplas fraturas, contusões e lacerações. O paciente está\nhemodinamicamente estável e consciente, mas exibe sinais evidentes de estresse metabólico. Na\nadmissão, os sinais vitais apresentavam PA = 110 mmHg x 70 mmHg, FC = 100 bpm, FR = 22 irpm\ne temperatura = 38.5 °C. Ele realizou exames laboratoriais, os quais demonstraram hemograma\ncom leucocitose, glicemia = 200 mg/dL, cortisol sérico elevado e insulina reduzida. Considerando a\nresposta endócrina e metabólica ao trauma apresentada, pelo paciente, qual é o principal\nmecanismo responsável pela elevação da glicemia?","options":{"A":"Hiperinsulinemia secundária ao estresse","B":"Aumento da sensibilidade à insulina","C":"Liberação de catecolaminas e cortisol","D":"Supressão da produção hepática de glicose"},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-349768","number":"349768","sourceNumber":"349768","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Os tecidos tentam restaurar a sua função normal e a integridade estrutural após uma\nlesão, passando pelo processo de cicatrização. Quais são as 3 fases desse processo, em ordem\ncronológica, e suas respectivas características?","options":{"A":"Fase reativa (proliferação e migração epitelial), fase de maturação (regeneração do tecido\nconjuntivo) e fase proliferativa (proliferação de colágeno e formação da cicatriz).","B":"Fase inflamatória (hemostasia e quimiotaxia), fase proliferativa (regeneração do tecido\nconjuntivo) e fase de maturação (contração, formação e remodelamento da cicatriz).","C":"Fase inflamatória (hemostasia e inflamação), fase regenerativa (formação e contração da\ncicatriz) e fase de remodelagem (migração epitelial e proliferação/regeneração do tecido\nconjuntivo).","D":"Fase de remodelagem (hemostasia e quimiotaxia), fase reativa (proliferação e migração epitelial)\ne fase maturacional (contração e formação da\ncicatriz).","E":"Fase proliferativa (migração e proliferação epitelial), fase maturacional (contração e formação\nda\ncicatriz) e fase reativa (hemostasia e quimiotaxia)."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-322135","number":"322135","sourceNumber":"322135","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Os pacientes submetidos à ressecção cirúrgica de lesões extensas de pele,\ngeralmente, necessitam de retalho ou enxerto como\nauxílio no fechamento do defeito. Assinale a\nalternativa que caracteriza corretamente as técnicas empregadas nessas situações.","options":{"A":"Enxerto que é um segmento de pele, sem o subcutâneo, com suprimento vascular próprio,\nrotacionado para a área doadora.","B":"Enxerto que é um pedaço de pele retirado de uma área corpórea e transferido para outra área\ncom um pedículo de comunicação entre as\náreas.","C":"Retalho que é um segmento da pele e subcutâneo com suprimento vascular próprio, que será\nmovido de uma área (doadora) para outra\n(receptora), existindo uma comunicação do retalho com a\nárea doadora por meio de um pedículo.","D":"Retalho que é um segmento de pele e subcutâneo sem nenhum pedículo de comunicação entre\neles. Só mais tardiamente desenvolve vascularização própria, restabelecendo, assim, um novo\nsuprimento sanguíneo.","E":"Geralmente o enxerto (área doadora) é retirado de pele adjacente, em continuidade com o\ndefeito, obtendo assim melhores resultados."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-322138","number":"322138","sourceNumber":"322138","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente de 57 anos possui uma lesão esofágica estenosante e não transponível ao\naparelho de endoscopia em nível de esôfago médio/distal, com biópsia revelando carcinoma\nepidermoide escamoso. O paciente iniciará tratamento com radioterapia e quimioterapia\nneoadjuvantes, porém está com ingesta praticamente nula de alimentos há vários dias. Qual é a\nmelhor estratégia cirúrgica de via alimentar a ser indicada para esse paciente?","options":{"A":"Realizar uma gastrostomia endoscópica.","B":"Realizar uma gastrostomia laparoscópica.","C":"Realizar uma jejunostomia.","D":"Realizar uma íleostomia.","E":"Realizar uma esofagostomia."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-322139","number":"322139","sourceNumber":"322139","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente de 74 anos recebeu o diagnóstico de HPB (Hiperplasia Prostática\nBenigna), e o médico indicou duas medicações\npara o tratamento dessa afecção e seus sintomas:\na tansulosina e a finasterida. Qual é a melhor explicação que pode ser dada sobre o efeito desses\ncompostos ao paciente?","options":{"A":"A tansulosina atua diminuindo o volume prostático, e a finasterida contribui para o relaxamento\nda musculatura na saída da bexiga; ambas facilitam a\nsaída do jato urinário.","B":"A tansulosina contribui para o relaxamento da musculatura na saída da bexiga, e a finasterida\natua diminuindo o volume prostático; ambas facilitam\na saída do jato urinário.","C":"A tansulosina contríbui para a contração do corpo da bexiga, e a finasterida age relaxando a\nmusculatura na saída da bexiga; ambas facilitam a saída do jato urinário.","D":"A tansulosina atua na contração da musculatura da próstata, e a finasterida contribui no\naumento da contração da musculatura detrusora da bexiga; ambas facilitam a saída do jato\nurinário.","E":"A tansulosina contribui para o relaxamento da musculatura na saída da bexiga, e a finasterida\natua relaxando a musculatura prostática; ambas\nfacilitam a saída do jato urinário."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-322141","number":"322141","sourceNumber":"322141","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente chega ao hospital com febre há 2 dias e dor em região lombar direita. Ao\nrealizar exames, recebe o diagnóstico de ureterolitíase obstrutiva à direita, com hidronefrose\nipsilateral, alteração significativa da função renal a infecção associada com sinais de sepse. Qual\né\na melhor abordagem para esse paciente?","options":{"A":"Administração de anti-inflamatórios não esteroidais e analgésicos e realização de litotripsia\nureteroscópica de urgência.","B":"Compensação clínica sintomática, administração de antibióticos e litotripsia extracorpórea - por\nser o método menos invasivo para o paciente\nnesse momento.","C":"Analgesia, prescrição de alfa-bloqueadores, como a doxazosina, e litotripsia ureteroscópica de\nurgência.","D":"Analgesia e reposição volêmica, anti-inflamatórios não esteroidais e, por cistoscopia,\ndescompressão do trato urinário superior à\ndireita com urgência, além de inserção de cateter\nureteral (duplo J) retrógrado ou por inserção de nefrostomia percutânea.","E":"Compensação clínica sintomática, administração de antibióticos e, por cistoscopia,\ndescompressão do trato urinário superior à direita\ncom urgência, além de inserção de cateter\nureteral (duplo J) retrógrado ou por inserção de nefrostomia percutânea."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-322160","number":"322160","sourceNumber":"322160","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um homem de 54 anos procura atendimento médico com queixa de dor ao urinar e\nurgência miccional. O diagnóstico de prostatite é estabelecido e a urocultura mostra crescimento de\npseudomonas aeruginosa. Diante do exposto, assinale a alternativa correta.","options":{"A":"A pseudomonas aeruginosa é responsável pela maioria dos casos de prostatite bacteriana\naguda.","B":"O quadro clínico geralmente é pouco sintomático.","C":"A incidência de neoplasia de próstata é comum nesses casos.","D":"A macrodantina é o antimicrobiano de escolha nesses casos.","E":"O uso de ertapenem está contraindicado."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-305271","number":"305271","sourceNumber":"305271","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente negro de 28 anos necessita de avaliação quanto a uma cicatriz de\ncrescimento exagerado em região de lóbulo da orelha, além dos limites de onde havia uma ferida\nprévia. Qual das seguintes orientações deve-se fornecer ao paciente?","options":{"A":"Trata-se, provavelmente, de cicatriz hipertrófica que deve regredir em breve.","B":"Trata-se, provavelmente, de um câncer de pele escamocelular, comum nessa região.","C":"Trata-se, provavelmente, de queloide, mais comum entre pacientes negros e que não possuem\nforma de prevenção clara.","D":"Trata-se, provavelmente, de queloide, mais comum entre pacientes caucasianos, que são\nprontamente resolvidos de maneira cirúrgica.","E":"Trata-se, provavelmente, de cicatriz hipertrófica, mais comum entre pacientes negros e que são\nfacilmente resolvidas de maneira cirúrgica."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-305273","number":"305273","sourceNumber":"305273","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Para uma boa avaliação da necessidade nutricional de um paciente, é necessário\nprever sua taxa metabólica basal, a qual pode\nser calculada por meio da equação de\n\nHarris-Benedict, que leva em consideração:","options":{"A":"peso em kg, altura em cm e Vco2 (volume de gás carbônico expirado).","B":"altura em m, superfície corpórea em m² e temperatura corporal em ºC.","C":"peso em kg, altura em m e fator de estresse, que exige multiplicação por 1,2 a 1,5 em pacientes\ncom sepse.","D":"peso em g, altura em cm e frequência cardíaca em bpm.","E":"altura em cm, peso em kg e fator de estresse, que exige multiplicação por 1,1 a 1,2 para\npacientes submetidos à cirurgia eletiva."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-305282","number":"305282","sourceNumber":"305282","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"No pronto atendimento, um paciente foi admitido com queimaduras extensas de grau 2\nem regiões de face e pescoço, provocadas por\nágua fervendo. Assinale a alternativa que apresenta\na melhor abordagem a ser feita nesse paciente.","options":{"A":"Avaliação da superfície corpórea atingida; analgesia e curativo com óleo de girassol nas\nferidas.","B":"Analgesia e, após 1h, reavaliação da dor e início da avaliação secundária quanto aos cuidados\ncom as queimaduras ? fazer apenas cobertura\ndas lesões com gaze para não causar mais dor à\nmanipulação.","C":"Acalmar o paciente; ressuscitação volêmica utilizando a fórmula de Parkland ? 1,5 ml/kg/% de\nsuperfície corpórea queimada; analgesia e curativo com sulfadiazina de prata nas feridas.","D":"Analgesia; ressuscitação volêmica utilizando a fórmula de Brooke ? 4 ml/kg/% de superfície\ncorpórea queimada ? e curativo com neomicina nas\nferidas.","E":"Avaliação quanto à possível lesão direta de via aérea; ressuscitação volêmica utilizando a\nfórmula de Parkland ? 4 ml/kg/% de\nsuperfície corpórea queimada ? juntamente com a analgesia, e\ncurativo com sulfadiazina de prata nas feridas."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-274341","number":"274341","sourceNumber":"274341","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação às fases e processos da cicatrização, é CORRETO afirmar que:","options":{"A":"Há, na fase inflamatória, secreção de citocinas e migração de células para a ferida por\nquimiotaxia.","B":"A adesão das plaquetas ao endotélio é mediada principalmente pelas prostaglandinas.","C":"Ocorrem, na fase de maturação da ferida, principalmente, a angiogênese e a formação de tecido\nde granulação.","D":"A fase de proliferação se inicia após a fase de maturação, com formação de arranjos de\ncolágeno.","E":"Os fibroblastos começam a produzir colágeno na fase de maturação."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-261208","number":"261208","sourceNumber":"261208","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um menino de 6 anos de idade, foi encaminhado ao consultório com relato de aumento\ndo volume testicular progressivo há cerca de\num ano. Ao exame físico, constataram-se FC = 85\nbpm; FR = 18 ipm; e SatO2 = 98%, com abaulamento inguinal à esquerda, que piora às manobras\nde esforço, com identificação de tumefação que desce através do canal inguinal. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Após a instituição do\ntratamento, espera-se aumento dos níveis séricos de IL-6.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-250130","number":"250130","sourceNumber":"250130","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Uma paciente de 44 anos de idade queixa-se de dor abdominal, principalmente em\nhipocôndrio direito, que se iniciou há dois dias. Relata febre de 38 ºC, associada ao quadro, além\nde náuseas. Ao exame, encontrava-se em bom estado geral, desidratada +/4+, anictérica, com\nabdome plano, flácido, doloroso à palpação em hipocôndrio direito e com defesa em hipocôndrio\ndireito. Realizou hemograma, que mostrou 14.500 leucócitos (normal até 10.000), bilirrubinas totais\nde 0,7 (normal até 1) e amilase de 137 (normal até 110). Fez ultrassom, que mostrou vesícula\naumentada de volume, com múltiplos cálculos de até 1,2 cm em seu interior e com paredes\ndelaminadas e com espessura de 6 mm. Com base nesse caso hipotético e nos conceitos médicos\na ele associados, julgue o item a seguir. Em geral, no pós-operatório de uma colecistectomia, a\nintrodução de dieta para o paciente deve ser lenta e progressiva, podendo levar, em média, de dois\na três dias para assegurar que o paciente receba alta em plenas condições e sem íleo adinâmico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-214467","number":"214467","sourceNumber":"214467","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente de 35 anos de idade, trabalhador braçal, é portador de hérnia inguinal à\ndireita e realizará correção cirúrgica dela (hernioplastia inguinal direita) hoje. O paciente\n\nencontra-se na sala cirúrgica. Em relação ao uso de antibióticos nesse paciente e considerando os\nconhecimentos médicos correlatos, julgue o item a seguir. O correto seria prescrever\nantibioticoterapia por via oral, com cefalosporina de primeira geração, três dias antes do\nprocedimento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-214475","number":"214475","sourceNumber":"214475","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente de 35 anos de idade, trabalhador braçal, é portador de hérnia inguinal à\ndireita e realizará correção cirúrgica dela (hernioplastia inguinal direita) hoje. O paciente\n\nencontra-se na sala cirúrgica. Em relação ao uso de antibióticos nesse paciente e considerando os\nconhecimentos médicos correlatos, julgue o item a seguir. Se a cirurgia do paciente mencionado\nfosse uma colecistectomia videolaparoscópica, a antibioticoprofilaxia seria realizada com uma\ncefalosporina de primeira geração (usualmente cefazolina ou cefalotina 1-2 g EV), por se tratar de\numa cirurgia potencialmente contaminada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-214486","number":"214486","sourceNumber":"214486","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente de 35 anos de idade, trabalhador braçal, é portador de hérnia inguinal à\ndireita e realizará correção cirúrgica dela (hernioplastia inguinal direita) hoje. O paciente\n\nencontra-se na sala cirúrgica. Em relação ao uso de antibióticos nesse paciente e considerando os\nconhecimentos médicos correlatos, julgue o item a seguir. O uso profilático de antimicrobianos em\ncirurgia consiste na administração deles a fim de reduzir a ocorrência de infecções associadas a\nesses procedimentos. As recomendações para antibioticoprofilaxia em cirurgia enfatizam a\nadministração do antimicrobiano correto, no momento certo e pelo maior tempo possível.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-196654","number":"196654","sourceNumber":"196654","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente de 65 anos de idade compareceu ao urologista por apresentar hematúria\nmacroscópica, emagrecimento de 5 kg em dois meses e dor abdominal. Ao exame físico, o médico\nencontrou uma massa palpável em região de flanco esquerdo. Solicitou então uma tomografia\ncomputadorizada de abdome, demonstrada na imagem a seguir. Com base nesse caso clínico e\nnos conhecimentos médicos correlatos, julgue o item a seguir. Provavelmente se trata de um cisto\nBosniak II e, em razão das proporções, o tratamento é nefrectomia parcial.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-2/196654.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-214440","number":"214440","sourceNumber":"214440","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente de 67 anos de idade demonstra quadro de dificuldade miccional\nprogressiva, há cerca de dois anos, com\ninfecções urinárias recorrentes e episódios de hematúria,\ne por isso procura o urologista. Ao exame de toque retal, apresenta próstata aumentada de\ntamanho, de bordos regulares e consistência fibroelástica. O urologista, então, indica o\nprocedimento cirúrgico chamado ressecção transuretral de próstata (RTU). Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. No caso descrito, se o\npaciente apresentasse distúrbio da coagulação, a raquianestesia (anestesia geralmente empregada\nnesse tipo de procedimento) estaria contraindicada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-211999","number":"211999","sourceNumber":"211999","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um menino de 13 anos de idade chega ao pronto-socorro acompanhado pela mãe,\napós queimar-se com óleo quente nas mãos (dorso,\npalma e dedos bilateralmente). A mãe refere\nque estava fritando batatas com óleo quando o incidente aconteceu. O garoto queixa-se de dor\nintensa no local e nega outras queimaduras. Ao exame, o dorso da mão do paciente encontra-se\ncom edema, eritema, bolhas, aspecto úmido e extremamente doloroso ao toque. A palma da mão\napresenta dor ao exame e eritema, e não contém bolhas. Com base nesse caso clínico, no que se\nrefere às queimaduras, assinale a alternativa CORRETA.","options":{"A":"Quanto à profundidade, as lesões descritas nas palmas das mãos do paciente são classificadas\ncomo de terceiro grau.","B":"Queimaduras de segundo grau envolvem apenas epiderme, derme e gordura subcutânea.","C":"Em relação à profundidade, as lesões descritas no dorso das mãos do paciente são\nclassificadas como de segundo grau.","D":"Considerando a \"Regra dos Nove\", ferramenta utilizada para cálculo da extensão das\nqueimaduras, a queimadura descrita nesse\ncaso clínico, referente à extensão, é considerada grave,\npois ultrapassa 40% de superfície corporal queimada.","E":"Se esse paciente tivesse sido socorrido por uma equipe médica pré-hospitalar, a atitude mais\ncorreta, relativamente ao tratamento das lesões, seria envolver as mãos do paciente em\ncompressas úmidas com soro fisiológico gelado."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-179202","number":"179202","sourceNumber":"179202","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O reparo de feridas é um fenômeno biológico de resposta dos tecidos lesados na\ntentativa de restaurar a função e a estrutura normais após o trauma. Acerca do processo de\ncicatrização de feridas, assinale a alternativa correta.","options":{"A":"Em uma ferida grande, como uma úlcera de pressão, a escara ou o exsudato fibrinoso refletem a\nfase proliferativa.","B":"O macrófago é a única célula verdadeiramente fundamental para a cicatrização de feridas, pois\nserve para orquestrar a liberação de citocinas e estimular processos subsequentes de cicatrização.","C":"Durante uma lesão tecidual aguda, a lesão dos vasos sanguíneos resulta em vasodilatação local\nintensa, seguida de vasoconstrição e parada do sangramento.","D":"A função primária dos fibroblastos é sintetizar colágeno, que eles começam a produzir durante a\nfase celular da maturação ou regeneração.","E":"O tecido resultante da ferida cicatrizada é repleto de cristas interpapilares, o que\npotencializa a\nancoragem e garante maior resistência à neoepiderme."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-179201","number":"179201","sourceNumber":"179201","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Acerca das queimaduras elétricas, assinale a alternativa correta.","options":{"A":"A área corporal queimada pode ser calculada pela regra dos 9 de Wallace.","B":"A corrente elétrica penetra em uma parte do corpo, como os dedos ou a mão, e progride pela\npele devido à sua baixa resistência.","C":"Os vasos sanguíneos, que transmitem grande parte da eletricidade, podem progredir para\ntrombose progressiva.","D":"As lesões de baixa voltagem também estão associadas à destruição oculta de tecidos\nprofundos, com graus variáveis de queimaduras cutâneas nos sítios de entrada e saída.","E":"A monitorização cardíaca contínua é necessária para todo paciente vítima de choque elétrico\nnas primeiras 72 horas de internação devido ao\nalto risco de desenvolvimento de arritmias\ncardíacas malignas e parada cardíaca."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-152098","number":"152098","sourceNumber":"152098","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Considere hipoteticamente que o paciente R. A. S., de 60 anos de idade, agenda\nconsulta ambulatorial de retorno para entregar\nresultados de uma endoscopia digestiva alta e de\numa ultrassonografia de rins e vias urinárias. O paciente trouxe receita do vizinho que teve o\nmesmo problema de saúde, porém melhorou após o uso de determinados medicamentos\nprescritos. R. A. S. apresenta antecedente pessoal de fratura exposta da tíbia com dano extenso às\npartes moles e antecedente familiar de acalasia no pai. Estava ansioso porque, após pesquisa na\ninternet, assemelhou os respectivos sintomas aos de alguns tipos de câncer. Com base nesse caso\nclínico, e considerando os conhecimentos médicos a ele relacionados, julgue o item a seguir. Em\nrelação à anatomia dos rins, em decorrência do contorno do músculo psoas, ambos os rins\n\nsituam-se obliquamente, com o polo superior localizado mais medialmente que o inferior.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-135041","number":"135041","sourceNumber":"135041","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"No próximo item é apresentado um caso clínico seguido de uma assertiva a ser julgada.\nUma paciente acamada, vítima de acidente vascular cerebral há seis meses, em uso de sonda\nnasoenteral para alimentação em virtude de disfagia orofaríngea grave sem perspectiva de\nregressão, foi encaminhada ao serviço de endoscopia digestiva para realização de gastrostomia\nendoscópica. Nessa situação, sabendo que a paciente faz uso de AAS e clopidogrel, deve-se\ninterromper o uso dessas medicações, respectivamente, sete e cinco dias antes do procedimento,\npodendo substituí-las por heparina de baixo peso molecular.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-135085","number":"135085","sourceNumber":"135085","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação à febre reumática, julgue o seguinte item. Os pacientes portadores de\nestenose mitral decorrente de febre\nreumática, que tenham indicação de hernioplastia inguinal com\ncolocação de tela de prolene, deverão ser submetidos à antibioticoprofilaxia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-105556","number":"105556","sourceNumber":"105556","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A adequada preparação pré-operatória, em operações eletivas, está diretamente\nrelacionada com menor morbidade pós-operatória, Acerca da avaliação laboratorial do estado\nnutricional, assinale a alternativa correta.","options":{"A":"A dosagem de proteínas totais, especialmente devido à dosagem de globulinas, é o exame de\nmaior especificidade no diagnóstico da desnutriçao.","B":"A proteína carreadora de retinol apresenta grande sensibilidade à restrição calórica e proteica e\nsua meia-vida é de apenas doze horas.","C":"A pré-albumina é de síntese hepática e está relacionada com o transporte de hormônios das\nglândulas suprarrenais.","D":"A transferrina é sintetizada na medula óssea e é dependente da concentração de ferro sérico.","E":"A dosagem de hemoglobina apresenta a maior sensibilidade quando comparada com as demais\nproteínas intracelulares."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-79669","number":"79669","sourceNumber":"79669","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Após reparo aberto de hérnia inguinal, há complicações. Assinale a alternativa que se\nrefere às complicações de longo prazo.","options":{"A":"Retenção urinária.","B":"Intraoperatórias.","C":"Neuralgia e dor.","D":"Seroma.","E":"Complicações potencialmente fatais."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-52603","number":"52603","sourceNumber":"52603","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação aos cuidados com pacientes durante os períodos pré, trans e\n\npós-operatório, julgue o item que se segue. No sistema de estratificação de riscos de anestesia da\nSociedade Americana de Anestesiologia, a categoria V corresponde a de paciente normal e\nsaudável.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-52601","number":"52601","sourceNumber":"52601","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação aos cuidados com pacientes durante os períodos pré, trans e\n\npós-operatório, julgue o item que se segue. Os pacientes que forem submetidos a operações\neletivas e apresentarem hematócrito inferior\na 30% deverão receber transfusão de concentrado de\nhemácias durante o pré-operatório.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-52599","number":"52599","sourceNumber":"52599","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação aos cuidados com pacientes durante os períodos pré, trans e\n\npós-operatório, julgue o item que se segue. O antibiótico a ser empregado em profilaxia deve ser\nescolhido com base nos patógenos mais comumente encontrados durante o procedimento cirúrgico\ne deve ser administrado antes que seja feita a incisão na pele.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-45742","number":"45742","sourceNumber":"45742","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Quanto à anatomia da parede abdominal, excetuando-se as variações anatômicas,\nassinale a alternativa correta:","options":{"A":"O ligamento de Cooper é formado por fibras aponeuróticas do músculo reto abdominal.","B":"O músculo cremaster origina-se das fibras distais do músculo oblíquo externo.","C":"A fáscia transversal é um componete do assoalho inguinal.","D":"As hérnias inguinais diretas ocorrem lateralmente aos vasos epigástricos inferiores.","E":"O canal inguinal na mulher contém o ligamento inguinal ou de Poupart."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-27569","number":"27569","sourceNumber":"27569","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com o objetivo de reduzir a ocorrência de infecções por Micobactérias de Crescimento\nRápido - MCR - em serviços de saúde, a\npartir do uso de procedimentos cirúrgicos e diagnósticos\npor videoscopias com penetração de pele, mucosas adjacentes, tecidos subepteliais e sistema\nvascular, cirurgias abdominais e pélvicas convencionais, cirurgias plásticas com auxílio de ópticas,\nmamoplastias e procedimentos de lipoaspiração, a ANVISA/MS, publicou em 27 de fevereiro de\n2009, a RDC n° 08 que suspende o uso de:","options":{"A":"agentes esterilizantes líquidos.","B":"vapor úmido ou saturado.","C":"óxido de etileno.","D":"plasma de peróxido de hidrogênio.","E":"autoclave."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-334864","number":"334864","sourceNumber":"334864","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"No atendimento a pacientes vítimas de queimaduras, após a estabilização inicial,\ndeve-se iniciar o processo de transferência para serviço de referência que possa manejar a\n\ncomplexidade do cuidado, caso seja indicado. A respeito da transferência de pacientes queimados\npara centro de referência é correto afirmar\nque","options":{"A":"deve ser imediata em casos graves, pelo risco de complicações respiratórias.","B":"pacientes graves deverão ser acompanhados de médico em ambulância com a possibilidade de\nassistência ventilatória.","C":"o transporte aéreo é o ideal em pacientes com trauma torácico e pneumotórax associados.","D":"têm indicação os pacientes adultos com queimaduras de segundo grau em áreas maiores do\nque 10% da SCQ.","E":"nunca é necessária em queimaduras elétricas ou químicas."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-343432","number":"343432","sourceNumber":"343432","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"As fases do processo de cicatrização de feridas segundo a ordem cronológica é:","options":{"A":"Granulação, maturação e remodelação.","B":"Inflamação, proliferação e maturação.","C":"Granulação, inflamação e reestruturação.","D":"Inflamação, proliferação e regeneração."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-343433","number":"343433","sourceNumber":"343433","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação aos retalhos cutâneos, é CORRETO afirmar:","options":{"A":"O retalho que roda sobre o próprio eixo é direcionado ao defeito, esticando a pele, sem rotação\nou movimento lateral.","B":"O retalho de avanço consiste em um retalho em semicírculo para cobrir um defeito adjacente.","C":"O retalho randomizado possui pedículo definido, recebendo fluxo sanguíneo das artérias\nmiocutâneas.","D":"O retalho axial é adquirido ao longo do eixo de um vaso sanguíneo anatomicamente\nreconhecido."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-307091","number":"307091","sourceNumber":"307091","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente de 75 anos de idade encontra-se em primeiro dia de pós- operatório de\nduodenopancreatectomia por videolaparoscopia, em razão de adenocarcinoma de cabeça de\npâncreas. No que tange à resposta endócrinometabólica esperada para esse paciente, assinale a\nalternativa correta.","options":{"A":"Na primeira fase, considerada fase de choque, o objetivo torna-se perfundir órgãos nobres;\nsendo assim, existe uma situação de redução da\nhomeostase.","B":"Na primeira fase, considerada fase de choque ou EBB flow, para perfundir órgãos vitais, ocorre\naumento da temperatura e do consumo de oxigênio.","C":"Na segunda fase, denominada fase de fluxo, ocorre hipometabolismo com gasto reduzido de\nenergia.","D":"Na segunda fase, há anabolismo muscular proteico e gliconeogênese, com redução da\nresistência à insulina.","E":"A insulina, nessa fase, é um importante hormônio para o catabolismo, estimulando o catabolismo\nproteico e a lipólise."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-307093","number":"307093","sourceNumber":"307093","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sua atividade inicia cerca de 48 horas a 96 horas após o trauma. São as células\ncruciais para cicatrização. Eles realizam o\ntérmino do desbridamento da ferida (fagocitose),\napresenta seus peptídeos às células T, através do complexo maior de histocompatibilidade\n(sistema imune), produz e exporta mediadores (fatores de crescimento) importantes para a fase\nseguinte, a fase proliferativa. As informações apresentadas referem-se a","options":{"A":"linfócitos.","B":"macrófagos.","C":"fibroblastos.","D":"colágeno.","E":"miofibroblastos."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-301324","number":"301324","sourceNumber":"301324","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Quanto aos riscos ocupacionais que podem extrapolar o ambiente de trabalho e atingir\na comunidade, julgue o item a seguir. Na tragédia\nda boate Kiss, as mortes das pessoas presentes\nno local foram causadas pela combinação sinérgica de dois gases da combustão de materiais e\nque atuam ligando-se fortemente à hemoglobina: o monóxido de carbono e o benzeno.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-263339","number":"263339","sourceNumber":"263339","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Uma mulher com 43 anos de idade, com 80kg, sofreu queimadura na perna após\nreceber descarga elétrica há 1 hora. Durante o\natendimento hospitalar, o médico emergencista\npercebeu pequena queimadura em face lateral da coxa direita, de cerca de 5 cm, e outra na face\nlateral do pé do mesmo lado, próxima ao maléolo, de cerca de 2 cm. Ao realizar o exame físico, os\nsinais vitais da paciente estavam estáveis. O médico iniciou hidratação venosa e colocação de\nsonda vesical para monitorar diurese da paciente. Notou saída de cerca de 80 mL de urina um\npouco mais escura que a habitual. Solicitou, então, hemograma e dosagem de creatinina, cujos\nresultados estavam normais. Diante desse quadro, após a internação hospitalar e o curativo das\nlesões, a conduta imediata adequada é indicar","options":{"A":"hidratação venosa com ringer lactato pela fórmula de Parkland e dar alta hospitalar à paciente.","B":"hidratação venosa com soro fisiológico 0,9 % até atingir débito urinário de 60 a 80 mL/hora.","C":"hidratação venosa com ringer lactato até atingir débito urinário de 100 a 200 mL/hora.","D":"hidratação venosa com soro fisiológico 0,9 % até atingir débito urinário de 80 a 100 mL/hora e\nfasciotomia da coxa direita."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-291493","number":"291493","sourceNumber":"291493","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente masculino, 76 anos de idade, vem à consulta com clínica médica por\napresentar dúvidas quanto à frequência com que\ndeve realizar seu exame de próstata. O paciente\ndiz ter feito o exame de PSA várias vezes ao longo dos últimos anos. Traz exame de 3 e de 4 anos\natrás, com PSA = 0,8 ng/ml e 0,78 ng/ml, respectivamente. Nesse caso, o paciente deve ser\nrecomendado a:","options":{"A":"Realizar exame de PSA a cada 5 anos.","B":"Não realizar mais exame de PSA.","C":"Realizar exame de toque retal anual.","D":"Realizar ultrassonografia retal com biópsia."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-263375","number":"263375","sourceNumber":"263375","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um homem com 62 anos de idade retorna à consulta para receber o resultado de\nbiópsia transretal de próstata, procedimento realizado duas semanas antes, cuja classificação\nhistopatológica foi de Gleason 7 (4+3). Esse resultado caracteriza o diagnóstico de","options":{"A":"hiperplasia prostática benigna.","B":"câncer de próstata.","C":"prostatite crônica.","D":"prostatite aguda."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-274629","number":"274629","sourceNumber":"274629","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"As falhas na remodelação da cicatrização, causadas pelo desequilíbrio entre a síntese\ne a degradação do colágeno, bem como em sua\norganização espacial, resultam em cicatrizes\nexuberantes, chamadas cicatrizes hipertróficas e queloides. Considerando as características das\ncicatrizes queloides, é CORRETO afirmar:","options":{"A":"São mais frequentes do que no caso das cicatrizes hipertróficas. Em geral, estão ligadas à\ntensão envolvida no fechamento da ferida.","B":"São elevadas, tensas, pruriginosas, avermelhadas e não ultrapassam as bordas da lesão inicial.","C":"Representam um fenótipo hiperproliferativo que se desenvolve a partir de múltiplos efeitos\nestimuladores.","D":"São extremamente dolorosas e pruriginosas e não respeitam as margens da ferida."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-274634","number":"274634","sourceNumber":"274634","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A circulação cutânea é rica e a demanda metabólica da pele e dos seus elementos é\nbaixa, necessitando apenas de uma pequena fração do potencial possível da circulação cutânea\npara manter sua viabilidade. A irrigação da pele é feita por três principais tipos de artérias. A\nalternativa que apresenta exemplos de artérias cutâneas diretas é:","options":{"A":"Artérias septais entre músculos delgados do antebraço.","B":"Retalho inguinal.","C":"Pele acima do músculo grande dorsal.","D":"Artérias septais entre músculos retos abdominais."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-274638","number":"274638","sourceNumber":"274638","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O aumento da demanda metabólica varia de acordo com a gravidade do trauma\nimposto e a resposta metabólica pode ser\nnotada por vários dias. Considerando o papel do sistema\nnervoso na resposta metabólica, é CORRETO afirmar:","options":{"A":"O sistema nervoso central é responsável pela iniciação da resposta metabólica sistêmica diante\ndo insulto.","B":"O sistema nervoso central atua na transmissão dos sinais aferentes.","C":"O sistema nervoso periférico é responsável pela iniciação da resposta metabólica sistêmica\ndiante do insulto.","D":"O sistema nervoso periférico representa o arco aferente da resposta metabólica."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-291510","number":"291510","sourceNumber":"291510","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um homem, com 72 anos de idade, foi tratado por equipe de atendimento\n\npré-hospitalar após ser resgatado de pequeno quarto sem janelas, em prédio onde ocorreu\nincêndio com combustão de material plástico\ninflamável, havia fumaça no local. Apresentava\nrouquidão, havia fuligem no escarro, os cílios e as sobrancelhas estavam queimados; foram\nevidenciadas queimaduras de segundo e terceiro graus na região anterior do tronco, membro\nsuperior direito e face. Com base nos dados apresentados, assinale a alternativa que apresenta a\nprioridade para o atendimento inicial da vítima.","options":{"A":"Retirar roupas e adereços, resfriar com água fria para interromper o processo de queimadura.","B":"Controlar efetivamente a via aérea com intubação traqueal.","C":"Cobrir a área queimada com campo estéril para auxiliar no alívio da dor.","D":"Obter acesso venoso para hidratação e analgesia."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-291540","number":"291540","sourceNumber":"291540","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"No atendimento de urgências por queimaduras, a avaliação da extensão da superfície\ncorporal queimada (SCQ) do paciente pode ser\nfeita pela \"regra dos nove\", diagrama de Lund e\nBrowder e, mais recentemente, com uso de aplicativos em smartphones. Utilizando a regra dos\nnove em um paciente masculino de 60 anos, pesando 50 Kg, com queimadura de 3.º grau que\natinge a totalidade do membro superior direito e a totalidade do membro inferior esquerdo, tem-se,\nrespectivamente, a superfície corporal estimada e a reposição hídrica, segundo a fórmula de\nParkland, de","options":{"A":"área de 27% de SCQ e 2 700 mL administrados nas primeiras 24 horas do momento da\nqueimadura.","B":"Área de 27% de SCQ e 1 350 mL administrados nas primeiras 8 horas do momento da\nqueimadura e 1 350 mL administrados nas 16 horas seguintes.","C":"Área 18% de SCQ e 900 mL administrados nas primeiras 8 horas do momento da queimadura e\n900 mL administrados nas 16 horas\nseguintes.","D":"Área de 18% de SCQ e 1 800 mL administrados nas primeiras 24 horas do momento da\nqueimadura."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-244464","number":"244464","sourceNumber":"244464","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Vítima de incêndio com 27 anos de idade e 70 kg foi levada ao hospital especializado\nem trauma, com porção anterior da face, abdome e\ntórax anterior e ambos os membros superiores\ncom hiperemia importante e flictenas, além de áreas com pele esbranquiçada e indolor. Quanto a\nesse caso clínico e com base nos conhecimentos correlatos, assinale a alternativa correta.","options":{"A":"O paciente apresenta queimadura em 27% do corpo, sendo considerado um grande queimado,\ndevendo ser encaminhado para unidade de terapia intensiva especializada em queimados.","B":"Em razão da queimadura extensa, deve-se iniciar infusão de soro fisiológico e monitorização da\ndiurese, sendo importante manter o débito urinário de pelo menos 10 mL/h.","C":"Durante o manejo do paciente, deve-se atentar ao risco de restrição ventilatória, nesse caso,\nsendo indicada a escarotomia.","D":"Diferentemente da queimadura por chama, no caso de queimaduras elétricas, elas são de fácil\navaliação de gravidade, pois, a partir da simples visualização da superfície do corpo, ficam claras\na\nextensão e a gravidade da queimadura.","E":"O grande queimado deve ter acesso venoso para correção de eletrólitos e atentar para\ndesidratação. Esse acesso em hipótese nenhuma será colocado sobre a área queimada."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-230586","number":"230586","sourceNumber":"230586","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Assinale a alternativa que é a PRIMEIRA opção de tratamento para adenocarcinoma de\npróstata com metástases, sintomático, com lesões secundárias em coluna lombar, cuja função é\nreduzir ação da testosterona nas células neoplásicas:","options":{"A":"difosfonados.","B":"5-Fluoracil.","C":"goserelina.","D":"carbamazepina."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-230592","number":"230592","sourceNumber":"230592","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A terapia hiperbárica é uma alternativa no tratamento de ferida, e sua utilização é cada\nvez maior e muito utilizada em processos como\nrecuperação de enxertos de pele, resgate de\nretalhos, fasceíte necrotizante e outras feridas crônicas. Sobre a terapia hiperbárica, assinale a\nCORRETA:","options":{"A":"a vascularização da área alvo é dispensável, pois as pressões de oxigênio administradas na\ncâmara são infundidas nos tecidos por difusão.","B":"os efeitos benéficos são imediatos, por isso na maioria dos protocolos são indicadas apenas\numa sessão, em qualquer tipo de lesão.","C":"o objetivo da terapia hiperbárica é reduzir a proliferação de fibroblastos, síntese de colágeno e\nmoderar a epitelização das feridas.","D":"são contraindicações à terapia: pneumotórax prévio não tratado, uso atual ou recente de\nbleomicina e/ou doxirrubicina, e tratamento com dissulfiram."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-183856","number":"183856","sourceNumber":"183856","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação às afecções oncológicas, julgue o item subsecutivo. O prognóstico de\ncâncer de próstata em pacientes obesos é melhor que em pacientes com peso adequado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-183866","number":"183866","sourceNumber":"183866","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Acerca de pacientes diabéticos, julgue o próximo item. O esvaziamento gástrico é\nretardado no caso desses pacientes, sendo necessário um período mais prolongado de jejum\npré-operatório nos procedimentos que envolvem anestesia geral.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-183953","number":"183953","sourceNumber":"183953","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação ao trauma físico nos pacientes que recebem o primeiro atendimento nas\nunidades hospitalares, julguem o item que se segue. Em se tratando de choque elétrico em\ncrianças, a análise da lesão de pele superficial é um bom marcador para a predição de\nenvolvimento dos tecidos internos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-183957","number":"183957","sourceNumber":"183957","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação ao trauma físico nos pacientes que recebem o primeiro atendimento nas\nunidades hospitalares, julguem o item que se segue. As queimaduras classifgicadas como de\nterceiro grau - espessura total - atingem somente a epiderme, a derme e estruturas profundas, e a\nqueixa de dor relatada pelo paciente geralmente relaciona-se com a derme.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-154479","number":"154479","sourceNumber":"154479","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação ao câncer de próstata, assinale a única alternativa INCORRETA:","options":{"A":"O câncer de próstata é, globalmente, o câncer mais comum nos homens.","B":"A sua apresentação, em estágios precoces, costuma ser assintomática.","C":"A velocidade de aumento do PSA pode ser usada como critério para indicação de biópsia.","D":"Idade avançada é o maior fator de risco associado ao câncer de próstata.","E":"O escore de Gleason pode ser usado para o estadiamento da doença."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-154502","number":"154502","sourceNumber":"154502","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente de 36 anos, 70 kg, é trazido à sala de emergência pela equipe de resgate\napós queimadura por combustão de álcool há 3 horas.\nDurante o transporte, recebeu 500 ml de\nsolução de Ringer lactado. Apresenta queimaduras de aspecto nacarado e endurecido\ncircunferencialmente em tronco e braços, totalizando 50% de superfície corporal queimada. Com\nrelação à queimadura circunferencial do braço, a conduta é:","options":{"A":"Fasciotomia.","B":"Escarotomia.","C":"Redução do volume de cristaloide a ser reposto para evitar síndrome compartimental.","D":"Aplicar Papaína 6% para debridamento da lesão.","E":"Amputação do membro."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-154517","number":"154517","sourceNumber":"154517","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente vítima de trauma com esmagamento do membro inferior esquerdo após\ndesabamento de laje, evoluindo com marcante\nedema da perna, dor intensa e sensação de\nparestesias, apresentando diminuição do pulso pedioso e palidez distal no membro afetado. Qual é\no tratamento a ser empregado no caso acima?","options":{"A":"Trombólise química.","B":"Fasciotomia.","C":"Aquecimento do membro.","D":"Embolectomia.","E":"Bloqueio do nervo femoral."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-159525","number":"159525","sourceNumber":"159525","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação aos curativos de queimaduras, julgue o próximo item. Vários agentes\ntópicos antibacterianos, como a sulfadiazina de\nprata, são utilizados para o tratamento de\nqueimaduras graves juntamente com a realização de curativo aberto ou fechado. Há maior\nprobabilidade de infecção quando se utiliza o curativo fechado em vez do aberto, principalmente se\no curativo fechado não for trocado pelo menos duas vezes por dia.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-159529","number":"159529","sourceNumber":"159529","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Considerando um paciente de vinte e oito anos de idade que apresente cólica renal\naguda decorrente de litíase renal, julgue o item\na seguir. Para o referido paciente, o exame de\nimagem de escolha é a tomografia computadorizada helicoidal do abdome - modalidade diagnóstica\nque apresenta maior sensibilidade e especificidade em comparação com outros exames de\nimagem.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-168461","number":"168461","sourceNumber":"168461","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um trabalhador braçal com 68 anos de idade e hipertensão arterial leve tratada de\nforma irregular, tabagista crônico (1 a 2 maços\nde cigarro/dia) e etilista de bebida destilada,\napresentou quadro de disfagia a sólidos que evoluiu para líquidos, seguido de perda de peso maior\nque 20 kg nos últimos 60 dias. Realizada a endoscopia digestiva, foi confirmado o diagnóstico de\nneoplasia de esôfago. O estadiamento da doença mostrou doença localmente avançada (T4N0M0),\ntendo sido indicado tratamento neoadjuvante com radioterapia e reavaliação futura para\nintervenção terapêutica. Nesse caso, a forma de suporte nutricional adequada para esse paciente é\na nutrição","options":{"A":"enteral por meio de sonda nasogástrica ou gastrostomia endoscópica percutânea,\npreservando-se assim a função do trato gastrointestinal.","B":"parenteral total, por permitir maior aporte nutricional aos pacientes gravemente desnutridos\ncomo nas neoplasias avançadas.","C":"parenteral periférica, por permitir bom aporte nutricional, com diminuição dos riscos\nrelacionados\na nutrição parenteral total.","D":"enteral por via oral, pois é o meio mais fisiológico e permite o aporte de nutrientes sem os\nriscos\nrelacionados à nutrição parenteral total e a nutrição enteral."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-168458","number":"168458","sourceNumber":"168458","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um homem com 58 anos de idade, em seguimento ambulatorial, apresenta radiografia\nda bacia mostrando lesões osteolíticas e um\nexame de antígeno prostático específico (PSA) = 35\nng/mL (valor de referência: < 4 ng/mL). Na ocasião, o médico solicitou a realização de biópsia\ntransretal da próstata e cintilografia, cujos resultados revelaram a presença de um adenocarcinoma\ne de múltiplas lesões hipercaptantes em bacia e coluna vertebral. Nesse caso, qual deve ser o\ntratamento proposto ao paciente?","options":{"A":"Castração química ou cirúrgica.","B":"Prostatectomia radical, seguida de quimioterapia adjuvante.","C":"Cirurgia minimamente invasiva, com ressecção transuretral da próstata.","D":"Radioterapia e quimioterapia neoadjuvantes, seguidas de prostatectomia radical."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-129006","number":"129006","sourceNumber":"129006","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"No que se refere à anatomia da região inguinal, assinale a alternativa correta.","options":{"A":"O cordão espermático é composto pelo cremaster, pelos vasos cremastéricos e pelos vasos\nepigástricos inferiores.","B":"As hérnias inguinais diretas originam-se lateralmente ao triângulo de Hesselbach.","C":"A parede posterior do canal inguinal é formada pela fáscia transversal e pela aponeurose do\nmúsculo transverso do abdome.","D":"A secção dos vasos cremastéricos leva, na maioria das vezes, à atrofia testicular.","E":"O ligamento redondo do útero forma a parece medial do canal inguinal."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-111264","number":"111264","sourceNumber":"111264","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Mulher de 54 anos, fumante, diabética, hipertensa, em uso de\nvalsartana/hidroclorotiazida 160/12,5 mg, fazendo\ndieta hipossódica com restrição de açúcar e\nportadora de colelitíase, necessita colecistectomia laparoscópica. BEG, PA: 125/80, FC: 80\nbat./min, rítmico. Glicemia 95 mg e sem alterações de Na e K. Rk tórax: normal. Sua classificação\nde risco anestésico (A.S.A.) é:","options":{"A":"ASA 1.","B":"ASA 2.","C":"ASA 3.","D":"ASA 4.","E":"ASA 5."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-75508","number":"75508","sourceNumber":"75508","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Homem com 25 anos de idade chega ao Setor de Emergência de hospital público de\ngrande porte após ser atingido pela explosão\nde um rojão de fogos de artifício, 40 minutos atrás.\nApresenta-se consciente, porém agitado, taquipneico, com fácies de dor forte, frequência cardíaca\n\n= 130 bpm e pressão arterial = 130 x 90 mmHg. Saturação de O2 (pelo oxímetro de pulso) = 95%.\nAo exame inicial observa-se vasta queimadura\nde terceiro grau na mão, no membro superior\nesquerdo e na região anterior do tronco, queimadura de segundo grau no membro inferior esquerdo\ne na cabeça (couro cabeludo). O médico de plantão resolveu transferir o paciente para um centro\nespecializado no tratamento de queimados. A intervenção mais importante a ser realizada, antes da\ntransferência a fim de minimizar os riscos de agravamento do quadro, é:","options":{"A":"garantir permeabilidade de via aérea com entubação orotraqueal.","B":"administrar antibioticoterapia profilática e vacina\nantitetânica.","C":"envolver as áreas lesionadas com compressas\númidas.","D":"puncionar acesso venoso e iniciar reposição volêmica.","E":"prescrever analgésicos fortes e ansiolíticos."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-137561","number":"137561","sourceNumber":"137561","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente do sexo feminino, 23 anos de idade, em tratamento clínico para\ntranstorno depressivo, deu entrada na Emergência\ndevido à tentativa de suicídio com fogo,\napós banhar-se com álcool. Queixa-se de \"sensação de sufocamento\" e dor nas áreas\nqueimadas. Ao exame, apresenta-se extremamente ansiosa, pouco cooperativa, gemente,\ncom queimaduras de segundo e terceiro graus na face, tronco (anterior e posterior) e\nmembro superior esquerdo, incluindo palma da mão. Taquipneica ? 36 irpm, taquicárdica ? 130\nbpm, P A = 100 x 60 mmHg. Observa-se também queimaduras de cílios e vibrissas nasais. Na\nausculta pulmonar , ouve-se discreta sibilância. Demais aspectos do exame físico não\nacrescentam outros agravantes ao caso. A medida mais urgente a ser adotada com essa\npaciente é","options":{"A":"a hidratação associada à prescrição de antibioticoterapia profilática.","B":"a instalação de acesso venoso central.","C":"o resfriamento da paciente com água corrente e lençóis molhados.","D":"a intubação orotraqueal para garantir permeabilidade das vias aéreas.","E":"a monitorização de pressão arterial pulmonar para orientar reposição volêmica."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-30977","number":"30977","sourceNumber":"30977","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um homem de 60 anos de idade com diagnóstico de colecistite crônica calculosa será\nsubmetido à colecistectomia videolaparoscópica. Ele também apresenta hipertensão arterial\nsistêmica, em uso de medicação, com bom controle da pressão; não tem outras queixas ou\ndoenças associadas além das citadas e não faz uso de outros medicamentos. Considerando o caso\nclínico apresentado, a avaliação pré-operatória desse paciente e o ato anestésico, julgue o item.\n\nNesse paciente, o uso do anestésico inalatório halotano promove o aumento da pressão arterial,\npor provocar aumento da resistência vascular\nsistêmica.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-138715","number":"138715","sourceNumber":"138715","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, com 29 anos de idade, procura o pronto-socorro local em virtude de\nqueimadura com água quente na coxa direita,\nocorrida há 10 minutos enquanto preparava café.\nQueixa-se de dores no local da queimadura. Informa ter dado a luz há dois anos e o cartão de\nacompanhamento da gestante mostra que todo o esquema vacinal foi realizado adequadamente. A\npaciente está consciente, orientada, eupneica, hidratada, normocorada e afebril, Frequência\ncardíaca = 79bpm, Pressão arterial = 120x80mmHg. Ao exame local apresenta flictenas, eritema e\nedema em face anterior de coxa direita. Qual a conduta para o caso descrito?","options":{"A":"Realizar lavagem da ferida com solução fi siológica a 0,9%. Analgesia endovenosa com dipirona.\n\nRecomendar não romper as flictenas e realizar curativo com solução fi siológica a 0,9%, associada\na sulfadiazina de prata. Analgesia domiciliar com\ndipirona, se necessário.","B":"Realizar a limpeza da ferida com clorhexidina. Analgesia endovenosa com meperidina\nendovenosa e antibioticoterapia oral com\ncefalexina - 500mg por via oral, de 6/6h durante 7 dias.\nRecomendar não romper as flictenas e realizar curativo com solução fisiológica a 0,9% e\nneomicina. Analgesia domiciliar com cloridrato de tramadol.","C":"Realizar a limpeza da ferida com PVPI\n\n(polivinilpirrolidona-iodo, lauril éster sulfato de sódio) tópico seguida de termoterapia com gelo.\n\nAnalgesia endovenosa com cloridrato de\ntramadol e antibioticoterapia parenteral com\n\npenincilina benzatina por via IM. Recomendar rotura e debridamento das flictenas e curativo com\nclorhexidina e sulfadiazina de prata tópico.","D":"Realizar lavagem da ferida com soro fi siológico a\n\n0,9%. Analgesia oral com paracetamol. Realiza curativo com clorhexidina e lidocaína tópica, romper\nas fl ictenas e realizar debridamento de\ntecidos desvitalizados. Antibioticoterapia parenteral com\npenincilina cristalina por via IM. Curativo oclusivo com clorhexidina.","E":"Realizar limpeza da ferida com soro fisiológico a\n0,9%. Analgesia oral com dipirona. Recomendar\n\nnão romper as flictenas. Realizar curativo com\n\nPVPI (polivinilpirrolidona-iodo, lauril éster sulfato de sódio) e lidocaína tópica. Prescrever\nanalgesia\noral\n\ncom tramadol e antibioticoterapia com amoxicilina + ácido clavulânico - 500mg por via oral, de 8/8h\ndurante 7 dias."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-359201","number":"359201","sourceNumber":"359201","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente em terapia nutricional enteral, iniciada precocemente, evoluiu com quadro\ndiarreico. Nesse caso, a conduta CORRETA a seguir é:","options":{"A":"Aumentar a velocidade de infusão.","B":"Investigar a etiologia do quadro inicialmente.","C":"Interromper imediatamente a nutrição desse paciente.","D":"Continuar o tratamento da mesma forma, já que é um quadro comum."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-359203","number":"359203","sourceNumber":"359203","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente com 23 anos chega ao Serviço de Urgência com queimadura química no\nmembro superior direito, tendo como agente etiológico um ácido. A PRIMEIRA conduta, nesse\ncaso, é:","options":{"A":"Neutralizar a reação, utilizando o antagonista específico.","B":"Aplicar sulfadiazina de prata a 1%.","C":"Lavar o local abundantemente com água corrente.","D":"Limpar com soro fisiológico e fazer aplicação tópica de corticoide."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-352205","number":"352205","sourceNumber":"352205","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Os mecanismos endócrinos, metabólicos e imunológicos usados pelo organismo são\nimportantes para a resposta à lesão tecidual, porém essa mesma resposta, se desregulada, pode\nlevar à morbidade e complicações potencialmente fatais. O conhecimento sobre o equilíbrio entre\nfatores anabólicos e catabólicos e seus processos reguladores são de fundamental importância\npara obter bons resultados clínicos em pacientes cirúrgicos. Acerca do tema, é CORRETO afirmar\nque:","options":{"A":"A resposta inflamatória à injúria traumática é caracterizada inicialmente por aumento da\npermeabilidade vascular, edema e resposta celular em que predomina a ação de neutrófilos.","B":"A resposta hipotalâmica ao trauma implica em supressão do eixo\nrenina-angiotensina-aldosterona.","C":"Com o intuito de aumentar o efeito anabólico para reparo tecidual nas fases iniciais, ocorre\naumento da ação da insulina e, por conseguinte, hipoglicemia.","D":"A ação anti-inflamatória de citocinas como IL-1 e TNF-alfa é observada mais tardiamente na\nresposta imune ao trauma."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-352197","number":"352197","sourceNumber":"352197","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Além de servir como um meio para a entrega sistêmica de nutrientes, a nutrição enteral\ndesempenha uma função crítica no suporte do próprio trato alimentar. A exposição da mucosa aos\nalimentos fornece nutrientes diretos de alta concentração, estimula o fluxo sanguíneo entérico,\nmantem a função de barreira e induz a produção e liberação de imunoglobulinas da mucosa e\nfatores críticos de crescimento endógeno. Sobre a nutrição enteral assinale a alternativa correta:","options":{"A":"A nutrição enteral tem um papel trófico e pacientes em uso de drogas vasoativas devem\nrecebê-la com a finalidade de evitar isquemia intestinal.","B":"Em pacientes vítimas de extensas queimaduras, a nutrição enteral deve ser retardada por até 48\nhoras.","C":"Dietas oligoméricas devem ser consideradas preferencialmente para pacientes com\ncomprometimento da função absortiva.","D":"A síndrome de realimentação é uma das complicações possíveis e se caracteriza por\nhipermagnesemia e hipercalemia."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-352199","number":"352199","sourceNumber":"352199","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente de 30 anos apresenta-se ao Pronto Socorro com forte dor lombar a direita\nassociada a febre de 38,5°C, e queda do\nestado geral e hipotensão arterial. Realizou tomografia de\nabdome com achado de dilatação ureteropielocalicial a direita com cálculo 09 mm em ureter\nproximal direita. Entre as alternativas, qual a conduta é contra-indicada?","options":{"A":"Iniciar precocemente antibiótico e reposição volêmica.","B":"Realizar precocemente ureterorrenolitotripsia endoscópica.","C":"Proceder desobstrução ureteral com colocação de cateter duplo J.","D":"Coletar cultura de urina após manipulação do trato urinário com colocação de duplo J."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-373627","number":"373627","sourceNumber":"373627","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em um paciente com HPB, que faz uso de terapia medicamentosa combinada, que deu\nentrada em retenção urinária aguda, a melhor conduta é:","options":{"A":"Sondagem vesical de demora e excluir processo infeccioso vigente.","B":"Sondagem vesical de alívio e RTU de próstata na mesma internação.","C":"Cistostomia por punção.","D":"Sondagem vesical de alívio e excluir processo infeccioso vigente."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-354097","number":"354097","sourceNumber":"354097","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente de 14 anos, submetido à uma laparotomia exploradora devido à apendicite\naguda fase 4, evolui no primeiro\npós-operatório com intensa resposta inflamatória sistêmica. Nesse\ncaso, quais citocinas pró-inflamatórias estarão elevadas durante esta resposta?","options":{"A":"TNF-alfa, Interleucina-1 e Interleucina-6.","B":"TNF-Beta, Interleucina-4 e Interleucina-10.","C":"Interferon-gama,TNF-Beta e interleucina-4.","D":"Fator transformador de crescimento Beta, Interleucina-5 e Interleucina-10.","E":"PDGF, FGF, TNF-alfa."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-368172","number":"368172","sourceNumber":"368172","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Adolescente feminina com 14 anos de idade vem apresentando dor abdominal crônica\nrecorrente há cerca de seis meses. Há 24 horas, deu entrada no pronto-socorro com dor intensa\nem flanco direito, irradiando para o grande lábio direito. A mãe informa que a paciente já teve um\nepisódio semelhante há cerca de dois anos. Relata, ainda, que ocasionalmente a urina fica\n\n?escura?, tipo cor de Coca-Cola. A ultrassonografia realizada na emergência mostrou um cálculo\nno terço médio do ureter direito de 5,0 mm.\nCom base no caso relatado, assinale a alternativa\ncorreta.","options":{"A":"A paciente deve aguardar a descida do cálculo com acompanhamento laboratorial e de imagem\nperiódico e sequencial.","B":"A paciente deve realizar o estudo metabólico da urina para iniciar a terapêutica apropriada, quer\nseja cirúrgica ou conservadora.","C":"A paciente deve ser internada e fazer uma urografia excretora para localização do cálculo e\navaliar seus efeitos colaterais.","D":"A paciente deve ser internada para receber opioides por via intravenosa para a dor até\ncompletar o estudo metabólico."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-354113","number":"354113","sourceNumber":"354113","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Quais as alterações esperadas para um paciente vítima de acidente automobilístico,\ncom trauma torácico e contusão pulmonar,\nassociado a trauma hepático grau III e esplênico grau\nIV, considerando a resposta endócrino metabólica secundária ao trauma, especificamente na fase\n\"flow precoce\"?","options":{"A":"Poliúria, com alta densidade urinária excreção aumentada de potássio e retenção de sódio.","B":"Poliúria, com baixa densidade urinária, excreção aumentada de cloro e retenção de magnésio.","C":"Poliúria, com alta densidade urinária, excreção aumentada de sódio, retenção de potássio.","D":"Oligúria, com alta densidade urinária, excreção aumentada de potássio e hidrogênio e retenção\nde sódio.","E":"Oligúria, com baixa densidade urinária, retenção de potássio e de sódio."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-354126","number":"354126","sourceNumber":"354126","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Homem, 40 anos, procura serviço de urgência, referindo dor lombar a direita, há 3 dias,\ncom irradiação pra fossa ilíaca e testículo ipsilateral, de forte intensidade, tipo cólica,\nassociado a\nhematúria leve, relata disúria e febre. No momento paciente referindo mal estar geral, dor\nimportante em fossa ilíaca e náuseas. Está com frequência cardíaca de 110 bpm e frequência\nrespiratória de 22 irpm. Tomografia de abdome identificou que paciente tem rim único a direita, com\ncálculo de 8 mm em ureter distal direito, com importante uretero-hidronefrose a montante.\n\nLeucócitos: 18 mil, creatinina: 7,8 ng/dI; uréia: 193 ng/dI. Qual a conduta correta neste caso?","options":{"A":"Realizar analgesia com antiespasmódico, pois segundo a fisiopatologia da cólica renal é o\nmelhor analgésico para tratamento.","B":"Antibioticoterapia, analgesia e realizar imediata desobstrução ureteral com cateter duplo j, sem\na\nretirada do cálculo ureteral neste procedimento de urgência.","C":"Associar analgesia endovenosa com opióide a hiper-hidratação e diurético, pois ajudarão no\ncontrole da dor e tratamento da disfunção renal.","D":"Com antibioticoterapia e controle da dor, e o paciente preenche critérios para realizar a terapia\nexpulsiva medicamentosa com Tansulosina.","E":"Antibioticoterapia, analgesia e realizar ureterolitotripsia endoscópica com a colocação de\ncateter\nduplo j."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-336254","number":"336254","sourceNumber":"336254","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Homem, 44 anos, chega a sala de emergência após extricação prolongada de uma\nexplosão com chamas em um edifício. Ao exame: agitado, respiração em gasping, gemente com\npalavras incompreensíveis, presença queimaduras severas com bolhas em sua face e corpo,\nmúltiplas fraturas de costela palpáveis e movimento paradoxal do tórax. Qual é a melhor conduta\ninicial no manejo desse paciente?","options":{"A":"Intubar o paciente com sequência rápida de intubação.","B":"Chamar um cirurgião para fazer a admissão do paciente.","C":"Realizar ultrassonografia a beira leito, utilizando o protocolo FAST.","D":"Realizar drenagem torácica no 4o espaço intercostal na linha axilar média."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-336261","number":"336261","sourceNumber":"336261","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, 80 anos, 84 Kg, portador de insufioiência cardíaca congestiva compensada, é\ntrazido ao PS devido queimadura acidental acomentendo toda extensão de ambas as pernas. Ao\nexame: lúcido e orientado, lesões de segundo e terceiro grau tanto em parte anterior e posterior\nbilateralmente de membros inferiores. O volume previsto de infusão de solução de Ringer Lactato\nnas primeiras 8 horas pela fórmula de Parkland, utilizando a regra dos nove de Wallace, para o\ncálculo do percentual de superfície queimada, é de:","options":{"A":"6048 ml","B":"9072 ml","C":"3024 ml","D":"1512 ml"},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-336263","number":"336263","sourceNumber":"336263","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Vários estágios e deflagradores são descritos para a Resposta Metabólica ao Trauma,\nseja por infecções, traumas, cirurgias de\nurgência e eletivas. A primeira fase dessa resposta\ncaracteriza-se por:","options":{"A":"Hipercatabolismo, hiperglicemia, hiperlactatemia e gliconeogênese","B":"Hipocatabolismo, hipoglicemia, hipolactatemia e gliconeogênese","C":"Hipercatabolismo, hipoglicemia, hiperlactatemia e glicogenólise","D":"Hipocatabolismo, hiperglicemia, hipolactatemia e glicogenólise"},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-335080","number":"335080","sourceNumber":"335080","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente de 35 anos de idade, com queimaduras de 40% da ASCT (área de\nsuperfície corporal total), está sendo tratado\nnuma Unidade de Terapia Intensiva. O paciente é\nsubmetido a uma esofagogastroduodenoscopia, após um sangramento gastrointestinal superior, e,\ndurante esse procedimento, é vista uma úlcera no estômago. O nome desse tipo de úlcera é","options":{"A":"úlcera marginal.","B":"úlcera de Cushing.","C":"úlcera de Curling.","D":"lesão de Dieulafoy."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-334732","number":"334732","sourceNumber":"334732","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Após um incêndio, um paciente de aproximadamente 70 kg sofreu queimadura de\nprimeiro grau em toda região da cabeça, de segundo grau na parte anterior do tronco (abdome e\ntórax) e de terceiro grau em todo membro inferior esquerdo. Calcule a Superfície Corpórea\nQueimada (SCQ) e a quantidade de volume de hidratação a ser reposto no período de 16 a 24\nhoras pós-queimadura:","options":{"A":"SCQ 36%, volume de 2.520 ml.","B":"SCQ 45%, volume de 6.300 ml.","C":"SCQ 36%, volume 5.040 ml.","D":"SCQ 45%, volume de 3.150 ml."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-345724","number":"345724","sourceNumber":"345724","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O estado nutricional interfere diretamente na evolução perioperatória dos pacientes\ncirúrgicos. Sobre triagem e avaliação do paciente cirúrgico, assinale a correta.","options":{"A":"O IMC (Índice de Massa Corporal) é um dos métodos mais confiáveis, pois não subestima o\nestado nutricional e avalia como nutrido um paciente desnutrido.","B":"A Avaliação Subjetiva Global (ASG) é um método simples e rápido para a identificação de\npacientes desnutridos ou em risco de se tornarem desnutridos.","C":"A comparação entre o peso atual e o habitual não é utilizada na Avaliação Subjetiva Global\n(ASG).","D":"Atualmente o percentual de perda de peso não é mais parâmetro para se avaliar riscos de\ncomplicações associadas a desnutrição."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-345726","number":"345726","sourceNumber":"345726","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"É a única célula verdadeiramente fundamental para a cicatrização de feridas, pois serve\npara orquestrar a liberação de citocinas e\nestimular muitos dos processos subsequentes de\ncicatrização. Surgem na ferida ao mesmo tempo que os neutrófilos desaparecem:","options":{"A":"Macrófagos.","B":"Mastócitos.","C":"Neutrófilos.","D":"Eosinófilos."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-345730","number":"345730","sourceNumber":"345730","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Não é um sintoma típico da hiperplasia prostática benigna não complicada:","options":{"A":"Urgência miccional.","B":"Disúria.","C":"Jato urinário fraco.","D":"Nocturia."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-320459","number":"320459","sourceNumber":"320459","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Homem, 65 anos, foi submetido a duodenopancreatectomia, sem complicações.\nEncontra-se no 2° dia de pós-operatório, em\nboa evolução. Apresenta-se estável clinicamente.\nPA=130×70 mmHg; FC=110 bpm; T= 37,2°C. Nesta fase da resposta metabólica ao trauma, é\ncorreto encontrar:","options":{"A":"Diminuição do cortisol plasmático.","B":"Diminuição do débito cardíaco.","C":"Aumento da insulina.","D":"Aumento de aldosterona e ADH.","E":"Balanço nitrogenado positivo."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-320462","number":"320462","sourceNumber":"320462","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Homem, 18 anos, 70kg, é levado ao Pronto Socorro por sofrer queimaduras por fogo.\nAo exame físico apresentando lesões térmicas\ntotalizado 18% de queimaduras de primeiro grau e\n36% de queimaduras de segundo grau de superfície corporal queimada. Considerando ATLS 10ª\ned. o volume correto para reposição é:","options":{"A":"1750 ml em 12 horas.","B":"3520 ml em 8 horas.","C":"5040 ml em 24 horas.","D":"7560 ml em 24 horas.","E":"10080 ml em 24 horas."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-314022","number":"314022","sourceNumber":"314022","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação a métodos diagnósticos e a tratamento de pacientes queimados, assinalar\na alternativa CORRETA:","options":{"A":"Injeções intramusculares ou subcutâneas de narcóticos contra a dor devem ser utilizadas para\nalívio.","B":"Atrasos para iniciar a reanimação volêmica de pacientes com queimadura não modificam\nresultados.","C":"Dissecações de veia safena são úteis em casos de difícil acesso, em detrimento das punções de\nacessos centrais, apesar de maiores taxas de\ncomplicação.","D":"O método diagnóstico padrão nos pacientes com suspeita de lesão por inalação deve ser\nbroncoscopia das vias aéreas superiores, de todo paciente queimado.","E":"Métodos para tratamento das feridas de queimadura, como a excisão tangencial precoce, cada\nvez mais agressiva dos tecidos queimados e\nfechamento precoce da ferida, principalmente com\nenxertos de pele, tem indicação na maioria dos casos, porém sem evidência de melhora\nsignificativa das taxas de mortalidade."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-304856","number":"304856","sourceNumber":"304856","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente, 58 anos, assintomático, em uma consulta de rotina, apresenta resultado de\nAntígeno Prostático Específico (PSA) de 4,5 ng/ml. Ao exame de toque retal foi constatado um\nnódulo endurecido no lobo esquerdo da próstata. Qual a conduta mais adequada para o\nesclarecimento do diagnóstico?","options":{"A":"Biópsia da próstata.","B":"Ultrassonografia transretal da próstata.","C":"Repetir o PSA e solicitar o PSA livre.","D":"Solicitar ressonância magnética da próstata."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-306711","number":"306711","sourceNumber":"306711","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"P.L.D, 35 anos, sofreu um trauma no braço direito há cerca de 8 dias. Foi atendido no\npronto socorro e realizada sutura da lesão 2 horas após o trauma. Retorna para reavaliação\nambulatorial da ferida. Sobre o caso apresentado assinale a alternativa correta:","options":{"A":"Na fase de evolução em que se encontra a ferida do paciente, há um predomínio de fibras\ncolágenas do tipo I.","B":"Quanto mais tempo houver de evolução da ferida maior será a resistência da cicatriz, pelo\nacúmulo de fibras de colágeno tipo III.","C":"Neste momento evolutivo da ferida do paciente, estão presentes em grande quantidade os\nfibroblastos, com elevada produção de fibronectina.","D":"Logo após o trauma sofrido pelo paciente, as células que predominavam em sua lesão eram os\nmacrófagos, que são as primeiras células a se apresentarem no processo inflamatório."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-304858","number":"304858","sourceNumber":"304858","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Assinale a afirmativa correta sobre a estratégia de alimentação em cirurgias colorretais\neletivas.","options":{"A":"A dieta pós-operatória de início precoce deve ser baseada em maiores quantidades de\ncarboidratos e pouco ou ausente conteúdo proteico.","B":"A alimentação oral de início precoce em cirurgias eletivas colorretais apresenta redução da\nmortalidade e das complicações graves.","C":"A permeabilidade intestinal, a translocação bacteriana e as reações inflamatórias no pós\noperatório de cirurgias colorretais não se\nmodificam com as diferentes estratégias de alimentação\npós cirúrgica.","D":"O estresse metabólico cirúrgico não traz consequências na síntese proteica ou imunidade,\nestando essa resposta fisiológica ligada à síntese lipídica e de carboidratos."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-314036","number":"314036","sourceNumber":"314036","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Os cálculos renais são compostos por cristais em uma matriz de proteínas. Em relação\naos cálculos renais, assinalar a alternativa\nCORRETA:","options":{"A":"Aproximadamente 90% dos cálculos renais são radiotransparentes e podem ser detectados em\numa radiografia abdominal simples.","B":"Os cálculos de estruvita formam-se apenas na presença de íons de cálcio e de um pH urinário\nmenor que 7.","C":"A ultrassonografia pode detectar cálculos renais clinicamente significativos e apresenta uma alta\nsensibilidade para a detecção de cálculos ureterais.","D":"Os cálculos renais que contêm cálcio são mais frequentemente causados por excreção de\nexcessiva de cálcio, de oxalato ou de uratos ou por uma insuficiência excreção de citrato.","E":"Os pacientes com hipercalciúria persistente se beneficiam com frequência de uso de diuréticos\nde alça, que reduzem diretamente o cálcio\nurinário e diminuem a formação de cálculos recorrentes\ne em cerca de 50%"},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-291953","number":"291953","sourceNumber":"291953","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente João de Sousa, 78 anos apresenta-se no Pronto Socorro com quadro de dor\npara evacuar, sensação de peso no períneo,\nfebre, mal-estar e calafrios e associou retenção\nurinária aguda tratada com sonda vesical de alívio. Baseado no diagnóstico clínico desse paciente,\né CORRETO afirmar que:","options":{"A":"Se o paciente está em bom estado geral, adotar antibioticoterapia oral por 4 a 6 semanas.","B":"Essa doença é causada em cerca de 80% das vezes pela Klebsiella.","C":"O tratamento é antibioticoterapia de largo espectro e fistulectomia anal.","D":"Toque retal repetido e massagem prostática podem aliviar e melhorar o paciente."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-291645","number":"291645","sourceNumber":"291645","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O conhecimento dos complexos eventos fisiológicos da cicatrização de feridas é de\ngrande importância para o cirurgião. Considere a\nferida fechada por primeira intenção e que evolui\nsem complicações. Qual tipo celular deve predominar nessa ferida após 48h de seu início?","options":{"A":"Fibroblastos.","B":"Plaquetas.","C":"Neutrófilos.","D":"Linfócitos.","E":"Macrófagos."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-314080","number":"314080","sourceNumber":"314080","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação à nefrolitíase, analisar os itens abaixo: I. Com menor frequência, os cálculos\npodem ser compostos pelo uso de medicamentos, como o aciclovir. II. A maior ingestão de proteína\nde origem animal pode aumentar a concentração urinária de cálcio e a excreção de ácido úrico e\naumentar os níveis de citrato na urina, elevando o risco de formação de cálculos. III. As doenças\nsistêmicas que aumentam o risco de formação dos cálculos constituídos por cálcio incluem o\nhiperparatireoidismo primário e a acidose renal tubular. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e II.","D":"Somente os itens I e III.","E":"Todos os itens."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-283895","number":"283895","sourceNumber":"283895","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Reposição volêmica é de extrema importância no pós-operatório, sendo a concentração\nde sódio, potássio, cálcio e o pH da solução\nimportantes fatores a serem levados em conta. Nesse\nsentido, os componentes cloreto de sódio 130mEq/L, cloreto de potássio 4mEq/L, cloreto de cálcio\n3mEq/L, pH 6.5 correspondem à qual solução cristaloide?","options":{"A":"Soro fisiológico 0,9%.","B":"Plasma lyte A.","C":"Ringer Lactato.","D":"Plasma.","E":"Salina hipertônica."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-283896","number":"283896","sourceNumber":"283896","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A grande vantagem da alimentação enteral sobre a parenteral total, na nutrição artificial\nprolongada, é que, na primeira:","options":{"A":"A absorção da glicose é mais rápida e não causa hipoglicemia.","B":"Previne-se a atrofia das vilosidades com formulações simples.","C":"Os cateteres nasojejunais são mais confortáveis que os venosos.","D":"A possibilidade de cólicas é bem menor com soluções mais concentradas.","E":"Nenhuma das anteriores."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-287857","number":"287857","sourceNumber":"287857","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação às doenças testiculares e escrotais, assinalar a alternativa CORRETA:","options":{"A":"Varicocele não está relacionada à infertilidade, portanto não há necessidade de tratamento.","B":"Hidrocele consiste em um acúmulo de líquido intratesticular, e o tratamento consiste em\ndrenagem cirúrgica.","C":"Epididimites são afecções do epidídimo, podendo ser causadas por bactérias coliformes\noriundas da prática de intercurso sexual anal sem preservativos.","D":"Neoplasias testiculares são dolorosas na maioria dos casos.","E":"Na torção testicular, o reflexo cremastérico está quase sempre presente."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-266407","number":"266407","sourceNumber":"266407","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente feminina, 35 anos, cozinheira, apresentou queimadura de terceiro grau em\nmão direita com óleo quente. Evoluiu com\nsindactilia, ocasionando seqüela grave e incapacitante,\ncom limitação da função preensora da mão direita. Para correção da sindactilia, qual a melhor\ntécnica cirúrgica a ser utilizada?","options":{"A":"Transplante de pele de doador.","B":"Aplicação local de toxina botulínica.","C":"Confecção de retalho de pele.","D":"Aplicação local de corticóides."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-283933","number":"283933","sourceNumber":"283933","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Homem, 74 anos, procura atendimento na ESF devido à dificuldade progressiva para\nurinar. Relata que, após micção, persiste com\nsensação de esvaziamento incompleto da bexiga.\nApós manobras, refere saída do restante da urina. Qual condição mais provável para que se realize\numa investigação com base no relato do paciente?","options":{"A":"Pielonefrite.","B":"Obstrução por cálculo urinário.","C":"Litíase renal.","D":"Hidrocele.","E":"Hiperplasia prostática benigna."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-234409","number":"234409","sourceNumber":"234409","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um homem de 72 anos vai ao pronto atendimento queixando-se de dor suprapúbica\nintensa iniciada há 30 minutos, além da\nimpossibilidade de realizar a micção, a despeito do intenso\ndesejo de urinar. É portador de depressão maior e hiperplasia prostática benigna e faz uso diário de\nsertralina, haloperidol e doxazosina há 7 dias. Ao exame físico, apresenta-se agitado, sudorético,\nalerta e orientado. A palpação do abdômen revela estrutura arredondada suprapúbica palpada até\no nível da cicatriz umbilical, com submacicez à percussão. Sem outras anormalidades ao exame\nfísico. Considerando o quadro clínico apresentado, assinale a conduta imediata MAIS ADEQUADA\npara esse paciente:","options":{"A":"Indicar a realização de cistostomia de urgência.","B":"Indicar a realização de ressecção transuretral da próstata.","C":"Suspender a sertralina e realizar o cateterismo vesical de demora.","D":"Suspender o haloperidol e realizar o cateterismo vesical de alívio."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-246368","number":"246368","sourceNumber":"246368","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre a formação de cálculos urinários, assinale a alternativa incorreta:","options":{"A":"Hiperparatireoidismo primário, mieloma múltiplo e doença de Cushing são causas de\nhipercalciúria reabsortiva.","B":"Na Hipercalciuria Absortiva Tipo III, ocorre perda de fosfato pelo rim, elevação de produção de\nvitamina D e aumento na absorção intestinal de cálcio.","C":"Diuréticos Tiazídicos são indicados no tratamento da Hipercalciúria Renal.","D":"A infecção intestinal pela bactéria Oxalobacter formigenes leva à maior absorção de oxalato."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-246371","number":"246371","sourceNumber":"246371","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A queimadura elétrica pode causar conseqüencias sistêmicas gravíssimas,\nprincipalmente envolvendo coração e rins, mesmo que não\nproduza grandes lesões cutâneas.\nDentre os tecidos abaixo: I - Nervo; II - Músculo; III - Vasos; IV - Pele; a ordem crescente de\nresistência à corrente elétrica será:","options":{"A":"I, II, III e IV","B":"I, III, II e IV","C":"IV, II, III e I","D":"IV, II, I e III"},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-227109","number":"227109","sourceNumber":"227109","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"No paciente grande queimado está indicado a Intubação Orotraqueal (IOT) em várias\nsituações. Nesse contexto, analise as afirmativas a seguir: I- Presença de estridor, uso de\nmusculatura acessória e retração esternal. II- Extensão de queimadura maior que 40-50%. III-\nDificuldade de engolir. IV- Sinais de queimadura na boca e língua. Estão CORRETAS a indicação\ndas afirmativas:","options":{"A":"I, II e III apenas.","B":"I, III e IV apenas.","C":"III e IV apenas.","D":"I, II, III e IV."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-234441","number":"234441","sourceNumber":"234441","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente Raimunda, 40 anos internada com dor abdominal difusa e vômitos. Exame\nclínico paciente taquicárdica, FC: 100bpm, eupneica e desidratada. PA: de 110 X 70mmHg. Os\nexames de laboratórios solicitados estavam normais leucograma mostra leucocitose de 17.000\nleucócitos com desvio a esquerda e amilase de 3500 mgr/dl. Ultrassom mostra colelitíase. Sobre\nesse caso, é CORRETO afirmar que:","options":{"A":"Está indicada a tomografia de abdômen na admissão para ver sinais de necrose e os critérios de\nBalthazar.","B":"Trata-se de pancreatite aguda grave considerando o quadro clínico e o que os resultados de\nexames mostram.","C":"Está indicado reposição volêmica e colangiopancreatografia retrógrada endoscópica para\ntratamento da possível coledocolitíase.","D":"Está indicada nutrição mais precoce possível dando preferência a via enteral."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-227301","number":"227301","sourceNumber":"227301","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente vítima de acidente automobilístico ficou preso nas ferragens por quase 03\nhoras, apresentando esmagamento importante dos\nmembros inferiores. Trazido ao hospital,\ndurante o exame na sala vermelha, foi identificado rigidez muscular importante, associado à\noliguria, e os exames laboratoriais apresentaram acidose importante e elevação de CPK\n(creatinofosfoquinase total). Objetivando minimizar o dano renal, qual conduta deve ser adotada?","options":{"A":"Administração de soluções acidificantes da urina.","B":"Administração de soluções alcalinizantes da urina.","C":"Uso de bloqueadores de canal de cálcio.","D":"Amputação imediata dos membros afetados."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-243043","number":"243043","sourceNumber":"243043","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Atleta Judoca, 21 anos de idade, sexo masculino, 80 kg, sofreu queimadura de 2º grau\ncomprometendo 40 % da superfície corporal. É atendido no Centro de Tratamento de Queimados\ndo hospital regional, dentro da primeira hora que ocorreu o acidente, em estado grave. Pergunta:\nQual a necessidade de hidratação deste paciente nas primeiras 24 horas?","options":{"A":"6400 ml de ringer lactado nas 8 primeiras horas e 6400 ml de ringer lactado nas 16 horas\nsubsequentes.","B":"3200 ml de Soro Glicosado 5 % nas 8 primeiras horas e 3200 ml de ringer lactato nas 16 horas\nsubsequentes.","C":"3200 ml de soro glicosado a 5 % nas 8 primeiras horas e 3200 ml de soro glicosado a 5 % nas\n16 horas subsequentes.","D":"6400 ml de ringer lactado nas 12 primeiras horas e 6400 ml de ringer lactado nas 12 horas\nsubsequentes.","E":"1600 ml de ringer lactado nas 8 primeiras horas e 1600 ml de ringer lactato nas 16 horas\nsubsequentes."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-243044","number":"243044","sourceNumber":"243044","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Homem de 28 anos, vítima de acidente automobilístico, submetido à laparotomia\nexploradora onde se realizou duodenorrafia,\nhepatorrafia, colecistectomia e enterecetomia\nsegmentar de cerca de 1 metro de delgado, transição jejuno ileal com anastomose primária\nenteroentérica e colocação intraoperatória de SNE (Sonda naso entérica) em jejuno. Encontra-se\nno 2º dia de pós-operatório, hemodinamicamente estável, eupneico, com abdômen flácido, porém\nsem ruídos hidroaéreos à ausculta e débito de 200 ml pela Sonda naso gástrica em 24hs. Qual a\nconduta nutrológica mais adequada dentre as questões abaixo?","options":{"A":"dieta zero.","B":"nutrição parenteral total exclusiva.","C":"nutrição parenteral periférica exclusiva.","D":"dieta enteral oligomérica via SNE.","E":"dieta enteral polimérica via SNE."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-246792","number":"246792","sourceNumber":"246792","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação à queimadura na criança, é errado afirmar que:","options":{"A":"Queimaduras por escaldadura ocorrem com mais frequência em crianças abaixo de 4 anos de\nidade.","B":"Queimaduras de primeiro grau envolvem apenas a epiderme e são caracterizadas por inchaço,\neritema e dor.","C":"Queimaduras de terceiro grau envolvem destruição total da epiderme e derme, e curam-se em 7\na 14 dias, desde que não haja infecção.","D":"Criança com queimadura que afeta mais de 15% da área de superfície corporal total tem que ser\nhospitalizada.","E":"Crianças que estiveram em incêndio em ambiente fechado devem ficar internadas em\nobservação ao menos por 24 horas, por causa dos\nefeitos da anóxia no sistema nervoso central."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-196736","number":"196736","sourceNumber":"196736","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente de 70 anos chega ao ambulatório com indicação para tratamento cirúrgico\nde adenocarcinoma de corpo gástrico. Refere anorexia\nhá seis meses; há um mês ingere apenas\nalimentos pastosos. Sente-se muito fraco, permanecendo no leito quase todo o dia. Seu peso\nhabitual há seis meses era 74 Kg e o atual é 60 Kg. Tem redução importante de massa muscular\nesquelética e gordurosa subcutânea; não tem edemas. Entre seus exames destacam-se ?\nalbumina: 2,8 g/dL e PCR: 42 mg/L. Em relação à avaliação e cuidados nutricionais no\n\npré-operatório deste paciente está correto.","options":{"A":"A avaliação nutricional subjetiva global (ASG) não tem validade para idosos.","B":"Albumina sérica não é fator de risco para complicações pós-operatórias.","C":"Nutrição enteral pré-operatória reduz complicações, principalmente as infecciosas.","D":"Dietas enterais imunomoduladoras são contraindicadas em idosos."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-199515","number":"199515","sourceNumber":"199515","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Quatro pacientes estavam trabalhando em uma usina siderúrgica quando um alto forno\nestourou. Os pacientes foram transferidos para um pronto socorro e os seguintes achados foram\nencontrados: Paciente 1 - Queimaduras faciais e cervical. Paciente 2 - Não há lesão evidente e\napresenta-se com saturação de 92%, além de chamuscamento dos cílios e das vibrissas nasais.\n\nPaciente 3 - Confusão mental, pois ficou confinado no local da cena. Paciente 4 - Depósitos de\ncarbono na boca e eritema na faringe. Considerando a situação dos pacientes, assinale a\nalternativa CORRETA:","options":{"A":"Somente os pacientes 1 e 2 necessitam de intubação traqueal.","B":"Somente os pacientes 1, 2 e 4 necessitam de intubação traqueal.","C":"Somente os pacientes 2, 3 e 4 necessitam de intubação traqueal.","D":"Todos os pacientes apresentam lesão inalatória aguda e a necessidade de intubação traqueal."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-215123","number":"215123","sourceNumber":"215123","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A Sociedade Americana de Câncer (ACS) e o Colégio Americano de Medicina Esportiva\n(ACSM) desenvolveram diretrizes de nutrição e atividade física para sobreviventes de câncer com\nbase nas evidências disponíveis relacionando dieta, peso e atividade física a resultados de câncer.\nOs pontos-chave das recomendações do ACS/ ACSM incluem, exceto:","options":{"A":"Manter um peso saudável e tentar perder se estiver acima do peso ou obeso.","B":"Adotar um estilo de vida fisicamente ativo, com pelo menos 30 minutos de atividade física\nmoderada a vigorosa em cinco ou mais dias da semana.","C":"Consumir uma dieta saudável, com pelo menos cinco porções de frutas/vegetais por dia.","D":"Limitar a ingesta de álcool a não mais do que uma bebida/ dia para mulheres e duas bebidas/dia\npara homens.","E":"Consumir uma dieta saudável rica em fibras com pelo menos 5 g/dia."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-202734","number":"202734","sourceNumber":"202734","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente de 54 anos é admitido em pronto-socorro com história de queimaduras por\ncombustão de álcool durante a realização\nde um churrasco em confraternização familiar. Submetido\nà avaliação inicial, onde evidenciou-se 55% de superfície corporal queimada e um peso de 76 kg e\naltura de 1,72 m. Assim, segundo a fórmula de Parkland, qual o valor adequado de reposição\nvolêmica de cristalóides para este paciente após o evento?","options":{"A":"8.360 ml nas primeiras 24h.","B":"8.360 ml nas primeiras 8h.","C":"16.720 ml nas primeiras 8h.","D":"8.360 ml nas primeiras 12h.","E":"16.720 ml nas primeiras 12h."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-215140","number":"215140","sourceNumber":"215140","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Atleta Judoca, 21 anos de idade, sexo masculino, 80 kg, sofreu queimadura de 2° grau\ncomprometendo 40 % da superfície corporal. É atendido no Centro de Tratamento de Queimados\ndo hospital regional dentro da primeira hora que ocorreu o acidente, em estado grave. Pergunta:\nqual a necessidade de hidratação deste paciente nas primeiras 24 horas?","options":{"A":"6400 ml de ringer lactado nas 8 primeiras horas e 6400 ml de ringer lactado nas 16 horas\nsubsequentes.","B":"3200 ml de Soro Glicosado 5% nas 8 primeiras horas e 3200 ml de ringer lactato nas 16 horas\nsubsequentes.","C":"3200 ml de soro glicosado a 5% nas 8 primeiras horas e 3200 ml de soro glicosado a 5% nas 16\nhoras subsequentes.","D":"6400 ml de ringer lactado nas 12 primeiras horas e 6400 ml de ringer lactado nas 12 horas\nsubsequentes.","E":"1600 ml de ringer lactado nas 8 primeiras horas e 1600 ml de ringer lactato nas 16 horas\nsubsequentes."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-202754","number":"202754","sourceNumber":"202754","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A.C. S., masculino, 78 anos, apresenta-se em ambulatório de urologia queixando-se de\ndesconforto testicular vago associado à dor eventual de início há aproximadamente 3 meses, e\npiora progressiva dos sintomas. Ao exame físico evidencia-se a presença de veias testiculares\ndilatadas e tortuosas, com desconforto à palpação. A ultrassonografia de bolsa testicular confirma a\npresença de varicocele. Qual a melhor conduta frente a esse paciente?","options":{"A":"Ultrassonografia de abdome total.","B":"Analgesia, uso de flebotômicos e retorno em 2 meses.","C":"Ligadura cirúrgica das veias espermáticas internas dilatadas.","D":"Cistoscopia de urgência.","E":"Tomografia computadorizada de abdome total."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-199620","number":"199620","sourceNumber":"199620","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em pacientes queimados, as queimaduras de vias aéreas são graves e aumentam o\níndice de morte. O que indica a necessidade de intubação orotraqueal no paciente queimado?","options":{"A":"Relato do paciente que queimou as vias aéreas sem sinais ou sintomas.","B":"Ocorrência de queimaduras maiores que 30% da superfície corporal.","C":"Ocorrência de queimaduras no pescoço.","D":"Ocorrência de eritema e edema da orofaringe na visualização direta."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-199596","number":"199596","sourceNumber":"199596","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente com quadro de dor lombar de forte intensidade, de início agudo, foi atendido\nna unidade de urgência. Feito analgesia e\nsolicitada uma tomografia computadorizada de abdome\ntotal que evidenciou a presença de um cálculo ureteral proximal de 5 mm com hidronefrose a\nmontante. Todas as situações a seguir têm indicação de remoção aguda do cálculo, EXCETO:","options":{"A":"Indicação social (por exemplo: piloto de avião).","B":"Dor intratável.","C":"Obstrução em paciente com rim único.","D":"Cálculo de oxalato de cálcio."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-199546","number":"199546","sourceNumber":"199546","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre cicatrização de feridas é CORRETO afirmar:","options":{"A":"Todas as três fases da cicatrização das feridas (fase inflamatória, fase proliferativa e fase de\nmaturação ou remodelamento) podem ocorrer simultaneamente, e as fases podem se sobrepor\ncom seus processos individuais.","B":"Os macrófagos surgem na ferida antes mesmo dos polimorfonucleares e atuam orquestrando a\nliberação de citocinas.","C":"A fase de maturação ou remodelamento é responsável pela angiogênese e produção da matriz\nextracelular provisória.","D":"Infecção, diabetes mellitus, período da infância, desnutrição e radioterapia são fatores que\ninibem a cicatrização de feridas."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-199550","number":"199550","sourceNumber":"199550","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Durante o stress cirúrgico, todos os seguintes hormônios apresentam secreção\naumentada, exceto:","options":{"A":"Cortisol.","B":"Aldosterona.","C":"Glucagon.","D":"Insulina."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-188017","number":"188017","sourceNumber":"188017","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Menino com 9 anos de idade é levado por sua mãe ao hospital devido dor abdominal,\nfalta de apetite, náusea, vômito e febre\naferida em 38,2°C nas últimas 48 horas. Exame físico\nabdominal com sensibilidade à palpação da fossa ilíaca direita. Hemograma com 14.000 leucócitos\ncom desvio à esquerda de neutrófilos. De acordo com o sistema de pontuação de Alvarado, qual é\na conduta adequada?","options":{"A":"Solicitar radiografia de tórax.","B":"Solicitar ultrassonografia de abdome total.","C":"Internação hospitalar para observação clínica.","D":"Antibioticoterapia endovenosa.","E":"Apendicectomia."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-174351","number":"174351","sourceNumber":"174351","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Qual o sinal clínico mais frequente associado à lesão de bexiga?","options":{"A":"Hematúria.","B":"Fratura de bacia.","C":"Crepitação em região supra-púbica.","D":"Oligúria.","E":"Polaciúria."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-172810","number":"172810","sourceNumber":"172810","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Menino de 5 anos é atendido no ambulatório de pediatria com história de dor abdominal\npélvica associada a palidez, irritabilidade, sudorese fria, hematúria e incontinência urinária. Mãe\nrelata episódio anterior de infecção urinária e uso frequente e prolongado de corticoide oral. O\ndiagnóstico mais provável é:","options":{"A":"Urolitíase.","B":"Infecção urinária.","C":"Adenite mesentérica.","D":"Disfunção vesical."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-187456","number":"187456","sourceNumber":"187456","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação às queimaduras é CORRETO afirmar:","options":{"A":"A fórmula de consenso de líquidos para as primeiras horas após a queimadura é de 2 a 4 ml\nRinger lactato X peso do corpo em Kg X % da área queimada. Nas primeiras oito horas após a\nlesão, ministrar 40 % do total calculado. Depois dar 30 % nas próximas oito horas, e 30 % nas oito\nhoras finais.","B":"Queimaduras de primeiro grau são queimaduras superficiais envolvendo somente a epiderme. A\npele apresenta-se vermelha e pouco sensível a dor.","C":"Queimaduras de segundo grau envolvem a epiderme e parte da derme. Apresentam-se\nbrancacentas, geralmente sem bolhas e sem edema. O\npaciente pode queixar-se de dor intensa\nporque os nervos sensoriais são parcialmente danificados.","D":"Queimaduras de primeiro e segundo grau são queimaduras de espessura parcial.","E":"Queimaduras de terceiro grau são queimaduras de espessura total que destroem as duas\ncamadas da pele e possuem aparência que pode\nser esbranquiçada ou enegrecida. São\nextremamente doloridas na área queimada."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-187461","number":"187461","sourceNumber":"187461","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente 32 anos internada por abdome agudo isquêmico, encontrase estável na\nenfermaria hospitalar, em terceiro dia de\npós-operatório de enterectomia extensa (apenas 80cm de\nintestino delgado residual e mantendo-se com preservação total do cólon). Nesta fase, a CORRETA\nterapia nutricional deve ser:","options":{"A":"Nutrição oral exclusiva.","B":"Nutrição enteral exclusiva.","C":"Nutrição parenteral exclusiva.","D":"Nutrição oral, enteral, parenteral associadas.","E":"Paciente não necessita de suporte nutricional."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-172791","number":"172791","sourceNumber":"172791","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"J.C.R., 18 anos, 80 Kg, vítima de queimaduras de 2° e 3° graus em todo membro\nsuperior direito, parede anterior de tórax e abdome. Deu entrada no Pronto Socorro acordado,\ncomunicativo, frequência cardíaca de 110 bpm, pressão arterial de 130/80 mmhg, eupneico,\ngemente de dor. Segundo fórmula de Parkland, qual seria a hidratação a ser realizada nas\nprimeiras 8 horas?","options":{"A":"8640ml de cristaloide.","B":"4320ml de colóide.","C":"5760ml de cristaloide.","D":"4320ml de cristaloide."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-172802","number":"172802","sourceNumber":"172802","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre cicatrização de feridas é correto afirmar, exceto:","options":{"A":"Na fase reativa, os macrófagos liberam proteinases que degradam a matriz extracelular e são\ncruciais para a remoção de material estranho.","B":"Os neutrófilos são as primeiras células a migrarem para a ferida, participando da fase\nproliferativa.","C":"A função primária dos fibroblastos é sintetizar colágeno, que começam a produzir durante a fase\ncelular da inflamação.","D":"Após a fase maturacional, em comparação a pele não ferida, a resistência à tração é de apenas\n30%."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-172812","number":"172812","sourceNumber":"172812","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação à fisiopatologia das úlceras de decúbito é correto afirmar:","options":{"A":"A pressão exercida sobre uma proeminência óssea é o principal fator fisiopatológico.","B":"Baixas pressões por períodos longos, são menos danosas do que altas pressões por períodos\ncurtos.","C":"Os cuidados de higiene e suporte nutricional não são importantes na prevenção das úlceras","D":"Colchões do tipo \"casca de ovo\" são os fatores mais importantes na prevenção das úlceras de\ndecúbito."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-172819","number":"172819","sourceNumber":"172819","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação às queimaduras químicas, podemos afirmar, EXCETO:","options":{"A":"Queimaduras por ácidos são mais graves que queimaduras por álcalis.","B":"A gravidade de queimadura tem relação com a concentração do agente e duração do contato.","C":"No tratamento, há necessidade de remoção do agente com irrigação contínua por pelo menos\n30 minutos.","D":"Deve-se evitar, no tratamento, o uso de agentes neutralizantes."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-162544","number":"162544","sourceNumber":"162544","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Homem, 60 anos, obeso, foi submetido a colectomia parcial por neoplasia de cólon. No\nsegundo dia pós-operatório foi necessária\nreabordagem cirúrgica devido à complicação\nhemorrágica. Encontra-se agora no 7º dia pós-operatório, clinicamente estável, porém em alto risco\nde bronco aspiração. Não foi iniciado nenhum suporte nutricional ao paciente, embora haja\nperistalse e a ileostomia esteja funcionante. Qual a conduta mais adequada neste caso?","options":{"A":"Manter infusão de soro glicosado e sem dieta.","B":"Posicionar uma sonda nasogástrica e iniciar nutrição enteral hiperproteica.","C":"Iniciar dieta líquida de prova, conforme aceitação, com cabeceira elevada, associada à infusão\nde soro glicosado a 5%.","D":"Instalar um acesso venoso central para iniciar nutrição parenteral total.","E":"Posicionar sonda nasojejunal e iniciar nutrição enteral."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-155388","number":"155388","sourceNumber":"155388","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Na resposta endócrino-metabólica ao trauma, pode-se afirmar que:","options":{"A":"O hormônio antidiurético está reduzido.","B":"O cortisol está reduzido.","C":"A glicogenólise está reduzida.","D":"A gliconeogênese está elevada.","E":"A liberação de catecolaminas séricas está reduzida."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-149151","number":"149151","sourceNumber":"149151","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A melhor conduta para um paciente com desnutrição leve a ser submetido a uma\ngastrectomia total para tratamento de câncer gástrico é?:","options":{"A":"Nutrição parenteral total no pré-operatório.","B":"Operar imediatamente e iniciar dieta enteral no primeiro dia de pós-operatório.","C":"Operar o paciente e iniciar dieta somente após 72 horas da cirurgia devido riscode fístulas com a\ndieta precoce.","D":"Iniciar nutrição parenteral total no primeiro dia de pós-operatório e dieta enteral após 72\nhoras.","E":"Iniciar nutrição enteral e parenteral em paciente por uma semana antes da cirurgia."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-155490","number":"155490","sourceNumber":"155490","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente masculino, 32 anos, vítima de acidente automobilístico, foi submetido à\nlaparotomia exploradora com evidência de lesões\nhepáticas, cinco lesões próximas em íleo terminal\ne uma lesão em cólon transverso. Foi submetido à hepatorrafia, enterectomia com anastomose\nprimária em íleo terminal e rafia da lesão colônica. No segundo dia pós-operatório, o paciente\nevidenciou-se febre de 38,8°C. Qual a causa mais provável da febre?","options":{"A":"Infecção de ferida operatória.","B":"Coleperitônio.","C":"Atelectasia.","D":"Deiscência anastomótica.","E":"Lesão duodenal despercebida."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-155411","number":"155411","sourceNumber":"155411","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente internado na UTI com pancreatite grave por hipertrigliceridemia, há 72 horas\ninstável hemodinamicamente, dependo de elevada dose de norepinefrina e vasopressina em\ninfusão contínua, apresentando-se com elevação de pressão-intra-abdominal, porém sem síndrome\ncompartimental. Sondagem nasogástrica com drenagem de 1200 ml em 12 horas. Qual a via de\nnutrição adequada neste momento?","options":{"A":"Nutrição zero.","B":"Nutrição oral.","C":"Nutrição enteral oligomérica.","D":"Nutrição parenteral sem lipídio.","E":"Nutrição parenteral com lipídio."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-155422","number":"155422","sourceNumber":"155422","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Durante a realização de procedimento de retosigmoidectomia foi observado lesão\ncompleta do ureter distal esquerdo, distando cerca de 3,0 cm da bexiga. Neste caso qual deverá\nser a melhor conduta:","options":{"A":"Ureteroureteroanastomose termino ? terminal.","B":"Ligadura do coto ureteral proximal e realização de nefrostomia. Programação de correção\ndefinitiva da lesão em um segundo tempo.","C":"Realizar Ureterocistoneostomia.","D":"Realizar correção da lesão com interposição de segmento de intestino delgado.","E":"Anastomose do coto ureteral lesado lateralmente com o ureter contralateral\n(transuretero-ureteroanastomose)."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-155426","number":"155426","sourceNumber":"155426","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um importante contribuinte para mortalidade precoce em queimaduras é o\nenvenenamento por Monóxido de Carbono\ndecorrente de inalação de fumaça. Sabemos que sua\nafinidade para a Hemoglobina é maior que o Oxigênio, o que pode levar à anóxia e à morte pelo\ndecréscimo dos níveis de hemoglobina oxigenada. A afinidade do Monóxido de Carbono para a\nHemoglobina é:","options":{"A":"2 a 5 vezes maior que o oxigênio.","B":"20 a 50 vezes maior que o oxigênio.","C":"200 a 250 vezes maior que o oxigênio.","D":"1000 vezes maior que o oxigênio.","E":"2000 vezes maior que o oxigênio."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-155339","number":"155339","sourceNumber":"155339","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre a cicatrização das feridas podemos afirmar que, EXCETO:","options":{"A":"As primeiras células a migrarem para uma ferida são os leucócitos polimorfonucleares, com pico\nem 24 a 48 horas.","B":"A força de tração de uma ferida nunca se iguala à força tensil de um tecido não lesionado.","C":"Existem 18 tipos de colágenos no corpo humano. Os 2 tipos mais importantes na cicatrização\ndas feridas são os tipos I e III.","D":"A camada intestinal com maior importância na cicatrização de uma anastomose é a submucosa.","E":"A fase da cicatrização mais afetada pelos corticosteroides é a fase de maturação e remodelação\nda cicatriz."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-148562","number":"148562","sourceNumber":"148562","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A inflamação sistêmica é mediada por diversos fatores, entre eles a Interleucina 1\n(IL-1), que desencadeia mais comumente as alterações abaixo, exceto:","options":{"A":"Febre.","B":"Anorexia.","C":"Ativação da cascata de coagulação.","D":"Neutrofilia.","E":"Hipercortisolemia."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-127165","number":"127165","sourceNumber":"127165","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente do sexo feminino, 19 anos, se apresenta no pronto-socorro queixando-se de\ndor intensa no membro inferior esquerdo, de\ninstalação súbita, evoluindo sem alívio há 3 horas. A\ndor se assemelha à constrição, não varia de intensidade com mudança da posição da extremidade,\ntem localização predominante na panturrilha, mas afeta proximal e distalmente. Refere diminuição\ndiscreta da percepção tátil. Também é observada diminuição discreta na temperatura, aumento do\nvolume de extremidade sem sinais de edema, panturrilha firme, lenhosa, dolorida, grande defesa\nantálgica à dorso, flexão do pé, pulso pedioso e tibial posterior presentes; discreta cianose do pé,\nmais acentuada nos pododáctilos. O diagnóstico mais provável é:","options":{"A":"Hematoma subaponeurótico.","B":"Obstrução arterial aguda.","C":"Cisto de Backer roto.","D":"Trombose venosa profunda aguda.","E":"Miosite aguda."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-127184","number":"127184","sourceNumber":"127184","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"São condições clínicas que aumentam o risco de infecção no pós-operatório, exceto:","options":{"A":"Corticoterapia.","B":"Obesidade.","C":"Hipocolesterolemia.","D":"Hipoxemia.","E":"Hipercolesterolemia."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-127190","number":"127190","sourceNumber":"127190","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"São condições que necessitam de avaliação pré-operatória um dia antes da realização\nda cirurgia, exceto:","options":{"A":"Obesidade com IMC maior do que 30.","B":"Internação nos últimos dois meses por condição clínica aguda ou piora de uma condição crônica.","C":"História de coronariopatia, infarto agudo do miocárdio.","D":"Asma que requer medicação crônica.","E":"Tumor de vias aéreas superiores."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-127201","number":"127201","sourceNumber":"127201","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Quanto as características dos fios cirúrgicos é incorreto afirmar:","options":{"A":"Prolene não esta sujeito a degradação ou enfraquecimento pela ação de enzimas teciduais.","B":"FDS II (polimero de poliéster), após degradação, 70% permanecem duas ou mais semanas nos\ntecidos.","C":"Ethilon-nylon é monofilamentar, não sofre hidrólise progressiva e não perde força tênsil com o\npassar do tempo.","D":"Nurulon-nylon trançado sofre hidrólise progressiva e perde força tênsil com o passar do tempo.","E":"Vicryl revestido, após degradação, 75% permanecem duas ou mais semanas nos tecidos."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-102729","number":"102729","sourceNumber":"102729","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"São medidas usadas no tratamento local de infecções superficiais do sítio cirúrgico,\nEXCETO:","options":{"A":"Calor local.","B":"Abertura de ferida.","C":"Retirada do corpo estranho.","D":"Uso de antibiótico sistêmico."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-102731","number":"102731","sourceNumber":"102731","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"São causas menos frequentes de febre no pós-operatório:","options":{"A":"Pneumonia.","B":"Infecção urinária.","C":"Embolia pulmonar.","D":"Infecção do sítio cirúrgico."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-102734","number":"102734","sourceNumber":"102734","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Estão associadas ao aumento de deiscência de uma sutura de parede abdominal,\nEXCETO:","options":{"A":"Presença de ascite.","B":"Presença de icterícia.","C":"Fechar o ferimento com sutura contínua.","D":"Passar um estoma através da incisão."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-102738","number":"102738","sourceNumber":"102738","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação às fístulas anastomóticas, é INCORRETO afirmar que:","options":{"A":"O uso de corticoide diminui a inflamação e o risco de aparecimento das fístulas.","B":"Em geral apresentam fechamento espontâneo de 4 a 6 semanas.","C":"A peritonite com irritação peritoneal deve ser tratada com cirurgia imediata.","D":"A obstrução distal à fístula favorece a manutenção do trajeto fistuloso."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-102736","number":"102736","sourceNumber":"102736","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação à cirurgia do paciente idoso e às alterações fisiológicas de envelhecimento,\né INCORRETO afirmar que:","options":{"A":"No idoso, ocorre aumento da rigidez torácica e diminuição da função ciliar, predispondo ao\naumento de infecção respiratória pós-operatória.","B":"O figado sofre inúmeras alterações com o envelhecimento, acarretando perda importante da\nreserva e função hepática.","C":"No idoso, o intestino delgado apresenta progressiva redução na altura das vilosidades,\nprejudicando a absorção de gorduras e carboidratos.","D":"Os idosos são dependentes da pré-carga, por isso a hipovolemia e estados hipermetabólicos,\ncomuns no perioperatório, podem ser mal tolerados\npor esses pacientes."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-106381","number":"106381","sourceNumber":"106381","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Um paciente adulto jovem é encaminhado à UTI após complicações de uma\ncolecistectomia laparoscópica eletiva. Ele apresenta\ntemperatura de 40,5°C, taquicardia,\nhipotensão arterial e rigidez muscular difusa. Qual dos medicamentos abaixo deve ser administrado\nimediatamente?","options":{"A":"Paracetamol.","B":"Dantrolene.","C":"Haloperidol.","D":"Hidrocortisona.","E":"Ibuprofeno."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-106463","number":"106463","sourceNumber":"106463","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O reparo laparoscópico das hérnias inguinais é um método de reparo livre de tensão\nbaseado na abordagem pré peritoneal.\nDurante a abordagem laparoscópica de uma hérnia inguinal,\no nervo com maior risco de ser lesado é o:","options":{"A":"Gênito-femoral em seu ramo genital.","B":"Ilioinguinal.","C":"Ilio-hipogástrico.","D":"Cutâneo femoral lateral.","E":"Femoral."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-100971","number":"100971","sourceNumber":"100971","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Quanto a necessidade de repetição da antibioticoprofilaxia durante o ato cirúrgico,\nmarque a alternativa CORRETA:","options":{"A":"Paciente super obeso, com Índice de Massa Corpórea (IMC) maior que 50.","B":"Situações em que ocorre hemorragia maciça > 1,5 litros em adultos.","C":"Quando o tempo da cirurgia é maior que uma hora.","D":"Toda cirurgia com uso de prótese.","E":"Toda cirurgia com uso de prótese, no momento da colocação da prótese."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-111648","number":"111648","sourceNumber":"111648","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente de 72 anos, portador de hérnia inguinal direita recidivada, foi submetido à\nhernioplastia laparoscópica com aposição de tela. São motivos para a realização de\nantibioticoprofilaxia","options":{"A":"idade, cirurgia laparoscópica e hérnia recidivada","B":"uso de tela, cirurgia laparoscópica e idade","C":"hérnia recidivada, uso de tela, cirurgia laparoscópica","D":"idade e uso de tela"},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-88840","number":"88840","sourceNumber":"88840","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Em relação à hérnia crural, assinale a alternativa INCORRETA:","options":{"A":"É classificada (NIHUS) como tipo IIIc.","B":"Se encarcerar, devemos tentar redução até no máximo 12 horas, desde que não haja sinais de\nestrangulamento. Se não houver êxito, operar.","C":"Se estiver estrangulada, deve ser operada imediatamente.","D":"Seu tratamento cirúrgico clássico é a técnica de McVay.","E":"A via laparoscópica (intra ou extraperitoneal) pode tratar esse tipo de hérnia."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-87381","number":"87381","sourceNumber":"87381","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Homem, 50 anos, busca serviço médico com queixa de dor abdominal intensa, de início\nsúbito há 2 horas. Ao exame físico, apresenta dor à palpação difusa de abdome, com defesa\ninvoluntária. Sem história de patologias prévias. Assinale a alternativa correta quanto ao caso\nclínico descrito.","options":{"A":"O achado radiológico de pneumoperitônio indica necessidade de realização de tomografia\ncomputadorizada de abdome para confirmação diagnóstica.","B":"Pneumoperitônio à radiografia simples de abdome, autoriza uma laparotomia exploradora.","C":"Toma-se mandatório a realização do lavado peritoneal diagnóstico ou do FAST (Focused\nAssessment with Sonography for Trauma) frente à suspeita de úlcera péptica perfurada.","D":"A hipótese de úlcera péptica perfurada não deve ser levantada na ausência de sintomas\ndispépticos anteriores.","E":"A hipótese de úlcera péptica perfurada pode ser descartada na presença de amílase sérica\naumentada em duas vezes o valor de referência."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-77372","number":"77372","sourceNumber":"77372","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente 66 anos, com história de estenose aórtica moderada em ecocardiograma\nrealizado no ano de 2011, deu entrada no\npronto-socorro do HECI em setembro de 2013 em\nedema agudo de pulmão grave, foi entubada após sedação com midazolam fentanil e transferida\nao CTI. No CTI, foi medicada com diuréticos e anti-hipertensivos, foi mantida sob sedação apenas\ncom propofol, repetido ecocardiograma mostrando agora estenose aórtica grave. Após melhora\nsignificativa da radiografia de tórax, cerca de 36 horas da admissão, foi suspensa sedação com\ndespertar imediato, porém devido à agitação psicomotora, foi extubada sem a realização do teste\nde respiração espontânea. Logo após, e devido extrema agitação psicomotora, hipertensão (210 x\n100) e taquicardia sinusal (150 bpm), apresentou recidiva do edema pulmonar, sendo reentubada.\nNovamente medicada e sedada com propofol, sendo acrescido risperidona para controle da\nagitação psicomotora apresentada. Nesse mesmo dia da reintubação, e devido mudança do\naspecto secreção pulmonar, foi colhida cultura de aspirado traqueal. Um dia após, iniciou febre.\n\nDois dias após, resultado da cultura do aspirado com S. aureus multissensível sendo iniciado\nOxacilina. Nesse mesmo dia a febre permaneceu\nconstante, elevada, em torno de 39,5/40 graus,\nacompanhada de tremores generalizados, refratária ao tratamento antitérmico e compressas de\ngelo. Manteve esse mesmo padrão de febre persistente após 48 horas de antibiótico,\nacompanhado ainda de labilidade pressórica significativa, leucocitose de 35000 com PCR de 60 e\nalteração leve de TGO e TGP. Hipótese diagnóstica e causa de refratariedade da febre?:","options":{"A":"Sinusite grave e otite média relacionadas ao uso da sonda nasoentérica. Necessidade de\nretirada da sonda e medidas locais para drenagem.","B":"Endocardite infecciosa com abscesso paravalvar. Necessidade de cirurgia cardíaca e retirada do\nfoco de infecção.","C":"Endocardite fúngica evoluindo com aneurisma micótico cerebral e consequente febre de origem\ncentral.","D":"Síndrome Neuroléptica Maligna relacionada ao uso de risperidona.","E":"Resistência in vivo à Oxacilina e provável infecção associada por Gram-negativo. Trocar\n\noxacilina por vancomicina e associar meropenem."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-88861","number":"88861","sourceNumber":"88861","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente submetido à colectomia parcial por videolaparoscopia, apresenta, na sala de\nrecuperação, sangramento vivo e abundante pelo dreno abdominal. A primeira hipótese a ser\navaliada seria:","options":{"A":"Integridade vascular.","B":"Hipotermia.","C":"Reação transfusional.","D":"Coagulação vascular disseminada.","E":"Septicemia."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-88864","number":"88864","sourceNumber":"88864","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O uso de prótese na cirurgia para hérnia inguinal corresponde à técnica de:","options":{"A":"Lichtenstein.","B":"Marcy.","C":"Bassini.","D":"Shouldice-Barrini.","E":"McVay-Lotheissen"},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-88866","number":"88866","sourceNumber":"88866","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A atrofia testicular após cirurgia de hérnia inguinal é secundária a:","options":{"A":"ligadura inadvertida da artéria testicular.","B":"torção inadvertida do testículo.","C":"constrição do anel inguinal profundo.","D":"orquite reacional à tela de reforço.","E":"manipulação cirúrgica."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-77365","number":"77365","sourceNumber":"77365","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Acerca da gastrectomia total para o tratamento do câncer gástrico:","options":{"A":"É rarissimamente utilizada, pois não oferece vantagem sobre a gastrectomia subtotal e ainda\napresenta um número muito superior de complicações.","B":"As complicações locais da cirurgia são bastante incomuns e estão relacionadas ao erro na\nrealização da técnica cirúrgica invariavelmente.","C":"A deiscência da anastomose esofagojejunal é uma complicação grave e de elevada mortalidade.","D":"É considerada uma cirurgia de baixa complexidade, podendo ser portanto rotineiramente\nrealizada em hospitais de baixa complexidade,\naumentando assim a possibilidade de acesso ao\nprocedimento para o grande número de portadores de neoplasia gástrica.","E":"Das complicações clínicas, a respiratória é a mais rara, porém, a de maior mortalidade."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-77327","number":"77327","sourceNumber":"77327","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Para um paciente com colecistite aguda litiásica não complicada:","options":{"A":"A tomografia de abdome é o melhor e ideal exame para confirmação diagnóstica.","B":"A colecistectomia geralmente não é necessária e não oferece benefícios em relação ao\ntratamento exclusivamente clínico e com antibióticos.","C":"O uso de antibióticos é desnecessário e a cirurgia deve ser imediata.","D":"A colecistectomia deve ser realizada preferencialmente na mesma internação após o início de\nantibióticos e a estabilização clínica.","E":"O antibiótico de escolha é a cefalotina."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-77515","number":"77515","sourceNumber":"77515","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"AJG, 17 anos, é submetido à cirurgia de emergência em Hospital de uma cidade vizinha\nquando foi realizado enterectomia com entero-entero anastomose. Evoluiu no 5°dia de\n\npós-operatório com dor abdominal localizada em mesogástrio com saída de secreção com aspecto\ndigestivo em ferida cirúrgica. Foi tratado de maneira conservadora e evoluiu com diminuição da dor,\nmas com orifício em ferida operatória com saída de secreção digestiva, caracterizando uma fístula\ndigestiva. Neste momento, o paciente é transferido para seu hospital. São fatores que podem\ninterferir no fechamento espontâneo de uma fístula gastrointestinal, exceto:","options":{"A":"Quando a fístula apresenta obstrução distal e a fístula é > 2 cm.","B":"Quando o paciente apresenta abscesso local associado à fístula ou outro sítio de infecção\nremota.","C":"Quando o paciente apresenta doença intestinal associada e o paciente é diabético.","D":"Quando a fístula apresenta múltiplos orifícios de drenagem e depende da origem da fístula.","E":"Quando a fístula tem epitelização da extensão mucocutânea e a fístula é de alto débito."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-77544","number":"77544","sourceNumber":"77544","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Fios de sutura cirúrgica são materiais utilizados para aproximar tecidos incisados\ncirurgicamente ou lacerados em traumatismos. Sobre a natureza dos fios cirúrgicos abaixo,\nassinale a alternativa mais adequada:","options":{"A":"Categute cromado, origem animal, monofilamentar, inabsorvível.","B":"Poliéster, origem sintética, monofilamentar, inabsorvível.","C":"Poliglactina, origem sintética, multifilamentar, absorvível.","D":"Seda, origem animal, multifilamentar, absorvível.","E":"Polidioxanone, origem sintética, multifilamentar, inabsorvível."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-77601","number":"77601","sourceNumber":"77601","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"TAT, 28 anos, mulher, portadora de hérnia femoral direita redutível. A melhor técnica\noperatória para a doente em questão, entre as abaixo, é:","options":{"A":"Operação de Bassini.","B":"Operação de McVay.","C":"Operação de Stoppa.","D":"Operação de Lichtenstein.","E":"Operação de Andrews I."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-59050","number":"59050","sourceNumber":"59050","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A cirurgia laparoscópica proporcionou verdadeira revolução na cirurgia geral e do\naparelho digestivo. Através de menor trauma\ncirúrgico, os doentes têm recuperação mais rápida e\nefeito cosmético melhorado. Assinale a alternativa incorreta, em relação às operações\nlaparoscópicas:","options":{"A":"Pressões abdominais entre 15 e 18 mmHg são efetivas na expansão abdominal e\ndistanciamento da parede abdominal das\nestruturas vasculares. Instaladas de forma transitória são\nseguras e com pequena repercussão orgânica.","B":"O pneumoperitônio diminui a expansibilidade pulmonar, motivo pelo qual é mais comum a\nocorrência de atelectasia pulmonar e\nredução da capacidade vital após operações laparoscópicas,\nem relação às laparotômicas.","C":"A realização do pneumoperitônio está contraindicada na presença de cateter de derivação\nventrículo-peritoneal.","D":"A perda ou diminuição da sensação tátil é uma das desvantagens que ocorre no método\noperatório videolaparoscópico.","E":"As operações videolaparoscópicas, em geral, apresentam menores índices de infecção de sítio\ncirúrgico, em relação às operações laparotômicas."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-43330","number":"43330","sourceNumber":"43330","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre a prevenção do tromboembolismo venoso (TVP) marque a alternativa\nINCORRETA:","options":{"A":"A incidência de TVP confirmada em pacientes hospitalizados, no pós-operatório de grandes\ncirurgias ortopédicas, sem a adequada tromboprofilaxia, pode chegar até 40-60% dos casos.","B":"O critério de escolha que deve ser usado para selecionar a estratégia de tromboprofilaxia é o\ntipo de cirurgia que será realizada.","C":"A aspirina nunca deve ser isoladamente para profilaxia da TVP em nenhum grupo de pacientes.","D":"Para pacientes submetidos à cirurgia geral de baixo risco, como procedimentos de pequeno\nporte e que não tenham outros fatores de\nrisco para TVP, recomenda-se somente a deambulação\nprecoce e frequente.","E":"Usar primeiramente a tromboprofilaxia mecânica (ex: meias de compressão pneumática) em\npacientes com alto risco de sangramento."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-43939","number":"43939","sourceNumber":"43939","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"As vantagens da cirurgia videolaparoscópia incluem, exceto:","options":{"A":"Menor dor pós-operatória devido às menores incisões.","B":"Redução das taxas de infecção de ferida, pois apresentam menor espaço morto.","C":"Retorno precoce às suas atividades.","D":"Maior incidência de hérnias incisionais, já que, por apresentar incisões pequenas, a aponeurose\nse torna difícil de ser fechada.","E":"Alta precoce."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-43332","number":"43332","sourceNumber":"43332","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Marque a alternativa INCORRETA sobre as alternativas listadas abaixo relacionadas às\nrecomendações para avaliação pré-operatória:","options":{"A":"O eletrocardiograma deve ser realizado de rotina, mesmo em indivíduos jovens assintomáticos\nno pré-operatório de procedimentos de baixo risco.","B":"A radiografia de tórax deve ser realizada em intervenções de grande porte, principalmente para\nas cirurgias intratorácicas e intra-abdominais.","C":"A realização de exames de coagulação não deve ser realizada rotineiramente em pacientes\nassintomáticos.","D":"A realização de exames de coagulação deve ser realizada no pré-operatório de cirurgias de\ngrande porte.","E":"O ecocardiograma deve ser realizado no pré-operatório de pacientes submetidos à operações de\nalto risco."},"answer":"E","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-43956","number":"43956","sourceNumber":"43956","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"No tocante à classificação das operações quanto ao grau de contaminação,\ncolecistectomia de urgência por videocirurgia\ndevido colecistite aguda necrotizante; colectomia\nesquerda eletiva com preparo intestinal apropriado; herniorrafia epigástrica e cirurgia bariátrica\nmista por vídeo, são classificadas como:","options":{"A":"Contaminada, limpa, potencialmente contaminada e limpa.","B":"Contaminada, potencialmente contaminada, limpa e potencialmente contaminada.","C":"Infectata, potencialmente contaminada, potencialmente contaminada e limpa.","D":"Infectada, contaminada, potencialmente contaminada e limpa.","E":"Infectada, potencialmente contaminada, limpa e potencialmente contaminada."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-43339","number":"43339","sourceNumber":"43339","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Algumas comorbidades requerem abordagens específicas no pré, per e pós-operatório.\nMarque a alternativa CORRETA dentre as\nafirmativas abaixo:","options":{"A":"Em procedimentos cirúrgicos na vigência de hipotireoidismo, deve ser realizada a profilaxia de\nhipotermia, a monitorização cardiovascular e a administração de hidrocortisona 100 mg a cada 8\nhoras pela chance de insuficiência adrenal.","B":"O metimazol, que além de inibir a síntese dos hormônios tireoideanos possui o benefício\nadicional de inibir a conversão periférica de\nT4 em T3 em doses altas, é o mais recomendado para\nuso no período perioperatório.","C":"Os pacientes portadores de feocromocitoma só podem ser operados depois de devidamente\ntratados com betabloqueadores e\nvasodilatadores.","D":"Os corticoides devem ser usados de rotina no pré-operatório de todos os indivíduos asmáticos.","E":"Em indivíduos obesos mórbidos candidatos a cirurgia bariátrica, o risco é maior naqueles\nportadores de mais comorbidades e mais idosos.\nO índice de massa corporal, por outro lado, não\ntem influência nas taxas de mortalidade."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-23087","number":"23087","sourceNumber":"23087","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"No tocante à classificação das operações quanto ao grau de contaminação, a\ncolecistectomia de urgência por videocirurgia devido colecistite aguda: a colectomia esquerda\neletiva com preparo intestinal: a derivação biliar em Y de Roux e a hernioplastia inguinal com tela\nde polipropileno, são classificadas como:","options":{"A":"contaminada, limpa, potencialmente contaminada e limpa.","B":"contaminada, contaminada, potencialmente contaminada e limpa.","C":"infectada, potencialmente contaminada, potencialmente contaminada e limpa.","D":"infectada, contaminada, potencialmente contaminada e limpa.","E":"infectada, potencialmente contaminada, potencialmente contaminada e potencialmente\ncontaminada."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-23089","number":"23089","sourceNumber":"23089","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"As infecções de sítio cirúrgico são mais frequentemente causadas pela microbiota do\npróprio doente. Entretanto, durante o período de 2003 a 2008, o Brasil vivenciou em dezenas de\nestados diversos surtos de infecções em sítio cirúrgico de operações realizadas por videocirurgia\ncausadas por microbactérias de crescimento rápido. Dentro desse contexto é correto afirmar que:","options":{"A":"As evidências de resistência da M. massiliense ao glutaraldeído em tempos de exposição de até\n10 horas, indicam que esse mecanismo pode ter tido papel decisivo na propagação dos surtos.","B":"Os surtos não tiveram relação entre si, pois apesar de quase todos os casos tratar-se de um\nmesmo clone de bactérias o país é enorme e\nnão hã como relacionar casos do Pará com casos do\nrio Grande do Sul.","C":"A autoclavação dos matérias garante a não sobrevivência da M. massiliense e a ausência de\nrisco de infecção operatória.","D":"O tratamento antimicrobiano da M. massiliense com Etambutol mostrou-se muito efetivo.","E":"A transmissão interpessoal pela não lavagem de mãos e não uso de máscaras propiciou a\ndisseminação do surto."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-23160","number":"23160","sourceNumber":"23160","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente com colecistite crônica deverá ser submetido à colecistectomia. Na consulta\npré-anestésica, o paciente fica sabendo que o seu risco cirúrgico é classificado como ASA II, qual o\nsignificado deste risco cirúrgico?","options":{"A":"Paciente apresenta a patologia cirúrgica (colecistite crônica), porém sem distúrbios\nfisiológicos,\nbioquímicos e psiquiátricos.","B":"Leve a moderado distúrbio fisiológico, controlado. Sem comprometimento da atividade normal. A\ncondição pode afetar a cirurgia ou anestesia.","C":"Distúrbio sistêmico importante, de difícil controle, com comprometimento da atividade normal e\ncom impacto sobre a anestesia e cirurgia.","D":"Leve a moderado distúrbio fisiológico, descontrolado. Com comprometimento da atividade\nnormal. A condição pode afetar a cirurgia ou anestesia.","E":"Desordem sistêmica severa, potencialmente letal, com grande impacto sobre a anestesia e\ncirurgia."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-354801","number":"354801","sourceNumber":"354801","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"As crianças representam 2 a 3% dos casos de litíase renal no Brasil. A principal causa\ndesta enfermidade é a","options":{"A":"hipocitratúria.","B":"hiperoxalúria.","C":"hipercalciúria.","D":"hiperuricosúria."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-363942","number":"363942","sourceNumber":"363942","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Os testes genéticos para avaliação de doenças oncológicas estão cada vez mais\ncomuns. As recomendações para testes genéticos de linha germinativa são para homens com:","options":{"A":"câncer de próstata (CaP) metastático.","B":"câncer de próstata (CaP) de baixo risco que têm um membro da família diagnosticado com CaP\nem idade < 60 anos.","C":"membros da família diagnosticados com câncer de próstata (CaP) com idade < 60 anos ou um\nmembro da família que morreu de CaP.","D":"história familiar com mutações de linha germinativa de moderado/alto risco ou história familiar\nde\nmúltiplos cânceres do mesmo lado da família."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-363941","number":"363941","sourceNumber":"363941","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Uma vez feito o diagnóstico de câncer de próstata (CaP), o passo subsequente na\ngrande maioria das vezes é o estadiamento da doença. É recomendado, no estadiamento,","options":{"A":"usar a ressonância magnética pré-biópsia para obter informações sobre estadiamento local nos\ncasos de CaP de risco intermediário.","B":"incluir exames de imagens abdominopélvicas transversais para os casos de CaP localizado de\nbaixo risco.","C":"incluir exames de imagens abdominopélvicas transversais e uma cintilografia óssea para triagem\nmetastática nos casos CaP de risco intermediário e ISUP grau 2 e 3.","D":"realizar triagem metastática, incluindo exame de imagens abdominopélvicas transversais e uma\ncintilografia óssea para os casos de CaP localizado de alto risco."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-355600","number":"355600","sourceNumber":"355600","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A incidência de queimaduras diminuiu nas últimas décadas, em virtude das medidas de\nprevenção. Crianças de até cinco anos pertencem ao grupo de maior risco, sendo os incêndios a\nprincipal causa de morte relacionada a queimaduras em crianças. Dentre as alternativas a seguir,\nindique aquela que está incorreta:","options":{"A":"Se o paciente tiver recebido uma ou nenhuma dose da vacina antitetânica, aplicar\nimunoglobulina antitetânica e imunização antitetânica seriada.","B":"Recomenda-se hospitalização das crianças com queimaduras elétricas/químicas e com\nqueimaduras de segundo grau, que acometam mais de 10% da superfície corpórea.","C":"Queimaduras por cigarro, queimaduras com líquido escaldante e imersão (limites bem definidos\nna extremidade) sugerem lesões intencionais e devem\nser notificadas.","D":"Nas queimaduras químicas extensas, deve-se remover a substância e irrigar com grande\nquantidade de água gelada por pelo menos 30 minutos.","E":"Deve-se instituir acesso venoso e ressuscitação hídrica em superfície corpórea queimada (SCQ)\nmaior de 15% ou menos em casos com evidências de inalação de fumaça."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-366974","number":"366974","sourceNumber":"366974","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Assinale a alternativa que defina corretamente a Varicocele:","options":{"A":"Uma condição benigna que não tem relação com a infertilidade masculina.","B":"Uma inflamação aguda do testículo.","C":"Uma dilatação das veias do plexo pampiniforme no escroto, que não afeta o cordão espermático.","D":"Uma dilatação das veias do cordão espermático que drena o testículo."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-362677","number":"362677","sourceNumber":"362677","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente 57 anos, sexo masculino, trabalhador rural, tabagista, queixa-se de hematúria\nindolor intermitente há cerca de 5 meses. Qual etiologia mais provável?","options":{"A":"Litíase urinária.","B":"Infecção do trato urinário.","C":"Neoplasia vesical.","D":"Neoplasia renal."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-354757","number":"354757","sourceNumber":"354757","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Durante o processo de cicatrização de feridas as citocinas desempenham diversos\nefeitos biológicos importantes. Qual citocina,\nsintetizada pelas células dendríticas e medula óssea,\naumenta a produção de plaquetas e inibe a proliferação de fibroblastos?","options":{"A":"Interleucina 11","B":"Interleucina 12","C":"Interleucina 13","D":"Interleucina 18"},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-354749","number":"354749","sourceNumber":"354749","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Dentre as fistulas enterocultâneas, qual tem a maior probabilidade de fechamento?","options":{"A":"Trajeto longo.","B":"Labiada.","C":"Próxima à pele.","D":"Próximal à obstrução."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-354793","number":"354793","sourceNumber":"354793","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Os tratamentos dos cálculos do trato urinário são determinados por muitos fatores,\ndentre eles, os mais importantes para a escolha\ndo tipo de tratamento são o tamanho e a posição\ndeste na via excretora. De acordo com estes dois fatores, qual é a indicação de tratamento?","options":{"A":"Se o cálculo mede 0,8 cm de diâmetro e se encontra no cálice superior, a indicação de litotripsia\nextracorpórea precede a de ureterorrenolitotripsia flexível que precede a de nefrolitotripsia.","B":"Se o cálculo mede 0,9 cm de diâmetro e se encontra no ureter distal, a indicação de litotripsia\nextracorpórea e ureterorrenolitotripsia flexível são igualmente adequadas.","C":"Se o cálculo mede 1,5 cm de diâmetro e se encontra no cálice inferior, a indicação de litotripsia\nextracorpórea e ureterorrenolitotripsia flexível são igualmente adequadas e precedem a de\nnefrolitotripsia percutânea, desde que na ausência de fatores desfavoráveis para litotripsia\npercutânea.","D":"Se o cálculo mede 2,3 cm de diâmetro e se encontra na pelve renal, a indicação de\nnefrolitotripsia percutânea precede a de\nureterorrenolitotripsia que, por sua vez, precede a de\nlitotripsia extracorpórea."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-354792","number":"354792","sourceNumber":"354792","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Os cálculos ureterais podem causar espectros diferentes de sintomas ou problemas ao\ntrato urinário. Em alguns casos, é possível realizar tratamento conservador e aguardar a eliminação\ndo cálculo. A observação de cálculos ureterais é viável em pacientes informados e com","options":{"A":"dor na lombar direita associada a náuseas e vômitos controlada com analgésicos e antieméticos,\ntomografia demonstrando cálculo ureteral distal de 8 mm à direita sem ureterohidronefrose, exame\nsimples de urina demonstrando hemácias de 400 mil/mL leucócitos de 20 mil/mL, nitrito negativo e\ncreatinina de 1,1 mg/dL.","B":"dor na lombar direita e febre controladas com analgésicos e antipiréticos, tomografia\ndemonstrando cálculo ureteral proximal de 7 mm à\ndireita, com ureterohidronefrose leve a\nmoderada a montante, exame simples de urina demonstrando hemácias de 35 mil/mL, leucócitos\nde 150 mil/mL, nitrito positivo e creatinina de 0,8 mg/dL.","C":"dor na lombar com irradiação para flanco e bolsa testicular esquerda refratária a analgésicos\ncomuns e opiódes, tomografia demonstrando cálculo ureteral distal de 8 mm à esquerda, com\nureterohidronefrose leve a montante, exame simples de urina demonstrando hemácias de 180\nmil/mL, leucócitos de 15 mil/mL, nitrito negativo, creatinina de 1,6 mg/dL.","D":"dor em flanco e bolsa testicular esquerda, disúria, náuseas e vômitos controlados com\nanalgésicos comuns, opiódes e antieméticos,\ntomografia demonstrando cálculo ureteral distal de 4\nmm à esquerda, com ureterohidronefrose acentuada a montante, exame simples de urina\ndemonstrando hemácias de 70 mil/mL, leucócitos de 17 mil/mL, nitrito negativo, creatinina de 2,8\nmg/dL."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-342595","number":"342595","sourceNumber":"342595","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Marque a INCORRETA com relação a cicatrização das feridas:","options":{"A":"feridas agudas evoluem num processo cicatricial ordenado e cronológico","B":"o tecido de granulação aparece na fase proliferativa","C":"os tipos de fechamento são divididos em reparos primário, secundário, terciário e quaternário","D":"são fases da cicatrização: inflamação, proliferação e maturação"},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-321539","number":"321539","sourceNumber":"321539","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O uso da nutrição parenteral é vital para pacientes com disfunção completa ou parcial\ndo trato gastrointestinal. Usando o exemplo de\numa pessoa de 70 kg, sem alterações metabólicas\nimportantes, qual seria a melhor composição para uma nutrição parenteral total formulada com\nlipídeos (solução 3 em 1)?","options":{"A":"105g de aminoácidos, 370g de dextrose, 47g de lipídios.","B":"70g de aminoácido, 320g de dextrose, 30g de lipídios.","C":"56g de aminoácidos, 320g de dextrose, 140g de lipídios.","D":"140g de aminoácidos, 420g de dextrose, 140g de lipídios."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-321540","number":"321540","sourceNumber":"321540","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Os pacientes cirúrgicos com alterações nutricionais apresentam aumento de morbidade\ne mortalidade. O suporte nutricional deve ser\nconsiderado para todos os pacientes com risco\nnutricional grave. Qual deve ser o critério para iniciar suporte nutricional perioperatório?","options":{"A":"Perda involuntária maior que 5% do peso nos últimos 6 meses.","B":"Perda de sangue esperada maior que 500 mL durante a cirurgia.","C":"Concentração de Transferrina menor que 350 mg/dL.","D":"Previsão de que o paciente não poderá satisfazer os requisitos calóricos dentro de 3 a 5 dias."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-342600","number":"342600","sourceNumber":"342600","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Das alterações endócrinas seguintes, qual não é compatível com o pós-operatório de\numa cirurgia de grande porte?","options":{"A":"elevação dos níveis de cortisol sérico","B":"elevação da secreção de hormônio antidiurético","C":"queda nos níveis plasmáticos dos esteroides gonadais","D":"aumento da secreção de insulina"},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-321549","number":"321549","sourceNumber":"321549","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O componente mais comum dos cálculos urinários é o cálcio, que é constituinte\nprincipal de quase 80% das pedras. Oxalato de\ncálcio compõe cerca de 60% de todos os cálculos,\noxalato de cálcio misto e hidroxiapatita 20% e os cálculos de brushite 2%. Qual é a anormalidade\nmais comum identificada em formadores de cálculos de cálcio?","options":{"A":"Hipercalciúria.","B":"Hiperoxalúria.","C":"Hipocitratúria.","D":"Hiperuricosúria."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-331973","number":"331973","sourceNumber":"331973","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Homem, 55 anos, com diagnóstico de estenose pilórica por câncer gástrico, sem outras\ncomorbidades. Não consegue ingerir nada há seis dias, porcentagem de perda de peso de 18% em\n40 dias. Há quatro dias com hidratação venosa com cristaloides. Iniciado nutrição parenteral total.\nNo segundo dia, apresenta quadro de dispneia intensa, taquipneia com estertores crepitantes\ndifusos em ambos os pulmões, hipotensão arterial, arritmia cardíaca. Diagnosticado como edema\nagudo de pulmão, foi medicado com diurético venoso e morfina. Não obteve melhora, evoluindo\npara parada cardiorespiratória e óbito. A provável causa da morte deste paciente é:","options":{"A":"Arritmia cardíaca devido a síndrome de realimentação.","B":"Sepse por cateter venoso central.","C":"Pneumonia com sepse.","D":"Crise hipertensiva, falência cardíaca.","E":"Insuficiência supra renal aguda."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-334796","number":"334796","sourceNumber":"334796","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O sistema imunológico é composto por múltiplas linhagens celulares. Dentre elas, o\nneutrófilo desempenha um papel muito importante. Esse polimorfonuclear","options":{"A":"é recrutado ao fim do processo inflamatório, sendo a última célula recrutada.","B":"apresenta uma vida média de cerca de 20 horas, sendo mais curta nos processos inflamatórios.","C":"são produzidos no baço em resposta ao Fator Granulócito Colônia-estimulante.","D":"tem sua produção regulada pala interleucina (IL)17, entre outros."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-339788","number":"339788","sourceNumber":"339788","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Numa ferida em cicatrização, a presença de miofibroblastos indica a seguinte fase:","options":{"A":"Maturação.","B":"Proliferativa.","C":"Inflamatória.","D":"Exsudativa.","E":"Hipertrófica."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-334798","number":"334798","sourceNumber":"334798","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A angiogênese representa importante papel na cicatrização de feridas. Em seu\nprocesso há:","options":{"A":"redução na ativação de enzimas degradantes de matriz para manter o endotélio íntegro.","B":"aumento na expressão de moléculas como a integrina, para estimular migração celular.","C":"formação de arteríolas que vão alimentar o processo de cicatrização, já que o retorno venos se\ndará pelos linfáticos.","D":"prejuízo na sua atividade com a presença de IL-8 e ácido lático, elementos que inibem o\nprocesso."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-339790","number":"339790","sourceNumber":"339790","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Os pacientes cirúrgicos com alterações nutricionais apresentam aumento de morbidade\ne mortalidade. O suporte nutricional deve ser\nconsiderado para todos os pacientes com risco\nnutricional grave. Qual deve ser o critério para iniciar suporte nutricional perioperatório?","options":{"A":"Perda involuntária maior que 5% do peso nos últimos 6 meses.","B":"Perda de sangue esperada maior que 500 mL durante a cirurgia.","C":"Concentração de Transferrina menor que 350 mg/dL.","D":"Previsão de que o paciente não poderá satisfazer os requisitos calóricos dentro de 3 a 5 dias."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-346442","number":"346442","sourceNumber":"346442","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Criança de 11 anos, previamente hígida, trazida pelo SAMU resgatada de um incêndio\nna creche. Chega ao pronto socorro com quadro de\nestridor laríngeo e edema de face progressivo.\nÀ monitorização apresenta SatO? 91% com máscara de oxigênio não reinalante a 5 l/min. Qual a\nconduta mais adequada?","options":{"A":"Aumentar fluxo de máscara de oxigênio não reinalante para 15 l/min;","B":"Entubação orotraqueal imediatamente;","C":"Ventilação não invasiva;","D":"Observação clínica e corticoterapia."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-339794","number":"339794","sourceNumber":"339794","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"O componente mais comum dos cálculos urinários é o cálcio, que é constituinte\nprincipal de quase 80% das pedras. Oxalato de\ncálcio compõe cerca de 60% de todos os cálculos,\noxalato de cálcio misto e hidroxiapatita 20% e os cálculos de brushite 2%. Qual é a anormalidade\nmais comum identificada em formadores de cálculos de cálcio?","options":{"A":"Hipercalciúria.","B":"Hiperoxalúria.","C":"Hipocitratúria.","D":"Hiperuricosúria."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-334136","number":"334136","sourceNumber":"334136","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A terapia hiperbárica é uma alternativa no tratamento de ferida, e sua utilização é cada\nvez maior e muito utilizada em processos como\nrecuperação de enxertos de pele, resgate de\nretalhos, fasceite necrotizante e outras feridas crônicas. Sobre a terapia hiperbárica, assinale a\ncorreta:","options":{"A":"A vascularização da área alvo é dispensável, pois as pressões de oxigênio administradas na\ncâmara são infundidas nos tecidos por difusão.","B":"Os efeitos benéficos são imediatos, por isso na maioria dos protocolos são indicadas apenas\numa sessão, em qualquer tipo de lesão.","C":"O objetivo da terapia hiperbárica é reduzir a proliferação de fibroblastos, síntese de colágeno e\nmoderar a epitelização das feridas.","D":"São contraindicações à terapia: pneumotórax, uso atual ou recente de bleomicina e/ou\ndoxirrubicina, e tratamento com dissulfiram."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-346454","number":"346454","sourceNumber":"346454","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Os tipos histológicos mais frequentes dos tumores de próstata, bexiga e testículo são\nrespectivamente:","options":{"A":"Adenocarcinoma, Adenocarcinoma e Seminoma;","B":"Carcinoma de células transicionais, Adenocarcinoma e Coriocarcinoma;","C":"Carcinoma de células transicionais, Carcinoma de células transicionais e Carcinoma\nEmbrionário;","D":"Adenocarcinoma, Carcinoma de Células Transicionais e Seminoma."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-330111","number":"330111","sourceNumber":"330111","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"A cicatrização de feridas consiste em perfeita e coordenada cascata de eventos que\nculminam com a reconstituição tecidual. Considerando o tema, é CORRETO afirmar:","options":{"A":"A cicatriz hipertrófica ocorre predominantemente nos lóbulos da orelha e na região pré-esternal e\nnão há grande tendência de regredir após\ncirurgia de correção.","B":"A fase de remodelamento é caracterizada pela formação do tecido de granulação. Os\nfibroblastos e as células endoteliais são as células predominantes e mais importantes.","C":"A betaterapia é uma forma de tratamento que envolve a irradiação precoce da cicatriz e pode ser\nindicada a pacientes que já desenvolveram queloides em cicatrizes prévias.","D":"A cicatrização por segunda intenção ocorre quando as bordas da lesão são coaptadas logo após\no seu surgimento, por exemplo, por meio de\nsuturas."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-330112","number":"330112","sourceNumber":"330112","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação aos retalhos, é CORRETO afirmar:","options":{"A":"O subepidérmico é o grande responsável pela nutrição dos retalhos classificados como de\npadrão aleatório.","B":"O retalho é contraindicado para cobertura de áreas com exposição de estruturas nobres, como\nvasos e tendões.","C":"Os retalhos musculares possuem as seguintes classificações: Cormack-Lamberty e Mathes e\nNahai.","D":"Os angiossomos estão interligados por meio de anastomoses verdadeiras ou por vasos\nobstruídos."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-321594","number":"321594","sourceNumber":"321594","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"É característica da varicocele em crianças e adolescentes:","options":{"A":"apresentar aumento do volume escrotal com dor associada.","B":"ser mais frequente na fase pré-puberal.","C":"ser predominantemente unilateral e à esquerda.","D":"apresentar a confirmação de seu diagnóstico com radiografia contrastada das veias testiculares."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-295334","number":"295334","sourceNumber":"295334","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Durante a resposta inflamatória, qual a célula do sistema imune que fagócita e degrada\na proteína antígeno-derivada, carregando-a em um\ncomplexo maior de histocompatibilidade e a\napresenta ao linfonodo e baço?","options":{"A":"Célula macrófago.","B":"Célula B.","C":"Célula dentrítica.","D":"Célula T."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-313178","number":"313178","sourceNumber":"313178","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Quanto ao fechamento de laparotomia, a prevenção de hérnia incisional pós-operatória\né fundamental. Dentre os fatores a seguir, aquele\nque tem maior relevância é(são):","options":{"A":"as incisões transversas contra longitudinais","B":"o controle de níveis pressóricos","C":"o uso de fio inabsorvível","D":"o controle do nível de hemoglobina glicada"},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-314093","number":"314093","sourceNumber":"314093","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente paraplégico há 15 anos por PAF raquimedular, usuário de crack, deu entrada\nno pronto-socorro com queixa de calafrio e piora na\nescara sacral. Ao exame físico, apresentava-se\nconsciente, desorientado, taquipneico, desidratado 3+/4, com FC de 120 bpm e PA 100x70mmHg.\nÀ inspeção, observou-se hiperemia em todo perineo, com crepitação à palpação e escara\nacometendo a pele perianal, com necrose e fezes na ferida. Diante do quadro exposto, qual a\nmelhor conduta?","options":{"A":"Tomografia de abdome e pelve com triplo contraste.","B":"Debridamento em centro cirúrgico.","C":"Debridamento em centro cirúrgico e confecção de colostomia em alça.","D":"Debridamento em centro cirúrgico e confecção de colostomia terminal."},"answer":"B","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-317920","number":"317920","sourceNumber":"317920","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"No estado crítico pós-trauma, o metabolismo apresenta","options":{"A":"fase inicial, após as primeiras horas, caracterizada por alto consumo de oxigênio e altas\ntemperaturas.","B":"orientação no sentido de aumentar a produção de proteínas como albumina e transferrina.","C":"orientação para uso de proteínas corporais, principalmente dos músculos esqueléticos.","D":"tendência pelo uso da arginina como fonte preferencial de energia pelas células imunes."},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-313179","number":"313179","sourceNumber":"313179","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Com relação ao processo de cicatrização das feridas, é correto afirmar que:","options":{"A":"a liberação de histamina e serotonina, que provocam aumento da permeabilidade capilar, ocorre\nna fase maturacional","B":"a migração dos fibroblastos para a ferida independe da liberação de substâncias quimiotáticas","C":"os macrófagos surgem ao mesmo tempo em que os neutrófilos desaparecem e são\nresponsáveis pela |i beração de citocinas, que são indispensáveis para a cicatrização","D":"a angiogênese iniciada na fase inflamatória tem seu pico mediado pela produção de citrinas\npelos macrófagos e pelas plaquetas na fase de maturação da ferida"},"answer":"C","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-317921","number":"317921","sourceNumber":"317921","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Sobre a fase de epitelização da cicatrização de feridas sabe-se que:","options":{"A":"a zona de base da membrana é constituída por fibras que contêm colágeno tipo IV.","B":"inicia-se a partir do segundo dia pós-ferimento.","C":"apresenta células de migração que aproximam o tecido necrótico do tecido viável.","D":"após completar esta fase, podem ser encontradas células fusiformes recobrindo a cicatriz."},"answer":"A","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-316296","number":"316296","sourceNumber":"316296","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Estima-se que, no Brasil, ocorram em torno de 1.000.000 acidentes com queimaduras\npor ano. Destes, 100.000 pacientes procurarão\natendimento hospitalar e cerca de 2.500 irão falecer\ndireta ou indiretamente de suas lesões. Assinale qual paciente não possui indicação para\nencaminhamento para centro especializado em queimaduras.","options":{"A":"M.S.L, 18 anos, vítima de queimadura profunda, por chama direta em região anterior de braço,\ndireito, abdome e região períneal, após uma explosão ao usar álcool líquido para acender uma\nchurrasqueira.","B":"Paciente desconhecido, aproximadamente 45 anos, morador de rua, apresentando queimadura\nde segundo grau profundo em palma da mão\nesquerda, após higienizar as mãos com álcool em gel\ne se aproximar de uma fogueira.","C":"D.G.A, 35 anos, apresentando queimadura elétrica com acometimento de pé direito, após\nacidente de trabalho.","D":"M.J.A, 28 dias, apresentando queimadura de primeiro grau em região glútea após escaldadura\npor água quente."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-2-311891","number":"311891","sourceNumber":"311891","collectionBlock":"medcurso:medcurso-cirurgia-cir-2","collectionLabel":"Medcurso · CIR 2","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 2","subtopic":"","stem":"Paciente de 63 anos, sem comorbidades, apresenta sintomas severos do trato urinário\ninferior, graduado pelo IPSS, mesmo em uso de\nantagonista alfa-adrenérgico (tansulosina 0,4mg\npor dia) e inibidor de 5-alfa-redutase (dutasterida 0,5mg por dia), há mais de 12 meses. Traz PSA\ncom valor 2,5ng/mL, ultrassonografia de próstata via abdominal, demonstrando próstata de 56g\ncom resíduo pós-miccional grande e estudo urodinâmico apresentando obstrução infravesical. Ao\nexame do toque retal, a próstata apresenta-se fibroelástica, lisa e globosa. A conduta a ser tomada\né a de:","options":{"A":"manter tratamento clínico-farmacológico com ajuste de dose.","B":"solicitar biópsia transretal de próstata guiada por ultrassonografia.","C":"solicitar ressonância magnética de próstata.","D":"indicar ressecção transuretral de próstata."},"answer":"D","source":"Cirurgia/CIR 2/CIR 2.txt","sourceLabel":"Medcurso · CIR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
